# ── Runner ────────────────────────────────────────────────────────────────────

def _run_one(name: str, fn) -> tuple[str, str, str, float]:
    """Return (name, status, error, elapsed). status ∈ {"pass","fail","skip"}."""
    import time
    t = time.monotonic()
    try:
        fn()
        return (name, "pass", "", time.monotonic() - t)
    except SkipTest as e:
        return (name, "skip", str(e), time.monotonic() - t)
    except Exception as e:
        return (name, "fail", f"{type(e).__name__}: {e}", time.monotonic() - t)


def main():
    import time, argparse
    parser = argparse.ArgumentParser(description="OddsIntel smoke tests")
    parser.add_argument(
        "--filter", "-f", default=None,
        help="Run only tests whose name matches this substring (case-insensitive). "
             "Use this for a single new test locally — full suite is CI's job."
    )
    args = parser.parse_args()

    if args.filter:
        needle = args.filter.lower()
        registry = [(n, f) for (n, f) in _registry if needle in n.lower()]
        if not registry:
            print(f"No tests match filter: {args.filter}")
            sys.exit(1)
        print(f"Filter: {args.filter} → {len(registry)} test(s)")
    else:
        registry = _registry

    # SMOKE-SUITE-AUDIT 2026-09-01: warm the heavy scientific stack on ONE
    # thread before the pool starts.
    #
    # Tests run 8-wide, and several import modules that pull in scipy/sklearn
    # transitively. Python's import lock is per-module, so two threads taking
    # the FIRST import of different scipy submodules simultaneously can each
    # observe the other's half-built module — CI failed with
    # "cannot import name 'minkowski' from partially initialized module
    # 'scipy.spatial.distance' (most likely due to a circular import)".
    #
    # The race was always latent; adding behavioural tests that import
    # workers.jobs.* is what made it reachable. Fix it once here rather than
    # making every future test author think about import order. Failures are
    # swallowed deliberately: an environment without scipy should skip those
    # tests on their own terms, not die in the warm-up.
    for _warm in ("scipy.spatial.distance", "scipy.stats", "sklearn.linear_model",
                  "sklearn.calibration"):
        try:
            __import__(_warm)
        except Exception:
            pass

    t0 = time.monotonic()

    with ThreadPoolExecutor(max_workers=8) as pool:
        futures = {pool.submit(_run_one, name, fn): name for name, fn in registry}
        results = [f.result() for f in as_completed(futures)]

    elapsed = time.monotonic() - t0

    # Sort by original registration order for stable output
    order = {name: i for i, (name, _) in enumerate(_registry)}
    results.sort(key=lambda r: order.get(r[0], 9999))

    passed  = sum(1 for _, s, _, _ in results if s == "pass")
    failed  = sum(1 for _, s, _, _ in results if s == "fail")
    skipped = sum(1 for _, s, _, _ in results if s == "skip")

    print("\n" + "═" * 60)
    print("  OddsIntel Smoke Tests")
    print("═" * 60)

    _GLYPH = {"pass": "✓", "fail": "✗", "skip": "⊘"}
    _COLOR = {"pass": "\033[32m", "fail": "\033[31m", "skip": "\033[90m"}

    for name, status, error, t in results:
        glyph = _GLYPH[status]
        color_on = _COLOR[status]
        slow = f"  \033[33m({t:.1f}s)\033[0m" if t > 5 else ""
        print(f"  {color_on}{glyph}\033[0m  {name}{slow}")
        if status == "fail" and error:
            print(f"       \033[31m{error}\033[0m")
        elif status == "skip" and error:
            print(f"       \033[90m[skip] {error}\033[0m")

    print("═" * 60)
    slowest = sorted(results, key=lambda r: r[3], reverse=True)[:3]
    color = "\033[32m" if failed == 0 else "\033[31m"
    skip_suffix = f", {skipped} skipped" if skipped else ""
    print(f"  {color}{passed} passed, {failed} failed{skip_suffix}\033[0m  ({elapsed:.1f}s)")
    print(f"  Slowest: " + " | ".join(f"{r[0][:40]} {r[3]:.1f}s" for r in slowest))
    print("═" * 60 + "\n")

    sys.exit(0 if failed == 0 else 1)


