@test("B-ML3-BETS-MODE — train on fired bets with real Pinnacle CLV; signal direction verified")
def test_b_ml3_bets_mode():
    """B-ML3-BETS-MODE (2026-06-07): root fix for inverted meta-model signal.

    Old training data: all 7K+ MFV rows. Distribution mismatch vs inference
    (only ~300 actually-fired bets). Signal was inverted: high meta score → lower CLV.

    Fix: --bets-mode flag trains only on bots' fired bets + real Pinnacle CLV labels.
    AUC 0.6712 ± 0.0722, Q5 vs Q1 CLV spread: +18.4pp (previously −14.9pp).
    Bundle: data/models/meta/v_20260607_bets.
    """
    import pathlib, json

    train_src = pathlib.Path("scripts/train_b_ml3.py").read_text()

    # --bets-mode flag and helper function exist
    assert "_load_bets_mode_data" in train_src, "_load_bets_mode_data function must exist"
    assert "--bets-mode" in train_src, "--bets-mode CLI arg must exist"
    assert "--bets-days" in train_src, "--bets-days CLI arg must exist"

    # Trains on actual fired bets (simulated_bets JOIN bots), not all MFV rows
    assert "FROM simulated_bets sb" in train_src, "must query simulated_bets"
    assert "b.is_active = true" in train_src, "must filter to active bots only"
    assert "clv_pinnacle IS NOT NULL" in train_src, "must require real Pinnacle CLV"

    # Label is relative (clv_pinnacle > median), not absolute (> 0) which would be 84%+ positive
    assert "median_clv" in train_src and "clv_pinnacle" in train_src, \
        "label must use median threshold for balanced classes"

    # Lower minimum row check for bets-mode (50, not 1000)
    assert "50" in train_src, "bets-mode minimum row count must be 50"

    # Bundle saves to data/models/meta/<version>/ (version is a runtime arg, not hardcoded)
    assert "MODELS_DIR" in train_src, "must write bundle to MODELS_DIR"
    assert 'data" / "models" / "meta"' in train_src, "MODELS_DIR must point to data/models/meta/"
    assert "threshold.json" in train_src, "must save threshold.json with AUC metadata"
    assert "cv_auc_mean" in train_src, "must record cv_auc_mean in threshold.json"


@test("B-ML3-FEATURE-PATCH — _build_feature_row supplies all 44 features for bets-mode bundle")
def test_b_ml3_feature_patch():
    """B-ML3-BETS-MODE (2026-06-07): _build_feature_row in meta_b_ml3.py was only building
    ~22 features. The new v_20260607_bets bundle expects 44. Missing features silently
    zeroed by the KeyError fallback — model ran but accuracy was degraded.

    This patch adds the 12 new match-level features + 2 new missing-indicators.
    """
    import pathlib, joblib

    meta_src = pathlib.Path("workers/model/meta_b_ml3.py").read_text()

    # New match-level features added to the loop
    new_features = [
        "pinnacle_ah_line_at_t6h", "pinnacle_ah_line_move",
        "league_draw_rate_ytd", "season_progress", "line_velocity",
        "xg_overperf_home", "xg_overperf_away", "league_clv_efficiency",
        "injury_severity_score_home", "injury_severity_score_away",
        "team_avg_player_rating_home", "team_avg_player_rating_away",
    ]
    for feat in new_features:
        assert feat in meta_src, f"{feat} must be added to _build_feature_row"

    # New missing-indicators in thin list
    assert "pinnacle_ah_line_at_t6h" in meta_src.split("thin = ")[1].split("]")[0], \
        "pinnacle_ah_line_at_t6h must be in thin (missing-indicator) list"
    assert "pinnacle_ah_line_move" in meta_src.split("thin = ")[1].split("]")[0], \
        "pinnacle_ah_line_move must be in thin (missing-indicator) list"

    # _build_feature_row backward compat: old features still present
    for feat in ("bookmaker_disagreement", "elo_diff", "form_ppg_home", "lineup_confirmed",
                 "selection_draw", "selection_away"):
        assert feat in meta_src, f"old feature {feat} must still be in _build_feature_row"

    # Bundle feature_cols confirm all 44 features are accounted for
    bundle_dir = pathlib.Path("data/models/meta/v_20260607_bets")
    if bundle_dir.exists():
        fc = joblib.load(bundle_dir / "feature_cols.pkl")
        assert len(fc) == 44, f"bundle must have 44 features, got {len(fc)}"
        # Verify all new features are in the bundle
        for feat in new_features:
            assert feat in fc, f"{feat} must be in bundle feature_cols"


