@test("RAILWAY-ELIMINATION-SERVICE — Hetzner systemd unit + docker-compose + setup script exist and are well-formed")
def test_railway_elimination_service():
    import pathlib
    root = pathlib.Path(__file__).parent.parent

    unit = root / "local/systemd/oddsintel-scheduler.service"
    compose = root / "local/systemd/docker-compose.yml"
    setup = root / "local/setup-hetzner.sh"

    assert unit.exists(), "local/systemd/oddsintel-scheduler.service must exist"
    assert compose.exists(), "local/systemd/docker-compose.yml must exist"
    assert setup.exists(), "local/setup-hetzner.sh must exist"

    unit_src = unit.read_text()
    compose_src = compose.read_text()
    setup_src = setup.read_text()

    # Unit: essential fields
    assert "workers.scheduler" in unit_src, "systemd unit must invoke workers.scheduler"
    assert "python3" in unit_src, "systemd unit must invoke python3"
    assert "TZ=UTC" in unit_src, "systemd unit must set TZ=UTC (APScheduler timezone)"
    assert "FLARESOLVERR_URL=http://localhost:8191" in unit_src, (
        "systemd unit must pin FLARESOLVERR_URL to localhost (not VPS-hosted)"
    )
    assert "SCHEDULER_PROCESS_MB_LIMIT" in unit_src, (
        "systemd unit must set SCHEDULER_PROCESS_MB_LIMIT for health_alerts.py"
    )
    assert "EnvironmentFile" in unit_src, "systemd unit must load .env via EnvironmentFile"
    assert "Restart=always" in unit_src, "systemd unit must restart automatically"

    # Compose: FlareSolverr on port 8191, no persistent profile volume
    assert "8191" in compose_src, "docker-compose must expose FlareSolverr on port 8191"
    assert "flaresolverr_profile" not in compose_src, (
        "Hetzner FlareSolverr must not have persistent profile volume — "
        "HLTV sessions are ephemeral (torn down every 6h by FS-AUTO-RECOVER-HLTV)"
    )

    # Setup script: covers all five install steps
    assert "docker" in setup_src.lower(), "setup script must install Docker"
    # RAILWAY-ELIMINATION Phase 5 (d827f24) moved Hetzner deps into a venv, so
    # the script installs via `venv/bin/pip`, not `pip3`. The assertion was never
    # updated and has failed ever since. Accept either form — what matters is
    # that the script installs Python deps at all.
    assert ("pip3 install" in setup_src or "pip install" in setup_src), \
        "setup script must install Python deps"
    assert "systemctl enable" in setup_src, "setup script must enable the systemd unit"


@test("TIER-C-T3PLUS-GATE — daily_pipeline_v2 boosts tier 3/4 thresholds (+5pp 1X2, +3pp rest)")
def test_tier_c_t3plus_gate():
    import pathlib
    src = (pathlib.Path(__file__).parent.parent / "workers/jobs/daily_pipeline_v2.py").read_text()

    assert "if tier >= 3 and thresholds:" in src, (
        "TIER-C-T3PLUS-GATE: daily_pipeline_v2.py must guard the boost with 'if tier >= 3 and thresholds:'"
    )
    # Was a flat +0.03 for every market. TIER-C-T3PLUS-GATE-EXPAND-2026-07-31
    # split it after a 90d audit found T3 1X2 still at -24.30% ROI (n=170) and
    # T4 at -22.86% (n=176) even with the original +3pp gate: 1X2 gates went to
    # +5pp, everything else stayed +3pp. The test kept asserting the flat form
    # and has failed since. Assert the split, and pin BOTH legs so neither can
    # drift back silently.
    assert '0.05 if k.startswith("1x2") else 0.03' in src, (
        "TIER-C-T3PLUS-GATE: tier 3/4 boost must be +5pp on 1X2 markets and "
        "+3pp on the rest (TIER-C-T3PLUS-GATE-EXPAND-2026-07-31)"
    )
    # Boost must appear immediately after the thresholds lookup, before odds_range unpack
    gate_idx = src.index("if tier >= 3 and thresholds:")
    odds_idx = src.index("odds_min, odds_max = config[\"odds_range\"]", gate_idx)
    thresholds_lookup_idx = src.rindex("thresholds = config[\"edge_thresholds\"].get(tier, {})", 0, gate_idx)
    assert thresholds_lookup_idx < gate_idx < odds_idx, (
        "TIER-C-T3PLUS-GATE: boost block must appear between thresholds lookup and odds_range unpack"
    )


