@test("WEEKLY-EVAL-BASELINE")
def test_weekly_eval_baseline_2026_08_26():
    """WEEKLY-EVAL-BASELINE-2026-08-26 — the weekly retrain eval must notice when
    production is split across model versions."""
    import pathlib
    sched = pathlib.Path("workers/scheduler.py").read_text()
    ev = pathlib.Path("scripts/weekly_eval_and_compare.py").read_text()

    # The scheduler resolved the baseline from the GLOBAL env var only, while
    # inference routes per market. OU 2.5 has been served by v20260719 since
    # 2026-07-19 while the global stayed v20260712, so every weekly email since
    # scored the OU markets against a model that was not live.
    assert "WEEKLY-EVAL-BASELINE-2026-08-26" in sched
    assert "_resolve_version as _rv" in sched, \
        "scheduler must resolve the baseline the way the RUNTIME does"
    assert '_per_market = {k: _rv(k) for k in ("1x2", "ou", "goals")}' in sched
    assert "is SPLIT across versions" in sched, "a split baseline must be surfaced"

    # SUPERSEDED 2026-08-31 by WEEKLY-EVAL-PERMARKET-BASELINE. The 08-26 fix
    # only *warned* that the baseline was split and still scored every market
    # against the one version passed in; the eval now scores each market
    # against the version that actually serves it, so the "NOT served by"
    # warning string it used to print no longer exists. Assert the stronger
    # property instead — warning about the bug is not fixing it.
    assert "baseline_for" in ev and "MARKET_HEAD" in ev, \
        "the eval must apply a PER-MARKET baseline, not merely warn that one is split"
    assert 'add_argument("--warn-split-baseline"' not in ev, \
        "the warn-only flag was removed once the split became impossible — a " \
        "declared-but-unread flag reads as working and does nothing"

    # The resolver itself, since the whole fix rests on it: a per-market
    # override must win over the global.
    import os
    from workers.model.xgboost_ensemble import _resolve_version
    prev = os.environ.get("MODEL_VERSION_OU")
    os.environ["MODEL_VERSION_OU"] = "v_test_ou"
    try:
        assert _resolve_version("ou") == "v_test_ou", \
            "MODEL_VERSION_OU must override the global for the ou head"
    finally:
        if prev is None:
            os.environ.pop("MODEL_VERSION_OU", None)
        else:
            os.environ["MODEL_VERSION_OU"] = prev
    return "weekly eval warns when production is split across model versions"



@test("MODEL-1X2-PROMOTION")
def test_model_1x2_promotion_2026_08_26():
    """MODEL-1X2-PROMOTION-2026-08-26 — v20260823 promoted for the 1X2 head only,
    and the promotion audit trail reconciled to what is actually served."""
    import pathlib
    mig = pathlib.Path("supabase/migrations/285_reconcile_model_promotions.sql").read_text()

    # Reality on 2026-08-26, read from the live scheduler's /proc environ:
    #   MODEL_VERSION=v20260712, MODEL_VERSION_OU(_T1)=v20260719,
    #   MODEL_VERSION_1X2=v20260823
    for v in ("v20260712", "v20260719", "v20260607"):
        assert v in mig, f"{v} must be reconciled"
    assert "COALESCE(promoted_at," in mig, "must not overwrite a real promotion date"
    assert "COALESCE(demoted_at," in mig
    assert "AND promoted_at IS NULL" in mig, "must be idempotent"

    # OU was deliberately NOT promoted: the eval scored it against v20260712
    # while v20260719 was live, so that comparison was never validly made.
    assert "wrong baseline" in mig, \
        "must record why OU stayed on v20260719 rather than moving to the candidate"

    from workers.api_clients.db import execute_query
    rows = execute_query(
        "SELECT version, promoted_at, demoted_at FROM model_versions "
        "WHERE version = ANY(%s)",
        [["v20260823", "v20260719", "v20260712", "v20260607"]],
    )
    st = {r["version"]: r for r in rows}
    assert st["v20260823"]["promoted_at"] is not None, "1X2 candidate must be promoted"
    assert st["v20260712"]["promoted_at"] is not None, "global must be recorded live"
    assert st["v20260719"]["promoted_at"] is not None, "OU head must be recorded live"
    assert st["v20260607"]["demoted_at"] is not None, \
        "v20260607 stopped serving in July and must not still read as production"
    return "1X2 promoted to v20260823; promotion audit trail matches served versions"


@test("WEEKLY-BOT-REVIEW-CS2-FILTER + CALIBRATION-ECE-BY-BIN — CS2 bots excluded; ECE bin section present")
def test_weekly_bot_review_cs2_filter_and_ece():
    """WEEKLY-BOT-REVIEW-CS2-FILTER (2026-06-21): excludes bot_cs2_* from
    the soccer-only weekly bot review. CS2 bets land in cs2_real_bets
    table (not simulated_bets / real_bets), so CS2 bots showed 0/0/0
    in this report and just polluted the dormant footer.

    CALIBRATION-ECE-BY-BIN (2026-06-21): adds a per-10pp-bin predicted
    vs actual win-rate table to the weekly digest. Surfaces miscalibration
    regressions within 7 days. Origin: tonight's GLOBAL-PLATT-OVERCONFIDENCE
    audit took 26 days from v20260607 promotion to discover the $5,800/yr
    leak. With this section in place, similar regressions surface on the
    next Sunday digest after a Platt re-fit.

    Pin: SQL filter excludes 'bot_cs2_%' in _fetch_active_bots;
    _print_calibration_section exists; bins on calibrated_prob in 10pp
    steps; flags significant gaps (|gap| > max(5pp, 1.96σ))."""
    import pathlib

    review = pathlib.Path("scripts/weekly_bot_review.py").read_text()

    # CS2 filter must be in the query, not a Python-side post-filter
    # (post-filter would still hit the DB and would be inconsistent with
    # the "where is_active" pattern).
    fetch_block = review[review.index("def _fetch_active_bots("):
                          review.index("def _fetch_sim_bets(")]
    assert "bot_cs2_%" in fetch_block, (
        "_fetch_active_bots must exclude bot_cs2_* (CS2 bets land in "
        "cs2_real_bets, not soccer simulated_bets / real_bets — they show "
        "0/0/0 here and pollute the dormant footer)."
    )

    # Calibration section function must exist.
    assert "def _print_calibration_section(" in review, (
        "weekly_bot_review.py must define _print_calibration_section() — "
        "the per-10pp-bin ECE audit that surfaces calibration regressions."
    )

    cal_block = review[review.index("def _print_calibration_section("):
                        review.index("def _print_bot_block(")]

    # Must read calibrated_prob from simulated_bets (not model_probability)
    # because the production-relevant calibration is the post-shrinkage
    # one the placer actually uses.
    assert "calibrated_prob" in cal_block, (
        "_print_calibration_section must read calibrated_prob (post-shrinkage, "
        "the actual production calibration) — model_probability is pre-stage-1 "
        "and wouldn't surface the regressions we care about."
    )

    # Significance test must be present so single-bet variance doesn't
    # spam the operator with false alarms.
    assert "1.96" in cal_block, (
        "_print_calibration_section must apply a 1.96σ significance test — "
        "without it, a 60-70% bin with n=10 and a 7pp gap would flag, "
        "even though the binomial standard error there is ~15pp."
    )
    assert "5pp" in cal_block or "0.05" in cal_block, (
        "_print_calibration_section must also require |gap| > 5pp absolute — "
        "1.96σ alone fires on small but statistically real gaps that aren't "
        "materially significant for ROI."
    )

    # Section must be called from main() between HEADLINE and ACTIONABLE
    # blocks so the operator sees the calibration warning BEFORE drilling
    # into bot-by-bot blocks.
    main_block = review[review.index("def main():"):]
    headline_idx = main_block.index("=== HEADLINE ===")
    cal_call_idx = main_block.index("_print_calibration_section(")
    actionable_idx = main_block.index("ACTIONABLE")
    assert headline_idx < cal_call_idx < actionable_idx, (
        "_print_calibration_section must be called AFTER the HEADLINE line "
        "and BEFORE the ACTIONABLE section so the operator reads it in "
        "context, not buried below 30 bot blocks."
    )


@test("FS-RECOVER-CLI — flaresolverr_recover.py surgical session destroyer")
def _():
    """Tool to unstick FlareSolverr when SOME sessions hang while others
    work (the 06-23 incident pattern: cs2_hltv_upcoming + cs2_coolbet_scanner
    + cs2_hltv_match_odds all failing every cron tick while
    coolbet_odds_snapshot kept working). Default is dry-run; targeting
    is by --session, --prefix, or --all. Pin so a future rename or
    accidental delete is caught.
    """
    import pathlib, importlib.util
    p = pathlib.Path("scripts/diagnose/flaresolverr_recover.py")
    assert p.exists(), "scripts/diagnose/flaresolverr_recover.py must exist"
    src = p.read_text()
    for needle in ("def list_sessions", "def destroy_session", "def pick_targets",
                   "sessions.list", "sessions.destroy",
                   "--apply", "--prefix", "--session", "--all", "--list",
                   "FLARESOLVERR_URL"):
        assert needle in src, f"flaresolverr_recover missing {needle}"

    spec = importlib.util.spec_from_file_location("fs_recover", p)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    sessions = ["coolbet_prod", "hltv_matches", "hltv_upcoming", "hltv_stats"]

    assert mod.pick_targets(sessions, names=["hltv_stats"], prefixes=[], all_=False) == ["hltv_stats"]
    assert sorted(mod.pick_targets(sessions, names=[], prefixes=["hltv_"], all_=False)) == \
           ["hltv_matches", "hltv_stats", "hltv_upcoming"]
    out = mod.pick_targets(sessions, names=["coolbet_prod"], prefixes=["hltv_"], all_=False)
    assert set(out) == {"coolbet_prod", "hltv_matches", "hltv_upcoming", "hltv_stats"}
    assert mod.pick_targets(sessions, names=[], prefixes=[], all_=True) == sessions
    assert mod.pick_targets(sessions, names=["nope"], prefixes=["zz_"], all_=False) == []


@test("COOLBET-SCRAPERS-MOVED-TO-MAC — odds_snapshot + cs2 scanner run via launchd on Mac, not VPS scheduler")
def test_coolbet_scrapers_moved_to_mac():
    """MOVED-TO-MAC (2026-07-03): Coolbet Imperva 403's the VPS FS
    Chrome + Hetzner IP. The two Coolbet-HTTP scrapers now run on the
    operator's Mac (residential IP + real browser fingerprint via CDP
    handles auth for the daemon; scanner + odds_snapshot go through
    the same local FS Docker that the daemon already uses).

    Guardrails this test enforces:
    1. VPS scheduler must NOT register either add_job — if someone
       uncomments them the VPS starts silently 403'ing again.
    2. Both launchd plists must exist and use StartCalendarInterval
       at the same offsets the VPS crons used (:03/:33 and :17/:47).
       If the offsets drift, betting_refresh at :05/:35 may read
       stale Coolbet odds.
    3. Both plists must pin FLARESOLVERR_URL=http://localhost:8191
       to defeat any stale the VPS URL still sitting in `.env`.
    """
    import pathlib
    root = pathlib.Path(__file__).parent.parent

    sched = (root / "workers/scheduler.py").read_text()
    # Neither add_job registration may exist on the VPS scheduler — if
    # someone re-adds them the VPS starts silently 403'ing again.
    assert "\n    scheduler.add_job(_coolbet_odds_snapshot_wrapper," not in sched, (
        "coolbet_odds_snapshot is registered on the VPS scheduler — it "
        "runs on the Mac via launchd instead (Imperva 403s the VPS). "
        "If you need it on the VPS again, first fix the Imperva 403 "
        "root cause; don't just re-add it."
    )
    assert "\n    scheduler.add_job(job_cs2_coolbet_scanner," not in sched, (
        "cs2_coolbet_scanner is registered on the VPS scheduler — moved "
        "to the Mac launchd. See "
    )
    # Breadcrumb comments must point at the launchd plists so future
    # readers know why these jobs aren't in the scheduler.
    assert "com.oddsintel.coolbet-odds-snapshot.plist" in sched, (
        "workers/scheduler.py must mention the launchd plist for "
        "coolbet_odds_snapshot so it's discoverable — don't delete "
        "the breadcrumb."
    )
    # CS2-REMOVAL-2026-08-26 removed the cs2_coolbet_scanner plist along with the
    # rest of the esports vertical, so this breadcrumb has nothing left to point
    # at. The odds-snapshot half of this test still guards a live Mac scraper.

    for name, minutes, prog_marker in [
        ("com.oddsintel.coolbet-odds-snapshot.plist",
         (3, 33), "workers.automation.coolbet_explorer"),
        # The cs2-coolbet-scanner entry was removed with the esports vertical
        # (CS2-REMOVAL-2026-08-26); odds-snapshot is the remaining Mac scraper.
    ]:
        plist = (root / "local/launchd" / name).read_text()
        assert "<key>StartCalendarInterval</key>" in plist, (
            f"{name} must use StartCalendarInterval to keep the "
            "VPS-era :03/:33 and :17/:47 alignment (betting_refresh "
            "reads odds at :05/:35)."
        )
        for m in minutes:
            assert f"<integer>{m}</integer>" in plist, (
                f"{name} must fire at :{m:02d} — drifting the schedule "
                "risks stale odds when betting_refresh runs."
            )
        assert prog_marker in plist, (
            f"{name} ProgramArguments must invoke {prog_marker!r}."
        )
        assert "<string>http://localhost:8191</string>" in plist, (
            f"{name} must pin FLARESOLVERR_URL=http://localhost:8191 "
            "so the dead the VPS URL in .env can't hijack the run."
        )
        assert "<key>RunAtLoad</key>\n    <false/>" in plist, (
            f"{name} must have RunAtLoad=false so `launchctl load` "
            "doesn't fire an unscheduled extra run right before :03/:17."
        )


@test("KUMA-TIER1-WIRED — 5 Tier-1 jobs push to Uptime Kuma via _run_job or direct call")
def test_kuma_tier1_wired():
    """KUMA-TIER1-WIRED (2026-07-07): the 5 Tier-1 jobs must all reach
    Uptime Kuma through one of two paths:
      1. `_run_job(name, ...)` — fires _kuma_push(name, status=up/down) at
         end. Covers morning_pipeline, betting_refresh, settlement.

    Was 7. CS2-REMOVAL-2026-08-26 dropped `cs2_bot` from the list below but
    left `cs2_v8_predict`, so this test kept asserting a job that no longer
    exists and failed from that date on. Both removed 2026-09-01.
      2. Direct `_kuma_push(...)` calls in job_coolbet_health_ping and
         job_healthcheck_ping (both don't flow through _run_job on all
         code paths, so they need the explicit call).

    Guardrails:
      - _run_job must import + invoke _kuma_push.
      - job_coolbet_health_ping's failure path must RAISE from the
        lambda so _run_job records status=failed → Kuma "down". The
        old `_run_job(lambda: None)` pattern silently logged
        'completed' on failure — the trap this test exists to prevent.
      - job_healthcheck_ping must call _kuma_push('healthcheck_ping',
        ...) in both success and failure branches.
      - Each Tier-1 pipeline-runs name must literally appear in
        scheduler.py so operators know which KUMA_TOKENS key maps
        where.
    """
    import pathlib
    sched = (pathlib.Path(__file__).parent.parent / "workers/scheduler.py").read_text()

    # 1. Central import of the Kuma push helper.
    assert "from workers.utils.kuma import push as _kuma_push" in sched, (
        "workers/scheduler.py must import workers.utils.kuma.push — "
        "this is the single choke-point for Uptime Kuma pings."
    )

    # 2. _run_job must fire the push using its `name` argument.
    assert "_kuma_push(" in sched and 'status="up" if status == "completed"' in sched, (
        "_run_job must call _kuma_push(name, status='up' if completed "
        "else 'down', ...) — Kuma won't get status transitions otherwise."
    )

    # 3. Silent-failure guardrail on job_coolbet_health_ping. Old code
    # used `_run_job('coolbet_health_ping', lambda: None)` on failure,
    # which pinged Kuma 'up' on failure. New code must raise from a
    # named lambda so _run_job → status=failed → Kuma 'down'.
    assert "raise RuntimeError(f\"coolbet health_ping exited" in sched, (
        "job_coolbet_health_ping failure path must RAISE — the previous "
        "`lambda: None` pattern is a silent-failure trap that would "
        "ping Kuma 'up' on failure. Do not revert."
    )
    # And the old trap must be gone.
    assert 'console.print(result.stdout[-500:] or result.stderr[-500:])\n    _run_job("coolbet_health_ping", lambda: None)' not in sched, (
        "job_coolbet_health_ping still contains the `_run_job(..., "
        "lambda: None)` silent-failure trap on the unhealthy branch. "
        "Replace with a raising lambda so pipeline_runs + Kuma both "
        "reflect reality."
    )

    # 4. job_healthcheck_ping must push in both branches.
    assert '_kuma_push("healthcheck_ping", status="up"' in sched, (
        "job_healthcheck_ping success branch must push status=up so "
        "Kuma's scheduler-alive monitor stays green."
    )
    assert '_kuma_push("healthcheck_ping", status="down"' in sched, (
        "job_healthcheck_ping failure branch must push status=down so "
        "an urllib exception surfaces on the Kuma dashboard."
    )

    # 5. Each Tier-1 pipeline_runs name literal must exist in scheduler.py
    # (these are the exact KUMA_TOKENS keys the operator needs to create).
    for job_id in (
        "morning_pipeline",
        "betting_refresh",
        "settlement",
        # "cs2_bot" and "cs2_v8_predict" both removed — CS2-REMOVAL-2026-08-26
        # deleted the jobs; the second name was missed until 2026-09-01.
        "coolbet_health_ping",
        "healthcheck_ping",
    ):
        assert f'"{job_id}"' in sched, (
            f"pipeline_runs name '{job_id}' must appear as a string "
            "literal in scheduler.py — it's the KUMA_TOKENS key the "
            "operator uses. If you rename the job, mirror the change "
            "in docs/KUMA_MONITORS.md AND the Kuma UI."
        )




@test("COOLBET-FEED-WATCHDOG")
def test_coolbet_feed_watchdog_2026_08_26():
    """COOLBET-FEED-WATCHDOG-2026-08-26 — watches the feed's OUTPUT and only
    self-heals what it can actually fix."""
    import pathlib
    from workers.jobs.coolbet_feed_watchdog import (
        classify, FEED_STALE_H, COOKIE_STALE_H, ODDS_JOB,
    )
    src = pathlib.Path("workers/jobs/coolbet_feed_watchdog.py").read_text()

    # The whole point: judge on odds arriving, not on the job looking alive.
    # On 2026-08-26 launchd reported the job running while it had failed every
    # 30 minutes for 80 hours.
    assert "FROM odds_snapshots WHERE bookmaker = 'Coolbet'" in src, \
        "must measure the feed's output, not process state"

    # Self-heal ONLY the two states with a safe automatic remedy. CDP_DOWN and
    # BLOCKED must alert and stop — retrying a block hardens it.
    assert '"NOT_LOADED"' in src and '"STALE_COOKIES"' in src
    assert '"CDP_DOWN"' in src and '"BLOCKED"' in src
    heal = src[src.index("def run("):]
    assert "_reload_job()" in heal and "_refresh_cookies()" in heal
    # BLOCKED is an ESCALATION, not a first classification. Observed 2026-08-26:
    # a run wrote 4,517 rows on fresh cookies then hit a 403 mid-batch, cookies
    # minutes old. Imperva re-challenges far faster than the staleness
    # threshold, so keying on age alone would page a human for something one
    # CDP re-harvest fixes. run() must only reach BLOCKED after that fails.
    assert 'state = "BLOCKED"' in heal, \
        "BLOCKED must be reachable only after a failed cookie refresh"
    assert "cookie_refresh_failed" in heal

    # COOLBET-WATCHDOG-BLINDED (2026-08-28): freshness must be measured over
    # BULK SWEEPS only. Once the UI placer started writing snapshots for the
    # few matches it visits, "newest Coolbet row" stayed fresh through a 6h
    # scraper outage and the watchdog reported HEALTHY throughout.
    assert "COUNT(DISTINCT match_id) >= " in src, \
        "freshness must key on sweep breadth, not any Coolbet row"
    from workers.jobs.coolbet_feed_watchdog import BULK_SWEEP_MIN_MATCHES
    assert BULK_SWEEP_MIN_MATCHES >= 10, "a handful of placer matches is not a sweep"

    # send_telegram takes dedup_window_s (seconds). The old dedup_hours kwarg
    # raised TypeError inside the try/except, so the alert path had never
    # fired — detection without notification.
    assert "dedup_hours" not in src, "wrong kwarg silently disabled every alert"
    assert "dedup_window_s" in src

    # ZERO-PICKS ALARM (2026-08-28): a healthy feed does not mean a working bot.
    # "0 picks" reads exactly like a quiet day — the shape that hid the
    # InplayBot UUID bug for 11 days. Separable: if both books priced plenty of
    # upcoming matches and the bot still wrote nothing, it is not a quiet day.
    from workers.jobs.coolbet_feed_watchdog import (
        PICKS_STALE_H, PICKS_MIN_PRICED_MATCHES, _picks_gap,
    )
    assert "NO_PICKS" in src, "a silent bot on a healthy feed must be detectable"
    assert 0 < PICKS_STALE_H <= 24 and PICKS_MIN_PRICED_MATCHES >= 5
    gap, priced = _picks_gap()
    assert priced >= 0, "picks-gap probe must not raise"

    # The cookie-age query named a column that does not exist
    # (imperva_cookies_at vs imperva_cookies_refreshed_at), so it raised on
    # every call, the except swallowed it, and the helper returned None
    # forever — "cookie age is unknown" on every run, with the
    # cookies-are-fresh branch of classify() unreachable.
    assert "imperva_cookies_refreshed_at" in src, "cookie age must use the real column"
    assert "imperva_cookies_at)" not in src

    assert 0 < FEED_STALE_H <= 6, "feed-stale threshold must be sane"
    assert 0 < COOKIE_STALE_H <= 4, "cookie-stale threshold must be sane"
    assert ODDS_JOB == "com.oddsintel.coolbet-odds-snapshot"

    # classify() must be pure — safe to call anywhere, takes no action.
    state, reason = classify()
    assert state in ("HEALTHY", "NOT_LOADED", "STALE_COOKIES", "CDP_DOWN",
                     "BLOCKED", "UNKNOWN"), f"unexpected state {state}"
    assert reason

    plist = pathlib.Path("local/launchd/com.oddsintel.coolbet-feed-watchdog.plist").read_text()
    assert "<key>COOLBET_NO_FS</key>" in plist, (
        "the watchdog must use the same direct-request path as the odds job; "
        "without it the session routes through FlareSolverr and measures a "
        "different failure surface"
    )
    assert "coolbet_feed_watchdog" in plist
    return "coolbet feed watchdog judges output, self-heals only what it can"



@test("MODEL-AB-ENSEMBLE-LEG")
def test_model_ab_ensemble_leg_2026_08_26():
    """MODEL-AB-ENSEMBLE-LEG-2026-08-26 — the A/B scores the blended ENSEMBLE,
    not just the raw XGB leg, because the ensemble is what the bots bet."""
    import pathlib
    from workers.model.xgboost_ensemble import ensemble_prediction
    src = pathlib.Path("workers/jobs/daily_pipeline_v2.py").read_text()

    assert "pred_shadow = ensemble_prediction(poisson_pred, xgb_pred_shadow" in src, \
        "shadow XGB leg must be blended with the SAME poisson into an ensemble"
    assert '"source": "ensemble",\n                            "model_prob": float(_sh_prob)' in src \
        or 'shadow={_shadow_ver}' in src, \
        "shadow ensemble rows must be written with source='ensemble'"

    # A version compared against itself is noise — exactly what the stale
    # SHADOW_MODEL_VERSION pin produced before SHADOW-AUTOSELECT.
    assert '_shadow_ver != (_ens_ver or "")' in src, \
        "must not write a shadow row when candidate == production for that head"

    # _shadow_ver is assigned inside the Tier-A branch; without a per-match
    # init a Tier-B/C match would NameError at the write and kill the pipeline.
    assert 'xgb_pred_shadow = None  # Phase B shadow candidate predictions' in src
    i = src.index("xgb_pred_shadow = None  # Phase B")
    assert '_shadow_ver = ""' in src[i:i + 500], \
        "_shadow_ver must be initialised per match, not only inside Tier A"

    # ensemble_prediction reads the expected-goals half; the XGB-leg-only A/B
    # never called the blender, so the shadow dict lacked these keys and would
    # have raised KeyError in production.
    assert '"xgb_exp_home": _eh_s' in src and '"xgb_exp_away": _ea_s' in src, \
        "shadow inference must produce the goals regressors the blender needs"

    # The blend must actually work and must differ when the legs differ.
    poisson = {"home_prob": .45, "draw_prob": .28, "away_prob": .27,
               "over_25_prob": .55, "under_25_prob": .45,
               "exp_home": 1.5, "exp_away": 1.1}
    a = ensemble_prediction(poisson, {"xgb_home_prob": .50, "xgb_draw_prob": .26,
        "xgb_away_prob": .24, "xgb_over25_prob": .58, "xgb_exp_home": 1.7,
        "xgb_exp_away": 1.0}, tier=1)
    b = ensemble_prediction(poisson, {"xgb_home_prob": .44, "xgb_draw_prob": .29,
        "xgb_away_prob": .27, "xgb_over25_prob": .52, "xgb_exp_home": 1.4,
        "xgb_exp_away": 1.2}, tier=1)
    assert a["home_prob"] != b["home_prob"], "differing XGB legs must differ after blending"
    return "A/B now scores the blended ensemble the bots actually bet"



@test("COOLBET-OU-LINE-SHIFT")
def test_coolbet_ou_line_shift_2026_08_26():
    """COOLBET-OU-LINE-SHIFT-2026-08-26 — Coolbet's bracketed TEAM totals must
    not land in the full-match OU slot."""
    import pathlib
    from workers.automation.coolbet_explorer import (
        _looks_like_non_goals_total, _NON_GOALS_TOTAL_HINTS,
    )

    # Coolbet names a team total "[Home] Total Goals" — BRACKETED. The existing
    # qualifiers ("home team", "away total", ...) match none of that, and its
    # market_type_id (1551) is not in _MTID_OU, so it fell through to the
    # name-fallback, matched "total goals", and was stored as a full-match line.
    assert _looks_like_non_goals_total("[home] total goals"), \
        "bracketed home team total must be rejected"
    assert _looks_like_non_goals_total("[away] total goals"), \
        "bracketed away team total must be rejected"

    # ...without rejecting the real market, which is the whole point.
    assert not _looks_like_non_goals_total("total goals over / under"), \
        "the genuine full-match goals line must still be accepted"

    # The older unbracketed spellings must keep working.
    assert _looks_like_non_goals_total("total goals home team")
    assert _looks_like_non_goals_total("over / under corners")

    assert "[home]" in _NON_GOALS_TOTAL_HINTS and "[away]" in _NON_GOALS_TOTAL_HINTS

    src = pathlib.Path("workers/automation/coolbet_explorer.py").read_text()
    assert "COOLBET-OU-LINE-SHIFT-2026-08-26" in src, (
        "the why must stay next to the hint list — this is the third "
        "market-name collision after COMBINED-MARKET and HALF-MATCH"
    )
    return "bracketed Coolbet team totals no longer clobber the full-match OU ladder"



@test("COOLBET-VALUE-BOT")
def test_coolbet_value_bot_2026_08_26():
    """COOLBET-VALUE-BOT-2026-08-26 — bets COOLBET's own price, valued against
    de-vigged Pinnacle. The only bot whose quote the operator can actually take."""
    import pathlib
    src = pathlib.Path("workers/jobs/daily_pipeline_v2.py").read_text()

    assert "_COOLBET_VALUE_BOT = \"bot_coolbet_value_v1\"" in src
    assert "def _run_coolbet_value_pass(" in src
    fn = src[src.index("def _run_coolbet_value_pass("):src.index("def _run_pin_ou_shadow_pass(")]

    # It must price at Coolbet and NOT take a max across books — that is the
    # entire reason it exists. 57 of 58 sweep/pin picks were negative-EV at
    # Coolbet on 2026-08-26 despite showing +7% on the page.
    assert '"recommended_bookmaker": "Coolbet"' in fn, \
        "every pick must be quoted at Coolbet"
    assert "max(" not in fn, "must not take a best-of-N price"

    # Fair value must come from Pinnacle. Valuing Coolbet against Coolbet is
    # circular — a book can never look mispriced against itself.
    assert "_devig(pin)" in fn, "fair value must be the Shin-de-vigged Pinnacle close"
    assert "'Coolbet', 'Pinnacle'" in fn, "must read both books"

    # Guards carried over from the sibling bots.
    assert "_LINESHOP_TRUE_EDGE_MIN" in fn, "must use the shared 3% post-vig floor"
    assert "_LINESHOP_TIERS" in fn, "must keep the tier 1-2 gate"
    assert "1.35 if mkt ==" in fn, (
        "outlier guard required — COOLBET-OU-LINE-SHIFT found a bracketed TEAM "
        "total sitting in the full-match OU slot at 17.00 vs Pinnacle's 4.19"
    )
    # One side per total, or we pay the vig twice for a guaranteed loss.
    assert "edge > best[\"edge\"]" in fn, "must keep only the best side per market"

    # Wired into BOTH cohorts, error-isolated so a Coolbet outage cannot take
    # the pipeline down.
    # Count CALL sites only — the def line matches a naive substring too.
    calls = src.count("            _run_coolbet_value_pass(today_str")
    assert calls == 2, (
        f"must run on the morning cohort AND the shadow refresh (found {calls})"
    )
    assert "Coolbet-value bot failed (non-critical)" in src, "must be error-isolated"

    mig = pathlib.Path("supabase/migrations/287_bot_coolbet_value.sql").read_text()
    assert "bot_coolbet_value_v1" in mig and "ON CONFLICT (name) DO NOTHING" in mig

    # /admin/shadow-bots renders a HARDCODED bot list — a new bot is invisible
    # there until it is added, which is how a bot can run for weeks unseen.
    page = _web_path("src/app/(app)/admin/shadow-bots/page.tsx").read_text()
    assert '"bot_coolbet_value_v1"' in page, \
        "new shadow bots must be added to SHADOW_BOTS or they never render"
    # backtestN 0 means never replayed. Showing "+0.0% n=0" would read as a
    # measured zero rather than an absence.
    assert "s.backtestN === 0 ?" in page and "no backtest" in page, \
        "an unreplayed config must render as 'no backtest', not a fake zero"

    # The DETAIL page has its OWN allowlist and 404s on anything missing from
    # it. Being in SHADOW_BOTS is not enough — the index would link to a dead
    # page, which is exactly what happened on first deploy.
    detail = _web_path("src/app/(app)/admin/shadow-bots/[bot]/page.tsx").read_text()
    assert "bot_coolbet_value_v1: {" in detail, \
        "detail page ALLOWED entry required or the row links to a 404"
    assert "bot_coolbet_value_v1: 0.03," in detail, \
        "detail page edge-floor map must know this bot's gate"
    return "Coolbet-priced value bot: quotes only obtainable prices, visible on the admin page"


@test("EPICBET-ODDS-INGEST — second EE-licensed book: parser vocabulary, squad guard, scheduler slot")
def _():
    """EPICBET-ODDS-INGEST-2026-08-27. Coolbet was the only book the operator can
    actually bet at, so every value bot was priced against a single venue.
    Epicbet serves its prematch feed anonymously (no auth, no bot-protection),
    so it ingests VPS-side on the normal scheduler.

    Pins the three things that silently produce wrong money if they drift:

    (1) **Snapshot vocabulary.** Rows must use the same market/selection strings
        every other bookmaker in odds_snapshots uses (`1x2` home/draw/away,
        `over_under_XX`, `btts`, `asian_handicap`). A capitalised or renamed
        selection is invisible to the frontend lookup — that was
        COOLBET-SELECTION-CASE.
    (2) **Squad-qualifier guard.** `fuzzy_match_event` scores with partial_ratio,
        which cannot tell "Rosario Central Res." from "Rosario Central". On the
        first live run that produced Epicbet home 2.75 vs Pinnacle 1.47 — an
        apparent +87% edge across two different fixtures.
    (3) **Scheduler slot.** The job must be registered and must land before the
        :05/:35 betting refresh, or the cycle prices against stale quotes.
    """
    import pathlib
    from workers.automation import epicbet_explorer as ep

    # (1) vocabulary — parse a synthetic event through the real parser
    ev = {"raw": {
        "homeTeamName": "Alpha FC", "awayTeamName": "Beta United",
        "marketGroups": [
            {"id": 45, "markets": [{"id": 1, "line": None, "outcomes": [
                {"id": 11, "name": "Alpha FC"}, {"id": 12, "name": "Draw"},
                {"id": 13, "name": "Beta United"}]}]},
            {"id": 15, "markets": [
                {"id": 2, "line": 2.5, "outcomes": [
                    {"id": 21, "name": "Over", "line": "2.5"},
                    {"id": 22, "name": "Under", "line": "2.5"}]},
                # quarter line must be dropped — no column vocabulary for it
                {"id": 3, "line": 2.25, "outcomes": [
                    {"id": 31, "name": "Over", "line": "2.25"},
                    {"id": 32, "name": "Under", "line": "2.25"}]}]},
            {"id": 69, "markets": [{"id": 4, "line": None, "outcomes": [
                {"id": 41, "name": "Yes"}, {"id": 42, "name": "No"}]}]},
            {"id": 19, "markets": [{"id": 5, "line": -1.0, "outcomes": [
                {"id": 51, "name": "Alpha FC", "line": "-1.0"},
                {"id": 52, "name": "Beta United", "line": "+1.0"}]}]},
        ]}}
    odds = {11: 1.50, 12: 4.00, 13: 6.00, 21: 1.90, 22: 1.95,
            31: 1.70, 32: 2.15, 41: 1.80, 42: 1.95, 51: 2.05, 52: 1.80}
    rows = ep.parse_event_markets(ev, odds)
    got = {(m, sel) for m, sel, _o, _l in rows}
    for expected in [("1x2", "home"), ("1x2", "draw"), ("1x2", "away"),
                     ("over_under_25", "over"), ("over_under_25", "under"),
                     ("btts", "yes"), ("btts", "no"),
                     ("asian_handicap", "home"), ("asian_handicap", "away")]:
        assert expected in got, f"missing {expected} — snapshot vocabulary drifted"
    assert not any(m == "over_under_22" or m == "over_under_23" for m, _ in got), \
        "quarter OU lines have no column vocabulary and must be dropped"
    # AH line is stored home-perspective on BOTH sides of the market
    ah = {sel: line for m, sel, _o, line in rows if m == "asian_handicap"}
    assert ah["home"] == -1.0 and ah["away"] == -1.0, \
        f"AH must store the home-perspective line on both rows, got {ah}"
    # 1X2 must not be flipped: home is the shortest price here
    x2 = {sel: o for m, sel, o, _l in rows if m == "1x2"}
    assert x2["home"] == 1.50 and x2["away"] == 6.00, f"1X2 orientation flipped: {x2}"

    # (2) squad guard
    assert ep._squad_tag("Rosario Central Res.") == "res"
    assert ep._squad_tag("Rosario Central") is None
    assert ep._squad_tag("Club Tijuana U21") == "u21"
    assert ep._squad_tag("Millonarios W") == "w"
    assert ep._squad_tag("Brighton") is None, "first-team names must carry no tag"
    assert not ep._squads_compatible(
        "Rosario Central Res.", "Barracas Central Res.",
        {"home": "Rosario Central", "away": "Barracas Central"}), \
        "a reserves fixture must never match the first-team event"
    assert ep._squads_compatible(
        "Rosario Central Res.", "Barracas Central Res.",
        {"home": "Rosario Central Res.", "away": "Barracas Central Res."})
    src_mod = pathlib.Path("workers/automation/epicbet_explorer.py").read_text()
    assert "_squads_compatible(m[\"home\"], m[\"away\"], ev)" in src_mod, \
        "the guard must actually filter candidates, not just exist"

    # (3) scheduler registration + ordering
    sched = pathlib.Path("workers/scheduler.py").read_text()
    assert "def job_epicbet_odds_snapshot" in sched, "scheduler job must exist"
    assert 'id="epicbet_odds_snapshot"' in sched, "job must be registered, not just defined"
    assert 'CronTrigger(hour="*", minute="2,32")' in sched, \
        "Epicbet must fire at :02/:32 — before the :05/:35 betting refresh"

    # This assertion used to require "Epicbet odds snapshot failed" in the
    # scheduler — i.e. that the job swallowed its own exceptions. That is
    # exactly what EPICBET-403-FROM-VPS-2026-08-29 had to undo: catching
    # everything meant _run_job recorded status='completed' and pinged Kuma
    # "up" through 277 consecutive runs over six days that wrote zero rows.
    # _run_job already isolates each job from the others, so the job re-raises
    # and the failure is finally visible. Inverted rather than deleted, so the
    # swallow cannot quietly come back.
    job_src = sched[sched.index("def job_epicbet_odds_snapshot"):
                    sched.index("def _epicbet_odds_snapshot_wrapper")]
    assert "except Exception" not in job_src, (
        "job_epicbet_odds_snapshot must NOT catch its own exceptions — that is "
        "how six days of 403s reported success (EPICBET-403-FROM-VPS). "
        "_run_job provides the isolation."
    )
    assert "_run_job(\"epicbet_odds_snapshot\"" in sched, (
        "the job must still be wrapped by _run_job, which is what isolates it "
        "from the other scheduler jobs now that it re-raises"
    )
    return "Epicbet ingest: vocabulary pinned, reserve/youth false-matches blocked, :02/:32 slot"


@test("COOLBET-FEED-PAIRING")
def test_coolbet_feed_pairing_2026_08_28():
    """COOLBET-FEED-PAIRING-2026-08-28 — never price a Coolbet quote against a
    Pinnacle quote taken hours earlier, and record how far apart they were."""
    import inspect
    import pathlib
    from workers.jobs.daily_pipeline_v2 import _PAIR_MAX_GAP_H, _run_coolbet_value_pass

    src = inspect.getsource(_run_coolbet_value_pass)

    # The bot used to take each book's LATEST row with no window between them.
    # Measured on its last 79 picks: median gap 1.63h, 56pct over 1h, 37pct
    # over 4h, max 15.6h. Coolbet swings 14-19pct intraday, so that can invent
    # edge — the same mechanism produced apparent +55.6pct DC edges from
    # quotes 16h apart.
    assert "stale_pair" in src, "stale pairings must be counted, not silently used"
    assert "_PAIR_MAX_GAP_H" in src, "pairing must be time-bounded"
    assert 0 < _PAIR_MAX_GAP_H <= 12, "pairing window must be sane"

    # Staleness must be auditable after the fact, not reconstructable only by
    # re-querying odds_snapshots (which ages out).
    assert "pair_gap_hours" in src, "each pick must record its own pairing gap"
    writer = pathlib.Path("workers/api_clients/supabase_client.py").read_text()
    assert "pair_gap_hours" in writer, "the writer must persist the gap"

    mig = pathlib.Path("supabase/migrations/289_shadow_bets_pair_gap.sql").read_text()
    assert "ADD COLUMN IF NOT EXISTS pair_gap_hours" in mig

    return "cross-book pairing time-bounded + gap recorded per pick"


@test("COOLBET-UI-PLACER")
def test_coolbet_ui_placer_2026_08_27():
    """COOLBET-UI-PLACER-2026-08-27 — place at Coolbet by driving the UI, so the
    path has no Imperva cookie-freshness dependency. Stage-only by default."""
    import datetime as _dt
    import inspect
    import pathlib
    from workers.automation import coolbet_ui_placer as up

    src = pathlib.Path("workers/automation/coolbet_ui_placer.py").read_text()

    # Selectors are the contract with Coolbet's markup — verified live against
    # the FK Partizan v Getafe page 2026-08-27. Centralised so a redesign is a
    # one-place fix; pinned here so a silent edit shows up as a red test.
    assert up.SEL_SEARCH == 'input[name="sportSearch"]'
    assert up.SEL_PLACE_BTN == 'button[data-test="button-place-bet"]'
    assert "yourStake{market_id}" in up.SEL_STAKE

    # Money-committing default must be OFF. stage_bet() is the only orchestrator
    # and execute=False leaves the account untouched.
    assert inspect.signature(up.stage_bet).parameters["execute"].default is False

    # The kill switch must gate the execute branch. place_all_bets kept placing
    # through a paused flag once already (PLACEMENT-PAUSED-KILL-SWITCH,
    # 2026-06-12) — do not let the UI path repeat it.
    stage_src = inspect.getsource(up.stage_bet)
    assert "is_placement_paused" in stage_src, "execute path must honour the kill switch"
    assert "place_enabled" in stage_src, "must not click a disabled place button"

    # button-odds-<id> keys the MARKET, not the outcome: 1X2 home/draw/away all
    # share one id, Over and Under share one. Treating it as an outcome id bets
    # the wrong side. The module must say so.
    assert "MARKET, not the outcome" in src

    # Stake field is a React-controlled input behind an on-screen keypad — a
    # fill() that looks fine can be silently dropped. set_stake must read back.
    assert "input_value" in inspect.getsource(up.set_stake), \
        "stake must be verified by read-back, never assumed"
    assert "did not stick" in stage_src, "stage_bet must reject a dropped stake"

    # Odds drift: the pick is qualified against a captured price. FK Partizan
    # carried 3.55 while Coolbet showed 3.30 — staking into that silently is
    # how edge disappears.
    assert "max_odds_drop_pct" in stage_src

    # OU line matching against Coolbet's Estonian labels. The line must match
    # EXACTLY — 'Over 2.5' and 'Over 3.5' are different bets, and Coolbet
    # writes the side twice ('Üle Ü 2.5'), so the line cannot be taken as the
    # first number that parses.
    ou = [
        up.UiOutcome(market_id="849", label="Üle Ü 2.5", odds=2.12),
        up.UiOutcome(market_id="849", label="Alla A 2.5", odds=1.73),
        up.UiOutcome(market_id="850", label="Üle Ü 3.5", odds=3.51),
    ]
    assert up._label_line("Üle Ü 2.5") == 2.5, "side initial must not be read as the line"
    assert up._ou_side("Alla A 2.5") == "under"
    assert up.find_outcome(ou, "over_under_25", "over", "A", "B").odds == 2.12
    assert up.find_outcome(ou, "over_under_35", "over", "A", "B").odds == 3.51
    # A line that is not on the page must come back None, never a near miss.
    assert up.find_outcome(ou, "over_under_35", "under", "A", "B") is None

    # Asian handicap stays unsupported: Coolbet renders it as team-name-plus-
    # handicap ('FK Partizan +1.0'), colliding with the 1X2 label space.
    outcomes = [up.UiOutcome(market_id="1", label="FK Partizan", odds=3.30)]
    try:
        up.find_outcome(outcomes, "ah_home_-1.00", "home", "A", "B")
        raise AssertionError("unsupported market must raise, not guess")
    except up.UiPlacerError:
        pass

    # Totals must be read from the 'Väravate arv (Üle/Alla)' card, which holds
    # the whole ladder. The strip at the top of the match page is a quick-bet
    # shortcut showing ONE line — reading totals there missed every non-main
    # line on the first attempt.
    grid_src = inspect.getsource(up.read_ou_grid)
    assert "Väravate arv" in grid_src, "OU ladder must come from the totals card"
    # The line sits in its own cell, so the row is recovered geometrically.
    # Integrity guard: both prices on a row must share a market id (one id per
    # line), else the row is dropped rather than mis-paired into a wrong total.
    assert "row[0][\"mkt\"] != row[1][\"mkt\"]" in grid_src, \
        "mis-paired OU row must be dropped, not guessed"
    stage_src_ou = inspect.getsource(up.stage_bet)
    assert "read_ou_grid" in stage_src_ou, "stage_bet must use the ladder for totals"

    # Price gate is MIN-ODDS, not a drift percentage: a pick can sit below its
    # break-even price without having drifted at all, and taking it is negative
    # EV by the bot's own criterion.
    assert "min_odds_for" in stage_src_ou, "must gate on break-even price"
    assert abs(up.min_odds_for({"model_probability": 0.336}, 0.03) - 3.065) < 0.01

    # Slip hygiene. Coolbet remembers selections across navigation, so blanking
    # the stake is not enough — on 2026-08-27 three staged picks left a slip
    # reading '2 Pilet' whose text showed a DIFFERENT pick's selection.
    # Placing from that state bets something we never chose.
    assert "deselect_outcome" in stage_src_ou, "staged bets must be taken back out of the slip"
    assert "empty_slip" in stage_src_ou, "a dirty slip must be cleared before staging"
    assert "expected 1" in stage_src_ou, \
        "must refuse to place unless the slip holds exactly our one bet"

    # Every exit path records, including the ones that never reached a price.
    assert "record_attempt" in stage_src_ou
    rec_src = inspect.getsource(up.record_attempt)
    # execute_query does NOT commit — the first version inserted, returned a
    # fresh id, and rolled back on connection release, so the run reported
    # success and stored nothing.
    assert "execute_write_returning" in rec_src, "audit write must commit"

    # PLACEMENT MUST BE CONFIRMED BY EVIDENCE. On 2026-08-27 a run recorded
    # outcome='placed' (and wrote a real_bets row) for FK Jablonec draw @ 3.50
    # while the balance never moved off EUR 250.00 — the first TEE PANUS click
    # only opens Coolbet's two-step confirm. A cleared slip is not a bet.
    assert "read_balance" in stage_src_ou, "placement must be confirmed by balance delta"
    assert "NOT confirmed" in stage_src_ou, "unconfirmed placement must not be recorded as placed"
    place_src = inspect.getsource(up.place)
    assert "kinnita|confirm" in place_src, "must click Coolbet's second confirm step"

    # Periodic running is the design, so re-runs must never double-place and
    # must be bounded in blast radius.
    runner = pathlib.Path("scripts/place_coolbet_ui.py").read_text()
    assert "def already_placed" in runner, "re-runs must not double-place"
    assert "outcome = 'placed'" in runner, "dedup must key on a CONFIRMED placement"
    assert "MAX_BETS_PER_DAY" in runner and "MAX_STAKE_PER_DAY" in runner, \
        "unattended placement needs count AND money ceilings"
    assert "KICKOFF_CUTOFF_MIN" in runner, "must not place into a starting match"
    assert "MARK_PLACED" in runner and "MARK_CHECKED" in runner

    # The loop must recover its own session — the login is fully scripted, so
    # an unattended pass does not need a human unless Coolbet asks for SMS.
    assert "cdp_auto_login" in runner, "runner must re-login on its own"
    # cdp_auto_login opens its OWN sync_playwright, and Playwright refuses a
    # second sync context inside the first. Calling it from within the run's
    # `with sync_playwright()` block broke every unattended recovery overnight
    # 2026-08-27 -> 08-28: the loop woke, found the session gone, and failed to
    # heal on every pass with "Sync API inside the asyncio loop". The heal must
    # run BEFORE the run context is opened.
    heal_at = runner.index("cdp_auto_login")
    ctx_at = runner.index("with sync_playwright()")
    assert heal_at < ctx_at, "session heal must happen outside the run's browser context"

    # The betslip lives in localStorage; resetting the key is what makes the
    # loop self-clearing. Clicking the per-selection trash icon does NOT work:
    # it ignores dispatched MouseEvents and a real click times out on an icon
    # clipped at the viewport edge.
    empty_src = inspect.getsource(up.empty_slip)
    assert "betSlipSettings" in empty_src, "slip reset must go through localStorage"
    assert "reload" in empty_src, "storage reset only takes effect after a reload"

    # The placer loads a real match page every pass, so its prices are free —
    # and unlike the bulk scraper (search/v2, killed by stale Imperva cookies
    # for 4.5h on 2026-08-27 and 80h before that) this path has no cookie
    # dependency. odds_snapshots has vocabulary for .5 lines only; whole-number
    # lines are DROPPED, never rounded onto a neighbour.
    snap_src = inspect.getsource(up.snapshot_prices)
    assert "store_odds" in snap_src, "reuse the shared writer, not a raw insert"
    assert set(up._OU_LINE_SLOTS) == {0.5, 1.5, 2.5, 3.5, 4.5}, \
        "only .5 lines have an odds_snapshots slot"
    assert 2.0 not in up._OU_LINE_SLOTS and 3.0 not in up._OU_LINE_SLOTS

    # Navigation must WAIT for the URL, not sleep and hope: a fixed pause raced
    # the SPA and consecutive picks landed on the previous pick's match page.
    open_src = inspect.getsource(up.open_event)
    assert "wait_for_url" in open_src, "must wait for navigation, not a fixed timeout"

    # Search must WAIT for results. A flat sleep read a half-built dropdown and
    # reported "1 results" — really zero, since Coolbet injects a promoted
    # 'Ungari - Eesti' row into every search regardless of query.
    search_src = inspect.getsource(up.search_events)
    assert "wait_for_function" in search_src, "must wait for search results to render"

    # "Cannot find it" and "Coolbet does not offer it" are different facts and
    # must not share a message: 22 de Julio v Santo Domingo is listed by
    # Coolbet against Vargas Torres, so refusing it is CORRECT, while an empty
    # search is our bug. They were indistinguishable in the audit until now.
    assert "fixture not offered by Coolbet" in stage_src_ou
    assert "search returned no fixtures" in stage_src_ou

    # Concurrent passes drive the SAME browser tab and corrupt each other —
    # five fixtures failed to match inside one 90s window on 2026-08-27 purely
    # from a manual run overlapping the scheduled one.
    assert "single_run_lock" in runner and "LOCK_NB" in runner, \
        "a second pass must refuse rather than fight for the browser"

    # BLOCK DETECTION (2026-08-28). Coolbet served an Imperva interstitial — a
    # ~1KB document with an empty body and an _Incapsula_Resource iframe —
    # after a day of heavy automated traffic from one IP. is_logged_in was a
    # NEGATIVE check (no password field == logged in), so a block page read as
    # a healthy session and the placer walked into failure after failure.
    login_src = inspect.getsource(up.is_logged_in)
    assert "detect_block" in login_src, "a block must not read as a healthy session"
    block_src = inspect.getsource(up.detect_block)
    assert "_Incapsula_Resource" in block_src
    # A block is not a login problem: re-logging in adds traffic from an
    # already-flagged IP. The pass must abort, not retry.
    assert "BLOCKED:" in stage_src_ou
    assert "ABORT" in runner and "will recover on its own" in runner, \
        "a blocked pass must stop, not hammer the IP pick by pick"

    # REAL-MONEY ALLOWLIST (2026-08-28). Experimental bots must be able to run
    # the whole pipeline — matching, pricing, snapshots, audit rows — with no
    # path to the account. A default bot name is not a guard: --bot could name
    # anything and --execute would have honoured it.
    from scripts.place_coolbet_ui import EXECUTE_ALLOWED_BOTS  # noqa: F401
    assert EXECUTE_ALLOWED_BOTS == {"bot_coolbet_value_v1"}, \
        "only the proven bot may place real money"
    assert "not in EXECUTE_ALLOWED_BOTS" in runner
    assert "args.execute = False" in runner, "a disallowed bot must be forced dry"

    # Coolbet's search does not tolerate our full DB team names. Verified live:
    # "Ararat-Armenia" returned 10 results NOT containing the fixture, while
    # "ararat" returned it second — the hyphen breaks their tokeniser.
    assert up.search_queries("Ararat-Armenia", "Universitatea Craiova")[0] == "Ararat"
    assert "FC ST. Gallen" not in up.search_queries("FC ST. Gallen", "X")[:1]

    # Kickoff is the strongest evidence available: Coolbet prints Estonian
    # local time, and 27 aug 19:00 Tallinn is exactly 16:00 UTC. A fixture
    # agreeing to the minute is close to unique, so names spelled differently
    # across platforms stop being the deciding factor.
    ko = _dt.datetime(2026, 8, 27, 16, 0, tzinfo=_dt.timezone.utc)
    assert up.parse_start("27 aug 19:00", ko) == ko, "Tallinn->UTC conversion"
    assert up.start_matches("27 aug 19:00", ko) is True
    assert up.start_matches("21 aug 19:00", ko) is False

    right = up.UiEvent("1", "/x", "", "FC Ararat-Armenia", "CS Universitatea Craiova", "27 aug 19:00")
    assert up.pick_event([right], "Ararat-Armenia", "Universitatea Craiova", ko) is not None
    # Same teams, wrong leg — a parsed-and-disagreeing kickoff is a hard reject
    # at any name score.
    # COOLBET-MOVED-FIXTURE (2026-08-31) changed this: a LONE same-team
    # candidate on another day is now taken as a postponement, because
    # refusing it threw away real bets when Coolbet moved and our feed did
    # not. What still must not happen is guessing between TWO of them — that
    # is the wrong-leg case the guard was built for.
    wrong_leg = up.UiEvent("2", "/y", "", "FC Ararat-Armenia", "CS Universitatea Craiova", "21 aug 19:00")
    assert up.pick_event([wrong_leg], "Ararat-Armenia", "Universitatea Craiova", ko,
                         allow_moved=False) is None, \
        "with the moved-fixture rule off, a disagreeing kickoff is still a hard reject"
    leg_b = up.UiEvent("2b", "/yb", "", "FC Ararat-Armenia", "CS Universitatea Craiova", "28 aug 19:00")
    assert up.pick_event([wrong_leg, leg_b], "Ararat-Armenia", "Universitatea Craiova", ko) is None, \
        "two legs of a tie must never be guessed between"
    # And a date-agreeing candidate always beats a moved one.
    assert up.pick_event([wrong_leg, right], "Ararat-Armenia", "Universitatea Craiova", ko).match_id == "1"
    # And a perfect kickoff must NOT let a reserve side through.
    res = up.UiEvent("3", "/z", "", "Rosario Central Res.", "Boca Res.", "27 aug 19:00")
    assert up.pick_event([res], "Rosario Central", "Boca Juniors", ko) is None

    # The plist must never place a bet merely by being loaded.
    plist = pathlib.Path("local/launchd/com.oddsintel.coolbet-ui-placer.plist").read_text()
    assert "<key>RunAtLoad</key>\n    <false/>" in plist, \
        "loading the job must not itself fire a placement"

    # COOLBET-SQUAD-GUARD: a reserve side must never match a first team. This
    # produced a fake +87pct edge on the Epicbet path (Rosario Central Res.).
    evs = [up.UiEvent(match_id="1", href="/et/sport/match/1",
                      text="Rosario Central Res. - Boca Res.",
                      home="Rosario Central Res.", away="Boca Res.")]
    assert up.pick_event(evs, "Rosario Central", "Boca Juniors") is None, \
        "reserve fixture must not match a first team"

    # And the honest positive case still matches.
    evs2 = [up.UiEvent(match_id="6022381", href="/et/sport/match/6022381",
                       text="FK Partizan - Getafe 27 aug 22:00",
                       home="FK Partizan", away="Getafe")]
    assert up.pick_event(evs2, "FK Partizan", "Getafe") is not None

    return "Coolbet UI placer: selectors pinned, stage-only default, squad guard, stake read-back"


@test("COOLBET-MATCH-EXPOSURE-GUARD")
def test_coolbet_match_exposure_guard_2026_09_01():
    """COOLBET-MATCH-EXPOSURE-GUARD-2026-09-01 — at most 2 real-money bets per
    match, and the 2 must be independent opinions.

    Filed after 2026-08-31: 19 bets / EUR 190 for -EUR 92.80 with no per-match
    state of any kind in the UI placer. The daily caps were the only limit and
    the run stopped one bet short of MAX_BETS_PER_DAY.
    """
    import inspect
    import pathlib
    from scripts.place_coolbet_ui import (
        MARKET_FAMILY, MAX_BETS_PER_MATCH, MAX_STAKE_PER_MATCH,
        canon_bet, exposure_conflict, main,
    )

    assert MAX_BETS_PER_MATCH == 2
    assert MAX_STAKE_PER_MATCH == 20.00

    # ── The two-writer vocabulary trap ────────────────────────────────────
    # real_bets carries BOTH `over_under_25`+'over' (this UI placer) and
    # `o/u`+'over 2.5' (coolbet_placer.py). A guard that does not collapse
    # them reads half the book and lets the other half through.
    assert canon_bet("over_under_25", "over") == ("totals", "over 2.5")
    assert canon_bet("o/u", "over 2.5") == ("totals", "over 2.5")
    assert canon_bet("over_under_35", "under") == canon_bet("o/u", "under 3.5")
    assert canon_bet("1x2", "home") == ("result", "home")

    # Combos must NOT count as exposure: their match_id is only a placeholder
    # for the first leg, so counting one would block singles on that match.
    assert canon_bet("combo", "straight") is None
    # An unrecognised market must not silently collapse onto something else.
    assert canon_bet("totally_new_market", "yes") is None

    # ── Family grouping ───────────────────────────────────────────────────
    # 1x2/DC/DNB/AH are all re-expressions of who wins; the OU ladder is one
    # goals opinion. Backing two members of a family is one position staked
    # twice, not two bets.
    for m in ("1x2", "double_chance", "draw_no_bet", "asian_handicap"):
        assert MARKET_FAMILY[m] == "result", m
    assert canon_bet("over_under_25", "over")[0] == canon_bet("over_under_35", "over")[0]
    assert MARKET_FAMILY["btts"] == "btts"

    # ── The three faults from 2026-08-31, replayed ────────────────────────
    # (1) Colwyn Bay v Llandudno: 1x2/away 13:03 then 1x2/home 16:00. The model
    #     legitimately flipped on the 15:10 refresh and emitted a NEW uuid, so
    #     the shadow_bet_id dedup could not see it.
    held = [{"family": "result", "canon": "away", "stake": 10.0}]
    why = exposure_conflict({"market": "1x2", "selection": "home"}, held, 10.0)
    assert why and "same opinion" in why, why

    # (2) Airbus UK v Holywell: U2.5 + U3.5 (match finished 6-2, both lost).
    held = [{"family": "totals", "canon": "under 2.5", "stake": 10.0}]
    why = exposure_conflict({"market": "over_under_35", "selection": "under"}, held, 10.0)
    assert why and "same opinion" in why, why

    # (3) Same logical pick twice. shadow_bets_unique emitted 359 rows on
    #     08-31 that collapse to 197 distinct triples — ~45pct duplicate ids
    #     the uuid-keyed already_placed() cannot recognise. Combos already
    #     double-placed twice in August.
    held = [{"family": "totals", "canon": "over 3.5", "stake": 10.0}]
    why = exposure_conflict({"market": "o/u", "selection": "over 3.5"}, held, 10.0)
    assert why and "already hold this exact bet" in why, why

    # ── Two INDEPENDENT opinions on one match stay allowed ────────────────
    held = [{"family": "result", "canon": "home", "stake": 10.0}]
    assert exposure_conflict({"market": "over_under_35", "selection": "over"},
                             held, 10.0) is None
    # ...but a third does not, even from a fresh family.
    held.append({"family": "totals", "canon": "over 3.5", "stake": 10.0})
    why = exposure_conflict({"market": "btts", "selection": "yes"}, held, 10.0)
    assert why and "per-match bet cap" in why, why

    # Stake cap binds independently of the count cap.
    held = [{"family": "result", "canon": "home", "stake": 15.0}]
    why = exposure_conflict({"market": "btts", "selection": "yes"}, held, 10.0)
    assert why and "per-match stake cap" in why, why

    # ── Wiring: a guard that is never called is not a guard ───────────────
    main_src = inspect.getsource(main)
    assert "exposure_conflict(" in main_src, "guard must be called in the placement loop"
    assert "match_exposure(" in main_src, "exposure must be seeded from real_bets"
    # Airbus UK's three bets landed 13:00 / 13:02 / 13:02 — one pass. A DB-only
    # check is racy, so the loop must keep the exposure map current in memory.
    assert "held.append(" in main_src, "in-run placements must update exposure"
    # Blocks must be recorded, not merely skipped, or the firing rate is
    # unmeasurable ([[feedback_silent_failures]]).
    assert "exposure_guard" in main_src, "blocks must write a placement-attempt row"

    src = pathlib.Path("scripts/place_coolbet_ui.py").read_text()
    assert "match_id = ANY(%s::uuid[])" in src
    # Exposure must NOT be date- or result-filtered: a bet placed yesterday on
    # a match kicking off today is still exposure. Check the SQL, not the
    # docstring — the docstring says WHY it is unfiltered and names the column.
    exp_sql = (src.split("def match_exposure")[1]
                  .split("def exposure_conflict")[0]
                  .split('"""')[2])
    assert "placed_at" not in exp_sql, "must not date-filter exposure"
    assert "result" not in exp_sql.split("execute_query")[1].split(")")[0], \
        "must not filter exposure by settlement result"

    return ("Coolbet per-match exposure: max 2 bets from distinct families, "
            "both vocabularies collapsed, combos excluded, blocks recorded")


@test("COOLBET-UI-SEARCH-PREFIX")
def test_coolbet_ui_search_prefix_2026_08_31():
    """COOLBET-UI-PLACER-MATCHGAPS-2026-08-31 — prefix queries as a LAST RESORT
    fallback, appended after every whole-word query so they cost nothing on the
    picks that never needed them."""
    import datetime as _dt
    import inspect
    from workers.automation import coolbet_ui_placer as up

    # Prefixes exist for a name that differs at its START, which whole words
    # cannot reach — the way the odds-snapshot path (coolbet_placer._search_event)
    # has always searched. They are NOT what fixed FC Copenhagen v Sonderjyske:
    # that fixture matched on the whole word 'Sonderjyske' (Coolbet folds the
    # o-slash itself) and had simply not been attempted yet, its pick having
    # been created at 08:41 UTC — after that morning's 08:00 pass.
    qs = up.search_queries("FC Copenhagen", "Sonderjyske")
    assert "Son" in qs and "Cop" in qs, "prefixes must be available as a fallback"

    # ORDERING IS THE POINT. stage_bet loops the queries and stops at the first
    # one that matches, so every prefix placed before the whole words costs a
    # live search round trip on a pick that never needed one. Coolbet blocked
    # this IP on 2026-08-28 for traffic volume from a single address — extra
    # searches are not free. Every whole-word query must come first.
    prefixes = {"Cop", "Cope", "Copen", "Son", "Sond", "Sonde"}
    first_prefix = min(i for i, q in enumerate(qs) if q in prefixes)
    last_word = max(i for i, q in enumerate(qs) if q not in prefixes)
    assert first_prefix > last_word, "prefixes must be tried only after every whole word"
    assert qs[:3] == ["Copenhagen", "FC Copenhagen", "Sonderjyske"], \
        "the whole-word queries that already worked must be unchanged"

    # No duplicates — a repeated query is a wasted search.
    assert len(qs) == len(set(q.lower() for q in qs)), "queries must be unique"
    assert up.search_queries("X", "Rayo").count("Rayo") == 1

    # A prefix is a SEARCH widening only. It must not loosen matching — 'Son'
    # alone would match hundreds of clubs, and pick_event is what stops that.
    src = inspect.getsource(up.search_queries)
    assert "pick_event still vets" in src, "a loose query must not mean a loose match"
    loose = [up.UiEvent("9", "/w", "", "Sondrio", "Sondalo", "31 aug 20:00")]
    assert up.pick_event(loose, "FC Copenhagen", "Sonderjyske") is None, \
        "a prefix hit on the wrong club must still be rejected"

    # The fixture itself, placed live 2026-08-31 09:00 UTC at 5.50. Name score
    # alone is 72, below the 80 bar — the 20:00 Tallinn kickoff is what carries
    # it, which is exactly the design.
    ko = _dt.datetime(2026, 8, 31, 17, 0, tzinfo=_dt.timezone.utc)
    real = [up.UiEvent("6042909", "/et/sport/match/6042909", "",
                       "FC K\u00f8benhavn", "S\u00f8nderjyskE", "31 aug 20:00")]
    assert up.pick_event(real, "FC Copenhagen", "Sonderjyske", ko) is not None
    assert up.pick_event(real, "FC Copenhagen", "Sonderjyske") is None, \
        "without kickoff corroboration 72 is correctly below the name bar"

    return "UI placer prefix queries appended last; whole-word order unchanged"

@test("COOLBET-UI-OU-EXPAND")
def test_coolbet_ui_ou_expand_2026_08_31():
    """COOLBET-UI-PLACER-MATCHGAPS-2026-08-31 — the totals card must be expanded
    before it is read. Coolbet shows ~5 lines around the main total and hides
    the rest behind 'KUVA KOIK (n)'."""
    import inspect
    from workers.automation import coolbet_ui_placer as up

    # THE BUG. Barcelona v Rayo centred on 4.0 and rendered 3/3.5/4/4.5/5, so
    # over_under_25/under was rejected three times with "not offered on this
    # page" while over_under_35/under placed from that SAME page. read_ou_grid
    # reads the DOM, so an unexpanded card makes real markets invisible — and
    # which totals were reachable depended on where Coolbet centred the ladder.
    grid_src = inspect.getsource(up.read_ou_grid)
    assert "expand_ou_card" in grid_src,         "the ladder must be expanded before it is read, not read as rendered"

    exp_src = inspect.getsource(up.expand_ou_card)

    # Only the TOTALS card's expander. Handikap carries its own 'KUVA KOIK'
    # and clicking that one leaves 2.5 just as hidden.
    assert "V\u00e4ravate arv" in exp_src, "must scope to the totals card"

    # The click must be a real user event. Several controls on this page ignore
    # dispatched MouseEvents — the per-selection slip trash icon already proved
    # that in empty_slip — so JS .click() is not good enough for React here.
    assert "locator(" in exp_src and ".click(" in exp_src,         "expander must be clicked through Playwright, not JS dispatch"

    # Verify by EFFECT, not by the click returning. A click that silently does
    # nothing must not be reported as an expansion — that would turn a visible
    # failure back into an invisible one.
    assert "_count()" in exp_src and ">" in exp_src,         "expansion must be confirmed by the ladder actually growing"
    assert "did not grow" in exp_src

    # A card with no expander is the NORMAL case (every line already shown),
    # so it must return False, never raise — otherwise every low-scoring match
    # becomes a placement failure.
    import ast as _ast
    import textwrap as _tw
    fn = _ast.parse(_tw.dedent(exp_src)).body[0]
    assert not [n for n in _ast.walk(fn) if isinstance(n, _ast.Raise)], \
        "a card with no expander is not an error"
    assert exp_src.count("return False") >= 3

    return "OU totals card expanded before read; growth verified, missing expander is not an error"


@test("COOLBET-DATE-GUARD-DEAD")
def test_coolbet_date_guard_dead_2026_08_31():
    """COOLBET-DATE-GUARD-DEAD-2026-08-31 — COOLBET-FUZZY-DATE-GUARD read the
    wrong field name and silently no-opped on every candidate since it was
    written: 217,518 log lines, every one '0 candidates rejected on date'."""
    import logging
    from datetime import datetime, timezone
    from workers.automation import coolbet_placer as cp

    # THE BUG. search/v2 calls this field `match_start` — the same name
    # fo-category already used, and which _fetch_category_matches already read.
    # _parse_event read only `start`, so _parse_iso_start got None for EVERY
    # search result and the guard's `if ev_start is not None` skipped it every
    # time. A guard that never rejects anything is indistinguishable from no
    # guard, which is why this survived unnoticed.
    ev = cp._parse_event({
        "id": 6062800,
        "name": "Atl\u00e9tico Grau - FBC Melgar",
        "match_start": "2026-09-01T20:00:00.000Z",
    })
    assert ev["start"] == "2026-09-01T20:00:00.000Z", \
        "search/v2 names the kickoff `match_start`, not `start`"
    # The old name must still work — fo-category events flow through the same
    # matcher and some payloads do carry `start`.
    assert cp._parse_event({"id": 1, "name": "A - B", "start": "2026-09-01T20:00:00Z"})["start"]

    # WHAT IT COST. Atletico Grau v FBC Melgar was postponed 31 Aug -> 1 Sept
    # for Melgar's travel to Piura. Coolbet moved the event; API-Football kept
    # the old date. With the guard dead we matched the moved event at score
    # 100, stored 82 price rows against a night it is not played, and
    # bot_coolbet_value_v1 raised a draw @ 3.14 off them.
    stale = datetime(2026, 8, 31, 20, 0, tzinfo=timezone.utc)
    assert cp.fuzzy_match_event("Atletico Grau", "FBC Melgar", [ev], stale) is None, \
        "a 24h gap must be rejected however perfectly the names score"
    real = datetime(2026, 9, 1, 20, 0, tzinfo=timezone.utc)
    assert (cp.fuzzy_match_event("Atletico Grau", "FBC Melgar", [ev], real) or {}).get("id") == 6062800, \
        "the same fixture on the right date must still match"

    # Tolerance stays generous enough that ordinary kickoff jitter is not a
    # rejection — measured 2026-08-31 over 30 upcoming fixtures: of 9 that
    # matched on name, 7 agreed to the minute and the 2 rejects were genuinely
    # different fixtures (Man Utd U21 13 days out).
    assert cp._FUZZY_DATE_TOLERANCE_HOURS == 6
    near = cp._parse_event({"id": 2, "name": "Atl\u00e9tico Grau - FBC Melgar",
                            "match_start": "2026-08-31T23:00:00.000Z"})
    assert cp.fuzzy_match_event("Atletico Grau", "FBC Melgar", [near], stale) is not None, \
        "3h of jitter must not cost us a fixture"

    # A name-perfect candidate losing ONLY on date is not "Coolbet does not
    # offer this" — it is "our date is stale", and the two call for opposite
    # responses. Both looked like no coverage before.
    recs = []

    class _Cap(logging.Handler):
        def emit(self, r):
            recs.append(r)

    h = _Cap()
    cp.log.addHandler(h)
    try:
        cp.fuzzy_match_event("Atletico Grau", "FBC Melgar", [ev], stale)
    finally:
        cp.log.removeHandler(h)
    warns = [r.getMessage() for r in recs if r.levelno >= logging.WARNING]
    assert any("DATE MISMATCH" in m for m in warns), "a postponement must be loud"
    assert any("24.0h apart" in m for m in warns), "the gap must be stated"
    assert any("stale" in m for m in warns), "must name our date as the suspect one"

    # A genuinely-absent fixture must NOT produce that warning — otherwise the
    # signal is worthless.
    recs.clear()
    other = cp._parse_event({"id": 3, "name": "Sondrio - Sondalo",
                             "match_start": "2026-09-01T20:00:00.000Z"})
    cp.log.addHandler(h)
    try:
        cp.fuzzy_match_event("Atletico Grau", "FBC Melgar", [other], stale)
    finally:
        cp.log.removeHandler(h)
    assert not [r for r in recs if r.levelno >= logging.WARNING], \
        "a wrong-name candidate is no coverage, not a date mismatch"

    # DATE-MISMATCH-FALSE-ALARM (2026-09-02). `date_rejects` is filled by the
    # date check at the top of the candidate loop, BEFORE the squad guard runs,
    # so it holds candidates that could never have been this fixture at all.
    # The warning block then re-scored them on NAME ONLY and announced our date
    # as stale. Real firings from the snapshot log: 'Seoul W vs Incheon Red
    # Angels W' reported against 'FC Seoul vs Incheon United', and 'Gremio U17'
    # against 'Gremio FBPA'.
    #
    # This is load-bearing for AF-STALE-FIXTURE-DATES, which wants to alert off
    # this warning: of 13 unique firings only 3 were genuine date
    # discrepancies. An alert that is 77% false trains the operator to ignore
    # the 23% that are real.
    recs.clear()
    mens = cp._parse_event({"id": 4, "name": "FC Seoul - Incheon United",
                            "match_start": "2026-09-05T10:00:00.000Z"})
    womens_ko = datetime(2026, 9, 2, 10, 0, tzinfo=timezone.utc)
    cp.log.addHandler(h)
    try:
        res = cp.fuzzy_match_event("Seoul W", "Incheon Red Angels W", [mens], womens_ko)
    finally:
        cp.log.removeHandler(h)
    assert res is None, "a men's fixture must never match our women's fixture"
    assert not [r for r in recs if "DATE MISMATCH" in r.getMessage()], (
        "a squad-incompatible candidate is a DIFFERENT FIXTURE, not evidence "
        "that our date is stale — warning here poisons the AF-STALE signal"
    )

    return ("search/v2 kickoff read as match_start; date guard live; "
            "postponement warns loudly; squad-incompatible candidates stay quiet")


@test("COOLBET-UI-DATE-MISMATCH")
def test_coolbet_ui_date_mismatch_2026_08_31():
    """COOLBET-DATE-GUARD-DEAD-2026-08-31 — the placer must say "postponed", not
    "not offered". A perfect name score next to "Coolbet does not have it" is a
    contradiction, and it hides a stale fixture date in our own DB."""
    import inspect
    from datetime import datetime, timezone
    from workers.automation import coolbet_ui_placer as up

    ko = datetime(2026, 8, 31, 20, 0, tzinfo=timezone.utc)
    # Coolbet renders Estonian local time: 01 sept 23:00 Tallinn == 01 Sept 20:00 UTC,
    # exactly 24h after the date API-Football still gives us.
    moved = up.UiEvent("6062800", "/et/sport/match/6062800", "",
                       "Atl\u00e9tico Grau", "FBC Melgar", "01 sept 23:00")

    # COOLBET-MOVED-FIXTURE (2026-08-31): a lone moved candidate is now BET,
    # not refused — the operator's call, and the right one, since Coolbet and
    # the press both had this fixture on 1 Sept while our feed did not.
    assert up.pick_event([moved], "Atletico Grau", "FBC Melgar", ko) is not None, \
        "a lone postponed fixture must be taken, not thrown away"
    assert up.pick_event([moved], "Atletico Grau", "FBC Melgar", ko,
                         allow_moved=False) is None, \
        "the old hard-reject must still be reachable"

    hits = up._date_rejected_candidates([moved], "Atletico Grau", "FBC Melgar", ko)
    assert len(hits) == 1, "a name-perfect candidate on another day must be surfaced"
    assert hits[0][1] == datetime(2026, 9, 1, 20, 0, tzinfo=timezone.utc), \
        "must report Coolbet's kickoff in UTC"

    # It must stay narrow, or the signal is worthless. None of these is a
    # postponement:
    same = up.UiEvent("1", "/x", "", "Atl\u00e9tico Grau", "FBC Melgar", "31 aug 23:00")
    assert not up._date_rejected_candidates([same], "Atletico Grau", "FBC Melgar", ko), \
        "the fixture on our own date is not a date mismatch"
    other = up.UiEvent("2", "/y", "", "Sondrio", "Sondalo", "01 sept 23:00")
    assert not up._date_rejected_candidates([other], "Atletico Grau", "FBC Melgar", ko), \
        "a different fixture is no coverage, not a postponement"
    # COOLBET-SQUAD-GUARD still applies: a reserve side on another day is a
    # different team, not the same match moved. It must not be bet either.
    res = up.UiEvent("3", "/z", "", "Atl\u00e9tico Grau Res.", "FBC Melgar Res.", "01 sept 23:00")
    assert not up._date_rejected_candidates([res], "Atletico Grau", "FBC Melgar", ko), \
        "a reserve fixture must never read as a postponement"
    assert up.pick_event([res], "Atletico Grau", "FBC Melgar", ko) is None, \
        "and must never be bet as one"
    # No kickoff of our own means nothing to disagree with.
    assert not up._date_rejected_candidates([moved], "Atletico Grau", "FBC Melgar", None)

    # And the branch must actually be wired into the refusal path, ahead of the
    # generic "not offered" message it would otherwise fall through to.
    stage_src = inspect.getsource(up.stage_bet)
    assert "_date_rejected_candidates" in stage_src
    assert "DATE MISMATCH, not missing coverage" in stage_src
    assert "AMBIGUOUS DATE" in stage_src, "two legs must record a distinct reason"
    # rindex: the generic message also appears in the comment explaining why
    # this branch exists, so anchor on the actual return statement.
    assert stage_src.index("_date_rejected_candidates") < stage_src.rindex('f"fixture not offered by Coolbet'), \
        "the postponement check must run before the generic no-coverage message"
    # A bet placed on a fixture we have mis-dated must say so on its own audit
    # row — the stale date also drives the kickoff cutoff and settlement.
    assert "MOVED FIXTURE: Coolbet has it" in stage_src

    return "placer reports a postponed fixture as a date mismatch, not as missing coverage"


@test("COOLBET-SEARCH-PROMO-RACE")
def test_coolbet_search_promo_race_2026_08_31():
    """COOLBET-SEARCH-PROMO-RACE-2026-08-31 — the search read raced Coolbet's
    promoted rows, and the kickoff regex could not see a 4-letter Estonian
    month. Together they turned a listed fixture into "no fixtures" and
    disarmed the placer's date guard."""
    import inspect
    from datetime import datetime, timezone
    from workers.automation import coolbet_ui_placer as up

    # --- BUG 1: the wait condition was satisfied by promotions -------------
    # Coolbet's search overlay renders five promoted fixtures ('Lecce vs AS
    # Roma' ...), identical whatever you type, BEFORE the real results arrive.
    # The old condition was "more than one link with text", which promotions
    # satisfy instantly, so the read could come back holding only promotions.
    # They are rendered 'A vs B' with no kickoff, so every one fails
    # _split_teams and the pass reported "search returned no fixtures" for a
    # fixture Coolbet was about to list.
    assert up._split_teams("Lecce vs AS Roma") == ("", ""), \
        "a promoted row must not parse as a fixture"
    search_src = inspect.getsource(up.search_events)
    assert "_DT_PATTERN" in search_src, \
        "the wait must key on a kickoff, which only real results carry"
    assert "length > 1" not in search_src, \
        "counting rows cannot distinguish promotions from results"

    # --- BUG 2: the month token is not three letters -----------------------
    # Estonian abbreviates September 'sept', February 'veebr'. The old pattern
    # required exactly \w{3} then a separator, so it matched 'aug' and failed
    # the rest. Not a cosmetic parse miss: an empty start_text makes
    # start_matches() return None, pick_event treats the fixture as having no
    # kickoff to check, and its hard reject on a disagreeing date cannot fire.
    assert up._start_text("X - Y 31 aug 23:00 Jalgpall") == "31 aug 23:00"
    assert up._start_text("X - Y 01 sept 23:00 Jalgpall") == "01 sept 23:00", \
        "a 4-letter month must parse — this is what disarmed the date guard"
    assert up._start_text("A - B 27 aug, 19:00") == "27 aug, 19:00"
    assert up._start_text("C - D 03 veebr 18:45") == "03 veebr 18:45"

    # Same assumption broke the away name, which was cut at the kickoff.
    assert up._split_teams(
        "Atl\u00e9tico Grau - FBC Melgar 01 sept 23:00 Jalgpall / Primera Divisi\u00f3n"
    ) == ("Atl\u00e9tico Grau", "FBC Melgar"), "the date must not glue onto the away name"

    # --- The consequence, end to end ---------------------------------------
    # Atletico Grau v FBC Melgar: postponed 31 Aug -> 1 Sept, Coolbet moved,
    # API-Football did not. With start_text blank this MATCHED on names alone
    # and would have been bet. It must now be refused, and refused as a date
    # mismatch rather than as missing coverage.
    row = "Atl\u00e9tico Grau - FBC Melgar 01 sept 23:00 Jalgpall / Primera Divisi\u00f3n"
    h, a = up._split_teams(row)
    moved = up.UiEvent("6062800", "/et/sport/match/6062800", row, h, a, up._start_text(row))
    ours = datetime(2026, 8, 31, 20, 0, tzinfo=timezone.utc)
    assert up.parse_start(moved.start_text, ours) == datetime(2026, 9, 1, 20, 0, tzinfo=timezone.utc), \
        "01 sept 23:00 Tallinn is 1 Sept 20:00 UTC"
    assert up.start_matches(moved.start_text, ours) is False
    # With start_text blank this used to match on names alone. Now the kickoff
    # parses, so the fixture is recognised AS MOVED rather than silently
    # treated as same-day — which is what makes the operator's
    # bet-it-anyway rule (COOLBET-MOVED-FIXTURE) a decision rather than an
    # accident.
    assert up.pick_event([moved], "Atletico Grau", "FBC Melgar", ours,
                         allow_moved=False) is None, \
        "without the moved rule the postponed fixture must not be bet"
    assert up.pick_event([moved], "Atletico Grau", "FBC Melgar", ours) is not None, \
        "with it, a lone postponement is taken deliberately"
    assert up._date_rejected_candidates([moved], "Atletico Grau", "FBC Melgar", ours), \
        "and is recognised as a date mismatch, not as same-day"
    # On its real date the same row must still match — the guard rejects the
    # wrong day, not the fixture.
    right = datetime(2026, 9, 1, 20, 0, tzinfo=timezone.utc)
    assert up.pick_event([moved], "Atletico Grau", "FBC Melgar", right) is not None

    # Novara v Folgore Caratese died in the SAME pass from the promo race
    # alone — its kickoff agrees, so once the row is actually read it is a
    # plain match and must be placeable.
    nov = up.UiEvent("1", "/x", "", "Novara", "US Folgore Caratese", "31 aug 21:30")
    nko = datetime(2026, 8, 31, 18, 30, tzinfo=timezone.utc)
    assert up.start_matches(nov.start_text, nko) is True
    assert up.pick_event([nov], "Novara", "Folgore Caratese", nko) is not None, \
        "a fixture whose kickoff agrees must match"
    assert not up._date_rejected_candidates([nov], "Novara", "Folgore Caratese", nko)

    return "search waits for a real result; 4-letter Estonian months parse; date guard armed again"


@test("COOLBET-MOVED-FIXTURE")
def test_coolbet_moved_fixture_2026_08_31():
    """COOLBET-MOVED-FIXTURE-2026-08-31 — a postponed fixture is a bet we should
    take, not one to throw away. Operator call: if the model found a good game,
    a date our own feed has wrong is not a reason to skip it."""
    import inspect
    from datetime import datetime, timezone
    from workers.automation import coolbet_ui_placer as up

    ours = datetime(2026, 8, 31, 20, 0, tzinfo=timezone.utc)
    moved = up.UiEvent("6062800", "/a", "", "Atl\u00e9tico Grau", "FBC Melgar", "01 sept 23:00")

    # THE CASE. Atletico Grau v FBC Melgar moved 31 Aug -> 1 Sept; Coolbet
    # moved with it and the press agrees with Coolbet, not with API-Football.
    # A lone same-team candidate has nothing to be confused with, so it is our
    # fixture on a date we have wrong. Take it.
    got = up.pick_event([moved], "Atletico Grau", "FBC Melgar", ours)
    assert got is not None and got.match_id == "6062800", \
        "a lone moved fixture must be bet, not refused"

    # THE LIMIT, and the reason the guard existed. Two same-team candidates on
    # different days is a two-legged tie: the kickoff is the ONLY thing telling
    # them apart, so taking either backs a coin flip.
    leg2 = up.UiEvent("2", "/b", "", "Atl\u00e9tico Grau", "FBC Melgar", "07 sept 23:00")
    assert up.pick_event([moved, leg2], "Atletico Grau", "FBC Melgar", ours) is None, \
        "two legs must never be guessed between"

    # A date-AGREEING candidate must always win over a moved one, whatever the
    # names say — the moved path is a fallback, never a preference.
    agree = up.UiEvent("3", "/c", "", "Atl\u00e9tico Grau", "FBC Melgar", "31 aug 23:00")
    assert up.pick_event([moved, agree], "Atletico Grau", "FBC Melgar", ours).match_id == "3"

    # Bounds, so "moved" cannot become "any fixture with these teams":
    #  - a higher name bar than normal, since the kickoff evidence is gone
    weak = up.UiEvent("4", "/d", "", "Grau Sport", "Melgar B", "01 sept 23:00")
    assert up.pick_event([weak], "Atletico Grau", "FBC Melgar", ours) is None, \
        "a moved candidate is held to a HIGHER name bar, not a lower one"
    #  - a reschedule window; the same teams months out is a different round
    far = up.UiEvent("5", "/e", "", "Atl\u00e9tico Grau", "FBC Melgar", "30 nov 23:00")
    assert up.pick_event([far], "Atletico Grau", "FBC Melgar", ours) is None, \
        "3 months out is a different round, not a postponement"
    #  - COOLBET-SQUAD-GUARD outranks all of it
    res = up.UiEvent("6", "/f", "", "Atl\u00e9tico Grau Res.", "FBC Melgar Res.", "01 sept 23:00")
    assert up.pick_event([res], "Atletico Grau", "FBC Melgar", ours) is None

    # The old behaviour stays reachable, so this is a policy switch rather than
    # a one-way door.
    assert up.pick_event([moved], "Atletico Grau", "FBC Melgar", ours, allow_moved=False) is None
    sig = inspect.signature(up.pick_event).parameters
    assert sig["allow_moved"].default is True
    assert sig["min_score_moved"].default > sig["min_score"].default, \
        "the moved bar must be stricter than the ordinary one"
    assert sig["max_move_days"].default == 7.0

    # Accepting a moved fixture must be LOUD — the stale date also drives the
    # kickoff cutoff, the pick's eligibility window and settlement.
    src = inspect.getsource(up.pick_event)
    assert "MOVED FIXTURE accepted" in src
    assert "AMBIGUOUS DATE" in src

    return "a lone postponed fixture is bet; two legs still refused; squad guard unaffected"


@test("MODEL-SPLIT-VERSION-GUARD — per-market model routing survives refactors")
def test_model_split_version_guard():
    """Production serves DIFFERENT model versions per market head, and the
    weekly eval has already been burned once by assuming a single global
    baseline (WEEKLY-EVAL-BASELINE-2026-08-26).

    On 2026-08-31 the live split was global=v20260712 / OU=v20260719 /
    1X2=v20260823 — i.e. the global MODEL_VERSION served NO market head, so
    every weekly comparison scored candidates against a model that was not
    live. Guard the resolver that makes the split expressible, so a refactor
    that collapses it back to one global version fails loudly here.
    """
    import inspect
    from workers.model import xgboost_ensemble as xe

    assert hasattr(xe, "_resolve_version"), \
        "per-market resolver _resolve_version must exist — production is split by market"
    src = inspect.getsource(xe._resolve_version)
    # Tier-specific OU override must be checked BEFORE the per-market one,
    # and the bare global must remain the last-resort fallback.
    for var in ("MODEL_VERSION_OU_T", "MODEL_VERSION_", "MODEL_VERSION"):
        assert var in src, f"_resolve_version must consult {var}"
    assert src.index("MODEL_VERSION_OU_T") < src.index("MODEL_VERSION_{"), \
        "tier-specific OU override must be resolved before the generic per-market one"
    return "per-market model routing intact (global/OU/1X2 may differ)"


@test("WEEKLY-EVAL-PERMARKET-BASELINE — each market scored against the version that serves it")
def test_weekly_eval_per_market_baseline():
    """The weekly retrain email scored EVERY market against one global
    MODEL_VERSION. Since 2026-07-19 that global has served no market head at
    all (1X2 -> v20260823, OU -> v20260719, global -> v20260712), so every
    weekly verdict compared against a model that was not live anywhere.
    The 2026-08-26 fix only printed a warning; the table stayed wrong.

    Also guards the no-skill column: a head that loses to a constant fixed at
    the observed base rate has no skill regardless of how it scores against
    the incumbent, which is how the OU 2.5 and BTTS heads stayed invisible.
    """
    import ast
    from pathlib import Path as _P
    src = _P(__file__).resolve().parent.parent / "scripts" / "weekly_eval_and_compare.py"
    code = src.read_text()
    ast.parse(code)  # must stay importable

    # Per-market routing table, and every evaluated market must be mapped.
    assert "MARKET_HEAD" in code, "eval must map each market to its model head"
    for mkt in ("1x2_home", "over25", "btts_yes", "ah_home_+0.5"):
        assert f'"{mkt}"' in code, f"{mkt} must appear in the market->head map"
    assert "_resolve_version" in code, \
        "baselines must be resolved the way inference resolves them, not from the global env"
    assert "baseline_for" in code and "by_version" in code, \
        "each distinct live baseline must be evaluated and applied per market"

    # The legacy single-baseline path must remain reachable but opt-in.
    assert "--single-baseline" in code, "legacy single-baseline mode must stay available"
    assert 'default=False' in code.split("--single-baseline")[1][:400], \
        "per-market baselines must be the DEFAULT; single-baseline is the escape hatch"

    # No-skill guard.
    assert "_no_skill" in code and "NO SKILL" in code, \
        "eval must flag heads that lose to a base-rate constant"
    assert "no_skill_markets" in code, "SUMMARY_JSON must carry the no-skill list for the digest"
    return "per-market baselines are the default; no-skill heads are flagged"


@test("COOLBET-UI-PLACER-AUDIT-WARN — audit reconciliation counts THIS run, not the last hour")
def test_coolbet_ui_placer_audit_warn():
    """The end-of-pass audit check must compare like with like.

    It used to count coolbet_placement_attempts rows from the last HOUR across
    all runs and compare that to len(picks). Both sides were wrong, so it
    warned on nearly every pass:
      - the job runs hourly, so a pass at :00 also counted the previous run's
        rows;
      - len(picks) counts every loaded pick, but three branches deliberately
        write no attempt row — already_placed (the dedup that makes re-running
        safe, so ANY prior placement guaranteed the warning), the
        kickoff-cutoff skip, and the daily-cap break.

    This matters because the check exists to catch the audit INSERT silently
    rolling back, on the code path that places real money unattended. A
    warning that is wrong nearly every run trains the operator to ignore the
    one run where the audit trail really is broken ([[feedback_silent_failures]]).
    """
    import ast
    from pathlib import Path as _P
    src_path = _P(__file__).resolve().parent.parent / "scripts" / "place_coolbet_ui.py"
    src = src_path.read_text()
    ast.parse(src)

    # The old, wrong shape must be gone on both sides.
    assert "NOW() - INTERVAL '1 hour'" not in src, (
        "audit reconciliation must not count the last hour across all runs — "
        "the job runs hourly, so that folds in the previous pass"
    )
    assert "if recorded < len(picks):" not in src, (
        "audit reconciliation must not compare against len(picks) — "
        "already_placed / kickoff-cutoff / daily-cap write no attempt row"
    )

    # The corrected shape: a run-scoped lower bound, and an explicit counter.
    assert "run_started" in src and "attempted_at >= %s" in src, (
        "recorded count must be bounded by this run's start timestamp"
    )
    assert "if recorded < expected_rows:" in src, (
        "the warning must fire on expected_rows, not on the pick count"
    )

    # expected_rows must be incremented at BOTH write points and nowhere the
    # code writes no row. stage_bet writes on every exit; exposure_guard writes
    # its own row. If a third write site appears without a matching increment,
    # the warning silently under-counts and stops firing when it should.
    tree = ast.parse(src)
    main_fn = next(n for n in ast.walk(tree)
                   if isinstance(n, ast.FunctionDef) and n.name == "main")
    stores = [n.lineno for n in ast.walk(main_fn)
              if isinstance(n, ast.Name) and n.id == "expected_rows"
              and isinstance(n.ctx, ast.Store)]
    assert len(stores) == 3, (
        f"expected_rows should be initialised once and incremented at exactly "
        f"the 2 attempt-writing sites (exposure_guard, stage_bet); found "
        f"{len(stores)} assignments"
    )

    # Guard the invariant the whole fix rests on: the run-scoped window is only
    # sound because the pass holds an exclusive non-blocking lock throughout.
    assert "fcntl.LOCK_EX | fcntl.LOCK_NB" in src, (
        "run-scoped counting assumes passes cannot overlap — keep the "
        "exclusive single-run lock"
    )
    return "audit warning reconciles this run's rows against actual write sites"


@test("EPICBET-403-FROM-VPS — FS fallback on 403, job raises, freshness watchdog wired")
def test_epicbet_403_from_vps():
    """EPICBET-403-FROM-VPS-2026-08-29 — two failures, not one.

    1. Cloudflare 403s every Epicbet call from the VPS. EPICBET-ODDS-INGEST
       claimed the site "hits no bot-protection"; that was only tested from a
       residential IP. Cookie harvesting does NOT fix it — FlareSolverr earns a
       cf_clearance but replaying it from plain requests still 403s, because
       Cloudflare binds clearance to the browser's TLS fingerprint. So the
       calls themselves route through FS, matching what the Coolbet odds
       reader already does (API + named FS session; only PLACEMENT drives a
       browser).

    2. The job caught every exception and returned normally, so _run_job
       recorded status='completed' and pinged Kuma up. 277 consecutive runs
       over six days reported success while writing zero rows
       ([[feedback_silent_failures]]).
    """
    import inspect
    import pathlib
    import requests as _rq
    from workers.automation import epicbet_explorer as ee

    # ── 1. transport: direct first, FS only after a block ────────────────
    calls = {"fs_open": 0, "fs_get": 0}

    class _Direct:
        """Fake requests.Session yielding a scripted status."""
        def __init__(self, status): self.status = status; self.hits = 0
        def get(self, *_a, **_kw):
            self.hits += 1
            r = _rq.Response()
            r.status_code = self.status
            r._content = b'{"result":{"data":[1,2,3]}}'
            if self.status != 200:
                raise _rq.HTTPError(response=r)
            return r

    orig_open, orig_get = ee._fs_open, ee._fs_get_json
    try:
        ee._fs_open = lambda sess: (calls.__setitem__("fs_open", calls["fs_open"] + 1),
                                    setattr(sess, "_fs_on", True))[0]
        ee._fs_get_json = lambda url, **kw: (calls.__setitem__("fs_get", calls["fs_get"] + 1),
                                             {"result": {"data": ["via-fs"]}})[1]

        ok = _Direct(200)
        assert ee._get(ok, "/x") == [1, 2, 3], "a 200 must be served directly"
        assert calls["fs_open"] == 0, "FlareSolverr must NOT be used when direct works"

        blocked = _Direct(403)
        assert ee._get(blocked, "/x") == ["via-fs"], "a 403 must fall back to FlareSolverr"
        assert calls["fs_open"] == 1 and calls["fs_get"] == 1

        # Once blocked, the rest of the run stays on FS rather than re-probing.
        assert ee._get(blocked, "/y") == ["via-fs"]
        assert calls["fs_open"] == 1, "FS session must be created once per run, not per call"

        # A non-block error must surface, not be masked as a bot-protection hit.
        try:
            ee._get(_Direct(500), "/x")
            raise AssertionError("HTTP 500 must propagate, not silently route via FS")
        except _rq.HTTPError:
            pass
    finally:
        ee._fs_open, ee._fs_get_json = orig_open, orig_get

    # Session teardown must exist and be safe on a session that never used FS.
    ee.fs_close(_Direct(200))

    # ── 2. the job must RAISE, not swallow ───────────────────────────────
    sched = pathlib.Path(__file__).resolve().parent.parent / "workers/scheduler.py"
    src = sched.read_text()
    job = src[src.index("def job_epicbet_odds_snapshot("):
              src.index("def _epicbet_odds_snapshot_wrapper(")]
    assert "except Exception" not in job, (
        "job_epicbet_odds_snapshot must not catch and return — that is what "
        "recorded 277 'completed' runs while the feed was dead. _run_job "
        "already isolates jobs from each other."
    )

    # ── 3. the watchdog that would have caught it in 2h, not 6 days ──────
    from workers.jobs.odds_freshness import check_feed, FEEDS
    assert "Epicbet" in FEEDS, "Epicbet must have a freshness profile"
    assert 'id="epicbet_odds_freshness"' in src, "watchdog must be registered"
    assert inspect.signature(check_feed).parameters["bookmaker"], (
        "freshness check must be per-bookmaker so a third book is one call"
    )
    return "403 falls back to FS once per run; job raises; watchdog registered"


@test("BOOK-UPLIFT-REPORT — cross-book comparison matches on handicap_line")
def test_book_uplift_report():
    """The AH trap, guarded.

    Asian-handicap `selection` is only 'home'/'away'; the line lives in a
    separate `handicap_line` column. Joining two books on
    (match, market, selection) alone compares a -0.5 quote against a -1.5 and
    reports nonsense — the first run of this comparison claimed Epicbet was
    +22.62% better on AH where the line-matched answer is +0.86%. Same class
    as ANALYSIS_GOTCHAS #16.

    Checks the join is line-matched, and then — when there is live data —
    that the number it produces is physically plausible. An unmatched join
    shows up as a double-digit "uplift", so the range assertion catches the
    bug behaviourally rather than by reading the SQL.
    """
    import inspect
    import scripts.book_uplift_report as rep

    sql = rep._LATEST + inspect.getsource(rep.per_market)
    assert "handicap_line IS NOT DISTINCT FROM" in sql, (
        "cross-book join must match on handicap_line — without it, AH quotes "
        "on different lines are compared and the result is meaningless"
    )
    assert "IS NOT DISTINCT FROM" in sql and "= y.handicap_line" not in sql, (
        "use IS NOT DISTINCT FROM, not '=' — a plain equality drops every "
        "non-handicap market, whose handicap_line is NULL"
    )
    # DISTINCT ON keeps one quote per book per outcome; without it, fixtures
    # we happened to poll more often would dominate the average.
    assert "DISTINCT ON" in rep._LATEST, (
        "must reduce to the latest quote per (match, market, selection, line, "
        "book) or polling frequency skews the comparison"
    )

    from workers.api_clients.db import get_conn
    with get_conn() as conn, conn.cursor() as cur:
        rows = rep.per_market(cur, 48, "Coolbet", "Epicbet", upcoming=False)
    ah = [r for r in rows if r[0] == "asian_handicap"]
    if not ah:
        return "join is line-matched (no AH overlap in window to range-check)"
    _m, n, _pct, avg_diff, uplift = ah[0]
    assert abs(float(avg_diff)) < 10.0, (
        f"AH average price difference is {avg_diff}% across {n} pairs. Two soft "
        "books do not differ by that much on the same line — the join has "
        "almost certainly come unmatched from handicap_line again."
    )
    assert 0.0 <= float(uplift) < 10.0, (
        f"AH best-of-two uplift is {uplift}% — implausible for line-matched quotes"
    )
    return f"line-matched; AH avg diff {avg_diff}% over {n} pairs is plausible"


@test("COOLBET-SQUAD-GUARD-API — women/reserves/U21 cannot match a senior fixture")
def test_coolbet_squad_guard_api_path():
    """AF-STALE-FIXTURE-DATES-2026-08-31 was filed as an API-Football date
    problem. Measuring it first — as the ticket asked — turned up something
    worse behind it.

    `coolbet_placer.fuzzy_match_event` had NO squad check. Only the UI placer
    did, which is what "COOLBET-SQUAD-GUARD carries a partial fix; the API
    path is still exposed" meant in practice. Verified before the fix: at an
    identical kickoff it matched a women's fixture to the men's match (score
    80) and a first team to its own reserves (score 100) — either would store
    the wrong book's price under our fixture and hand it to the value bots.

    It only ever looked safe because the date guard fired first: the real
    'Seoul W vs Incheon Red Angels W' was being offered 'FC Seoul vs Incheon
    United' at a different time, so it surfaced as a DATE MISMATCH warning
    rather than as bad odds. Same kickoff and it goes straight through.

    Both directions matter — over-rejecting would silently drop every genuine
    women's or youth fixture, which is the same class of bug pointing the
    other way.
    """
    from datetime import datetime, timezone
    from workers.automation import coolbet_placer as cp

    ko = datetime(2026, 9, 2, 10, 0, tzinfo=timezone.utc)

    def offer(home, away):
        return [{"name": f"{home} vs {away}", "home": home, "away": away,
                 "start": ko.isoformat(), "match_start": ko.isoformat(), "id": "x"}]

    # Must REJECT — squad qualifier differs, kickoff identical so the date
    # guard cannot help.
    for ours, theirs, why in [
        (("Seoul W", "Incheon Red Angels W"), ("FC Seoul", "Incheon United"),
         "women's fixture must not match the men's match"),
        (("Atletico Grau", "FBC Melgar"), ("Atletico Grau Res.", "FBC Melgar Res."),
         "first team must not match its own reserves"),
        (("Man Utd U21", "Leicester U21"), ("Manchester United", "Leicester City"),
         "U21 must not match the senior fixture"),
    ]:
        hit = cp.fuzzy_match_event(ours[0], ours[1], offer(*theirs), ko)
        assert hit is None, (
            f"{why} — matched '{hit.get('name')}' at the same kickoff. The wrong "
            "book price would be stored against our fixture and priced by the bots."
        )

    # Must still MATCH — same squad on both sides.
    for ours in [("FC Seoul", "Incheon United"),
                 ("Real Sociedad W", "Chelsea W"),
                 ("Man Utd U21", "Leicester U21")]:
        assert cp.fuzzy_match_event(ours[0], ours[1], offer(*ours), ko) is not None, (
            f"{ours} must still match its own squad level — over-rejecting "
            "silently drops every genuine women's / youth fixture"
        )

    # The rejection has to be countable, or a guard that stops firing looks
    # identical to one that never fires ([[feedback_silent_failures]]).
    import inspect
    src = inspect.getsource(cp.fuzzy_match_event)
    assert "skipped_squad" in src and "squad-mismatched" in src, (
        "squad rejections must be counted and logged"
    )
    return "women/reserves/U21 rejected at identical kickoff; same-squad still matches"


@test("COMPETITOR-PICKS-STALE — the scraped data itself must be recent, not just the JSON")
def test_competitor_picks_stale():
    """COMPETITOR-AUDIT-FRESH checks `snapshot_at_utc` and `status`. Neither
    can see the failure mode that actually happened.

    The audit workflow runs daily and recomputes comparison_*.json from
    ledger/picks_*.csv. If a SCRAPER stops producing but the last-good picks
    file is still on disk, the audit happily recomputes from month-old rows
    and writes a snapshot stamped today with status 'ok'. Measured 2026-09-02:

        winnerodds   1,852 rows   newest pick 2026-08-29   ok
        deepbetting    479 rows   newest pick 2026-08-29   ok
        forebet      1,832 rows   newest pick 2026-07-31   <-- 33 days stale,
                                                               status STILL 'ok'
        signalodds       0 rows   (header only)
        tipstrr          0 rows   (header only)

    Forebet was rendering month-old figures on the public landing page as
    live, with today's date and no marker, because every signal the old test
    looks at was green. The only honest check is the newest kickoff_date
    INSIDE the picks file — file mtime is useless (git does not preserve it,
    and CI checkout rewrites it).
    """
    import csv
    import pathlib
    import re
    from datetime import date, timedelta

    ledger = pathlib.Path(__file__).resolve().parent.parent / "ledger"
    if not ledger.is_dir():
        raise SkipTest("ledger/ not present")

    # Generous: these are weekly scrapes of settled picks, so a fortnight of
    # slack absorbs a skipped cron and a competitor's own reporting lag. The
    # failure this guards against is measured in months.
    MAX_AGE_DAYS = 21

    # Tipstrr publishes at (tipster x month) grain — per-bet selections are not
    # exposed — so every row is stamped the 1st of a month. Early in a month the
    # newest complete bucket is inherently ~30-35 days old, which is not
    # staleness. Give it a grain-aware allowance rather than excluding it, so a
    # genuinely dead Tipstrr scrape still fails here.
    MAX_AGE_BY_SOURCE = {"tipstrr": 50}

    # Only books we scrape ourselves. Betaminic is auth-gated by design and
    # has no picks file.
    expect = ["winnerodds", "deepbetting", "forebet", "signalodds", "tipstrr"]
    stale, empty = [], []
    for key in expect:
        f = ledger / f"picks_{key}.csv"
        if not f.exists():
            empty.append(f"{key} (no picks file)")
            continue
        with f.open() as fh:
            rows = list(csv.DictReader(fh))
        if not rows:
            empty.append(f"{key} (0 rows)")
            continue
        newest = None
        for r in rows:
            v = (r.get("kickoff_date") or "")[:10]
            if re.match(r"^\d{4}-\d{2}-\d{2}$", v) and (newest is None or v > newest):
                newest = v
        if newest is None:
            empty.append(f"{key} (no parseable kickoff_date)")
        else:
            limit = MAX_AGE_BY_SOURCE.get(key, MAX_AGE_DAYS)
            age = (date.today() - date.fromisoformat(newest)).days
            if age > limit:
                stale.append(f"{key} (newest pick {newest}, {age}d old, limit {limit}d)")

    problems = empty + stale
    assert not problems, (
        "competitor picks data is stale or empty: " + "; ".join(problems) +
        ". The audit will keep recomputing a fresh-looking comparison_*.json "
        "from these rows and the landing page will present them as current. "
        "Fix the scraper, or drop the competitor from the comparison set — do "
        "not let a stale row render as live."
    )
    return (f"all {len(expect)} scraped competitors within their freshness "
            f"limit ({MAX_AGE_DAYS}d; tipstrr {MAX_AGE_BY_SOURCE['tipstrr']}d for month-grain)")


@test("COMP-FALLBACK-DRIFT-GUARD — landing's offline competitor figures are guarded")
def _comp_fallback_guard():
    """The landing publishes named competitors' ROI, with COMP_FALLBACK in
    page.tsx as the copy served when the live ledger fetch fails. That copy
    silently rotted for two months (2026-07-05 -> 2026-09-02) because the
    engine's refresh step is gated on a cross-repo PAT that is not set, and
    exits 0 when it is missing. It published Tipstrr at -5.22% ROI while the
    ledger said +1.49% — a sign error about a named competitor.

    Source-inspection only: the guard itself lives in odds-intel-web and runs
    in that repo's CI, which is the point (the ledger is public, so the check
    needs no PAT and cannot be skipped for want of a credential). What this
    test protects is the engine half — that betaminic is actually in the sync
    key list, and that the PAT skip is loud rather than silent.
    """
    import re as _re
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    sync = (root / "scripts" / "update_frontend_comp_fallback.py").read_text()
    keys = _re.search(r"LEDGER_KEYS\s*=\s*\[(.*?)\]", sync, _re.S)
    assert keys, "LEDGER_KEYS not found in update_frontend_comp_fallback.py"
    found = set(_re.findall(r'"(\w+)"', keys.group(1)))
    expected = {"winnerodds", "signalodds", "deepbetting", "forebet", "betaminic"}
    missing = expected - found
    assert not missing, (
        f"competitors missing from LEDGER_KEYS: {sorted(missing)}. A source on "
        "the landing page but absent here never gets its fallback refreshed, so "
        "it freezes at whatever was hardcoded and the page keeps publishing it "
        "as current."
    )
    # TIPSTRR-DROPPED-2026-09-02. Pinned as an absence, not just deleted: the
    # audit still runs and the ledger JSON is still written, so the key is
    # sitting right there for someone to re-add without knowing why it went.
    # Tipstrr is a MARKETPLACE — the figure we published was a consequence of
    # which tipsters we happened to list (3 of 8 hand-written slugs out of
    # thousands, all three inactive), pooled across all bet types at month
    # grain because per-bet market detail is paywalled. It can never be made
    # like-for-like with our 1X2 + OU 2.5 cohort.
    assert "tipstrr" not in found, (
        "tipstrr must stay out of LEDGER_KEYS — it is a tipster marketplace, "
        "not a competitor product, and its figure cannot be market-matched to "
        "ours. If it is being re-added deliberately, update this test and "
        "COMP_META together."
    )

    wf = (root / ".github" / "workflows" / "competitor_audits_weekly.yml").read_text()
    assert "::warning title=COMP_FALLBACK" in wf, (
        "the FRONTEND_REPO_TOKEN skip in competitor_audits_weekly.yml must emit "
        "a ::warning annotation. A plain echo is invisible in the run summary, "
        "which is exactly how this step skipped daily for two months unnoticed."
    )
    return (f"{len(expected)} sources in LEDGER_KEYS; PAT skip emits a "
            "::warning annotation")


@test("FOREBET-REPRICE — landing publishes Forebet's picks at real odds, not their claimed odds")
def _forebet_reprice():
    """FOREBET-ODDS-CROSS-SOURCE showed Forebet's quoted prices are frequently
    unobtainable (9.5% of picks claim >1.5x the best price available anywhere,
    against 0.7% for a third-party control, concentrated on winners at
    p=2.4e-06). The landing nonetheless published +12.44% ROI — a number
    computed entirely FROM those odds — while footnoting that the odds were not
    real. This pins the fix: their_stats is the repriced record.

    The trap being guarded is subtler than 'is a reprice present'. The
    verification script prices bets at MAX(odds) over ALL snapshots ever, to be
    maximally generous when asking 'was this reachable at all'. Reusing that as
    an EXECUTION price rates Forebet at +37.66% — better than their own claim —
    because nobody catches the all-time high of every line. Execution prices
    must come from the CLOSING line, so that is asserted directly.
    """
    import json as _json
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent

    src = (root / "scripts" / "_competitor_reprice.py").read_text()
    assert "o.timestamp <= m.date" in src, (
        "repricing must use the closing line (last quote at or before "
        "kickoff). A post-kickoff in-play quote is a different bet."
    )
    assert "DISTINCT ON (o.bookmaker)" in src, (
        "one closing quote PER BOOK, or MAX() picks the all-time high across "
        "every snapshot and rates the competitor better than they claim"
    )
    assert "MAX(odds) FILTER (WHERE bookmaker = 'Bet365')" in src

    audit = (root / "scripts" / "audit_vs_forebet.py").read_text()
    assert '"their_stats_claimed_odds"' in audit, (
        "Forebet's own published figure must be kept verbatim and labelled — "
        "we are repricing their picks, not hiding what they claim"
    )
    assert 'rep["at_best_close"]' in audit, (
        "their_stats must publish the BEST closing price, the most favourable "
        "realistic assumption for them. Publishing at_median_close would "
        "overstate our case."
    )

    led = root / "ledger" / "comparison_forebet.json"
    if not led.exists():
        raise SkipTest("comparison_forebet.json not built yet")
    j = _json.loads(led.read_text())
    ts = j.get("their_stats") or {}
    assert ts.get("priced_at", "").startswith("best closing"), (
        f"their_stats must be the repriced figure, got priced_at="
        f"{ts.get('priced_at')!r}"
    )
    assert "n_total_picks" in ts and "coverage_pct" in ts, (
        "the repriced figure must state its own coverage — a recomputed "
        "number whose sample is unstated invites the 'your data is thin' "
        "dismissal this work exists to remove"
    )
    claimed = (j.get("their_stats_claimed_odds") or {}).get("roi_pct")
    assert claimed is not None, "their claimed ROI must still be published"
    assert ts.get("roi_pct") is not None and ts["roi_pct"] < claimed, (
        f"repriced ROI ({ts.get('roi_pct')}%) should sit below their claimed "
        f"ROI ({claimed}%) — if it does not, the repricing is not doing "
        "anything and the finding needs re-examining, not shipping"
    )
    return (f"repriced {ts['roi_pct']:+.2f}% over {ts['n']} of "
            f"{ts['n_total_picks']} picks vs claimed {claimed:+.2f}%")


@test("STALE-BEST-ODDS — every odds query takes the LATEST quote per book, not the all-time high")
def _stale_best_odds():
    """STALE-BEST-ODDS-2026-09-02. `_load_today_from_db` selected every
    non-closing snapshot ever written for a fixture with no recency
    constraint, then took max() across the lot. So "best odds" meant the
    highest price ANY book showed at ANY time, and `recommended_bookmaker`
    named whoever posted that high-water mark hours earlier.

    Dandenong City v Preston Lions: Betano showed 3.70 until 05:00, crashed to
    2.82, and the pipeline stored "3.70 at Betano" at 05:08/05:14/05:44/06:15/
    06:44 while the best accessible price was 10Bet 3.10. Each 30-min refresh
    re-derived the stale peak instead of correcting it, because the refresh
    re-runs this same query.

    Measured on scheduled fixtures at fix time: 34.2% of 1X2 selections had a
    historical max above the latest-per-book max, mean +6.3%, worst 2.27x.
    Snapshot history runs ~15 days because pruning only touches finished
    matches, so "any time" really is any time.

    The shadow passes were NOT exempt: `_run_no_pin_shadow_pass` and
    `_run_sweep_shadow_pass` carried the identical bug, and those bots'
    signals are followed with real money.
    """
    import re as _re
    from pathlib import Path as _Path
    src = (_Path(__file__).resolve().parent.parent
           / "workers" / "jobs" / "daily_pipeline_v2.py").read_text()

    # Every query that aggregates odds_snapshots into a "best price" must
    # collapse to one row per bookmaker first. Checked structurally rather
    # than by counting occurrences, so adding a new pass cannot slip through.
    for fn_name in ("_load_today_from_db", "_run_no_pin_shadow_pass",
                    "_run_sweep_shadow_pass"):
        i = src.index(f"def {fn_name}")
        # up to the next top-level def
        m = _re.compile(r"\ndef ").search(src, i + 10)
        body = src[i:m.start() if m else len(src)]
        assert "FROM odds_snapshots" in body, f"{fn_name}: expected an odds query"
        # Check the SELECT that actually reads odds_snapshots, not merely that
        # the function contains a DISTINCT ON somewhere — _load_today_from_db
        # has three, and an earlier version of this test passed while its odds
        # query was unguarded.
        for m2 in _re.finditer(r"FROM odds_snapshots", body):
            head = body[max(0, m2.start() - 700):m2.start()]
            sel = head.rfind("SELECT")
            assert sel >= 0, f"{fn_name}: could not locate the SELECT"
            clause = head[sel:]
            dm = _re.search(r"DISTINCT ON \(([^)]*)\)", clause, _re.S)
            assert dm, (
                f"{fn_name} reads odds_snapshots without DISTINCT ON — it "
                "takes the maximum price across the WHOLE polling history "
                "instead of the latest quote per book, and stores a price no "
                "book is offering (STALE-BEST-ODDS-2026-09-02)"
            )
            assert "bookmaker" in dm.group(1), (
                f"{fn_name}: DISTINCT ON must key on bookmaker — collapsing "
                f"without it drops books entirely. Got: {dm.group(1)!r}"
            )
            tail = body[m2.start():m2.start() + 900]
            assert "timestamp DESC" in tail, (
                f"{fn_name}: DISTINCT ON without ORDER BY ... timestamp DESC "
                "picks an arbitrary row per book, not the current one"
            )

    # The outlier guard's Pinnacle anchor rides on that same recency: it does
    # next(... if b == "Pinnacle") over the rows, so a history-wide result set
    # anchors it to a stale Pinnacle price. On Dandenong it anchored to 2.81
    # (ceiling 3.79) and waved through the stale 3.70; the live 2.73 caps at
    # 3.69 and would have rejected it. The guard was defeated by the very
    # staleness it exists to catch.
    i = src.index("outlier_anchor: dict[str, dict[str, float]]")
    assert "DEPENDS ON the DISTINCT ON" in src[i - 200:i + 900], (
        "the outlier anchor's dependency on the recency constraint must stay "
        "documented at the anchor — it is silent when broken"
    )
    return ("3 odds queries pinned to latest-per-book; outlier anchor "
            "dependency documented")


@test("SHADOW-BOTS-DETAIL-TRUNCATION — both shadow-bot pages read the deduped view")
def _shadow_dedup_view():
    """SHADOW-BOTS-DETAIL-TRUNCATION-2026-09-02. The dashboard card and the
    per-bot detail page disagreed wildly for the same bot —
    bot_pin_1x2_home_v1 read +12.7% on the card and -11.8% on its detail page
    — because each was aggregating a different fraction of the same ledger.

    Shadow bots persist one row per (cohort x match x market x selection) and
    cohorts fire every 30 minutes, so a pick carries ~10 rows. Both pages
    deduplicated in JS AFTER the fetch, so the row cap bit on RAW rows:

      detail: `.limit(500)` -> 24 of 41 bots truncated. bot_dc_value showed
              48 of its 3,081 picks (1.6%); bot_pin_1x2_home_v1 61 of 304.
      card:   no `.limit()` at all, which is NOT no limit — PostgREST caps at
              db-max-rows, measured at 10,000 against 143,263 rows, so the
              card aggregated 7% of the ledger. A capped response is
              indistinguishable from a complete one, which is why this ran
              unnoticed.

    Both pages now read the pre-existing `shadow_bets_unique` view (migrations
    282/283), so they aggregate the same population by construction.
    """
    from pathlib import Path as _Path
    web = _Path(__file__).resolve().parent.parent.parent / "odds-intel-web"
    if not web.exists():
        raise SkipTest("odds-intel-web not present (CI single-repo checkout)")

    # SHADOW-VIEW-DUPLICATE-2026-09-02: migration 290 created a second dedup
    # view before noticing `shadow_bets_unique` already existed (282/283) with
    # identical semantics — verified 0 rows differed. Migration 293 drops the
    # duplicate. ANALYSIS_GOTCHAS #5 already said to use shadow_bets_unique and
    # ends with "one definition beats two"; shipping a second one is precisely
    # what it warns against.
    root2 = _Path(__file__).resolve().parent.parent
    drop = root2 / "supabase" / "migrations" / "293_drop_shadow_bets_deduped.sql"
    assert drop.exists(), "migration 293 (drop the duplicate view) is missing"
    assert "DROP VIEW IF EXISTS shadow_bets_deduped" in drop.read_text(), (
        "migration 293 must drop the duplicate view"
    )

    for rel in ("src/app/(app)/admin/shadow-bots/page.tsx",
                "src/app/(app)/admin/shadow-bots/[bot]/page.tsx"):
        src = (web / rel).read_text()
        assert 'from("shadow_bets_unique")' in src, (
            f"{rel} must read shadow_bets_unique — reading shadow_bets directly "
            "multiplies every pick by its cohort re-recordings and then lets a "
            "row cap decide which picks count"
        )
        assert 'from("shadow_bets")' not in src, (
            f"{rel} still reads the raw shadow_bets table somewhere; every "
            "per-bot aggregate must come from the deduped view"
        )

    card = (web / "src/app/(app)/admin/shadow-bots/page.tsx").read_text()
    assert ".range(" in card, (
        "the card must paginate: the deduped set is 13,955 rows against a "
        "10,000 db-max-rows cap, so a single unpaginated read is silently "
        "short — the exact failure being fixed"
    )
    return "both pages on shadow_bets_unique; card paginated; duplicate view dropped"


@test("STALE-ODDS-HISTORY-RESTATE — published ROI is priced at odds that were live")
def _restate():
    """STALE-ODDS-HISTORY-RESTATE-2026-09-02. `simulated_bets.pnl` settles from
    `odds_at_pick`, which STALE-BEST-ODDS showed to be a high-water mark across
    a fixture's whole snapshot history rather than a price on offer. So every
    ROI we published was inflated by the same mechanism we criticise Forebet
    for: +15.99% recorded against +10.65% at prices actually live at pick time,
    on the cohort the landing publishes.

    Six audit scripts each carried their own copy of the cohort query. Any one
    of them still summing `pnl` would quietly keep publishing the old number,
    so the query now lives in one module and this pins that none of them
    reintroduce a local copy.
    """
    import json as _json
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent

    helper = (root / "scripts" / "_our_stats.py").read_text()
    # Check the SQL, not the file: an earlier draft asserted the substring
    # anywhere in the module and passed while the SELECT had been changed to
    # `NULL::float AS odds_live`, because the docstring still said the words.
    sql_i = helper.index("_SQL = ")
    sql = helper[sql_i:helper.index('"""', helper.index('"""', sql_i) + 3)]
    assert "sb.odds_at_pick_live" in sql, (
        "the cohort query must SELECT odds_at_pick_live — pricing from `pnl` "
        "republishes the inflated figure (STALE-BEST-ODDS)"
    )
    assert "roi_pct_recorded" in helper, (
        "the recorded figure must still be published alongside the restated "
        "one — repricing a record without showing the original claim is not "
        "transparency, and it is exactly what we fault Forebet for"
    )
    assert "coverage_pct" in helper, (
        "a restated ROI must carry its coverage (ANALYSIS_GOTCHAS #29)"
    )

    for name in ("winnerodds", "signalodds", "deepbetting", "forebet",
                 "tipstrr", "betaminic"):
        src = (root / "scripts" / f"audit_vs_{name}.py").read_text()
        assert "from scripts._our_stats import our_stats" in src, (
            f"audit_vs_{name}.py must use the shared our_stats"
        )
        assert "def our_stats(" not in src, (
            f"audit_vs_{name}.py defines its own our_stats again — that is how "
            "five of six scripts would keep publishing the inflated number"
        )

    # The published ledgers must actually carry the restated shape.
    for name in ("winnerodds", "forebet", "betaminic"):
        led = root / "ledger" / f"comparison_{name}.json"
        if not led.exists():
            continue
        ours = (_json.loads(led.read_text()).get("our_stats_same_window") or {})
        if not ours.get("n"):
            continue
        assert ours.get("priced_at", "").startswith("best price live"), (
            f"comparison_{name}.json still publishes an unrestated our_stats"
        )
        assert ours.get("roi_pct_recorded") is not None, (
            f"comparison_{name}.json must keep the recorded figure for audit"
        )
        assert ours["roi_pct"] < ours["roi_pct_recorded"], (
            f"comparison_{name}.json: restated ROI ({ours['roi_pct']}) should "
            f"sit below the recorded one ({ours['roi_pct_recorded']}) — if not, "
            "the repricing is doing nothing and needs re-examining"
        )
    return "our_stats shared + priced live; recorded figure and coverage retained"


@test("AF-STALE-FIXTURE-DATES — disputed fixtures are recorded and never priced")
def _af_stale_dispute():
    """AF-STALE-FIXTURE-DATES-2026-08-31 steps 2-4. API-Football does not
    always follow a postponement: Atletico Grau v FBC Melgar moved 31 Aug ->
    1 Sept, Coolbet moved with it, AF kept returning the old kickoff at status
    NS. We then price a fixture that is not played, raise a pick on it, and
    settlement finds no result.

    The design decision this pins: we record the DISPUTE and stop pricing,
    rather than overwriting `matches.date` with the book's. The book is usually
    right, but the input is a fuzzy name match, and a wrong correction moves a
    fixture we would otherwise have priced correctly and is then believed over
    AF indefinitely. Suppression costs a handful of picks a week and cannot
    invent a wrong one.
    """
    import re as _re
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent

    mig = root / "supabase" / "migrations" / "292_match_date_disputed.sql"
    assert mig.exists(), "migration 292 (match date dispute) is missing"
    msql = mig.read_text()
    for col in ("date_disputed_at", "date_dispute_source", "date_dispute_value"):
        assert col in msql, f"migration 292 must add {col}"

    # Every fixture-selection query in the betting pipeline must suppress.
    pipe = (root / "workers" / "jobs" / "daily_pipeline_v2.py").read_text()
    n_sched = pipe.count("status = 'scheduled'")
    n_supp = pipe.count("date_disputed_at IS NULL")
    assert n_sched and n_supp >= n_sched, (
        f"{n_sched} scheduled-fixture queries but only {n_supp} carry "
        "`date_disputed_at IS NULL` — a query without it will price a fixture "
        "whose kickoff we cannot trust"
    )

    placer = (root / "workers" / "automation" / "coolbet_placer.py").read_text()
    assert "_record_date_dispute" in placer and "clear_date_dispute" in placer, (
        "the placer must both raise and lift disputes — a flag that only ever "
        "gets set suppresses the fixture forever once AF catches up"
    )

    # The load-bearing safety property: the recorder must never write the date.
    i = placer.index("def _record_date_dispute")
    body = placer[i:placer.index("def clear_date_dispute")]
    assert _re.search(r"SET\s+date_disputed_at", body), (
        "_record_date_dispute must set the dispute columns"
    )
    assert not _re.search(r"SET[^;]*\bdate\s*=", body), (
        "_record_date_dispute must NOT write matches.date — overwriting AF "
        "with a fuzzy-matched book date is the failure mode this design "
        "deliberately avoids"
    )
    assert "status = 'scheduled'" in body, (
        "only scheduled fixtures can be disputed; flagging a finished match "
        "would suppress nothing and confuse settlement"
    )

    # Self-healing: cleared on a successful same-date match.
    assert "clear_date_dispute(match_id)" in placer, (
        "a successful match on the agreed date must lift the dispute"
    )
    return (f"{n_sched} fixture queries suppress disputed dates; recorder never "
            "writes matches.date; dispute self-heals")


@test("BTTS-PLATT-NOT-APPLIED — an uncalibrated pass must not write to calibrated_prob")
def _btts_platt():
    """BTTS-PLATT-NOT-APPLIED-2026-09-02. The sweep and no-pin shadow passes
    score edge straight off the ensemble output and never call
    `calibrate_prob()`. That part is deliberate. What was not deliberate is
    that they wrote the RAW probability into a column named `calibrated_prob`,
    so every downstream reader — including the public /methodology page, which
    tells users "the result is a calibrated_prob per market" — was told Platt
    had been applied when it had not.

    Measured on settled deduped shadow rows, mean model_prob minus actual hit
    rate: bot_sweep_btts_yes_v1 +12.2pp (no Platt), bot_sweep_1x2_home_v1
    +11.1pp, bot_no_pin_home_v1 +16.1pp — but bot_btts_all +16.9pp and
    bot_btts_conservative +12.6pp, and those two DO get Platt. So applying the
    existing calibration would not have fixed the over-confidence; the honest
    fix is to stop mislabelling, and to treat the weak BTTS calibration as its
    own problem.
    """
    import re as _re
    from pathlib import Path as _Path
    src = (_Path(__file__).resolve().parent.parent
           / "workers" / "jobs" / "daily_pipeline_v2.py").read_text()

    # No pass may write a bare probability variable into calibrated_prob.
    bad = _re.findall(r'"calibrated_prob":\s*(prob|raw_mp|model_prob)\b', src)
    assert not bad, (
        f"a pass writes a raw probability into calibrated_prob ({bad}). Either "
        "call calibrate_prob() or record None — populating the column with an "
        "uncalibrated value tells /methodology readers the model was "
        "calibrated when it was not."
    )
    # And the passes that genuinely don't calibrate must say so with None.
    for fn in ("_run_sweep_shadow_pass", "_run_no_pin_shadow_pass"):
        i = src.index(f"def {fn}")
        m = _re.compile(r"\ndef ").search(src, i + 10)
        body = src[i:m.start() if m else len(src)]
        assert '"calibrated_prob": None' in body, (
            f"{fn} does not calibrate, so it must record calibrated_prob=None "
            "rather than the raw ensemble output"
        )
    return "no pass writes a raw probability into calibrated_prob"


@test("INPLAY-RETIRED — in-play betting is off by default; LivePoller settlement survives")
def _inplay_retired():
    """INPLAY-RETIRED-2026-09-03. Four months of in-play paper trading produced
    n=1,246 settled at ROI −0.31%, t=−0.07 — no edge. Priced at odds actually
    live at pick time the repriceable subset is −20.76%, because 76% of in-play
    picks recorded a price no book was showing (an in-play line moves every few
    seconds, so STALE-BEST-ODDS is at its worst here). `clv` is populated on 1
    of 1,246 rows and Pinnacle has zero live coverage ever, so none of it can
    be validated either.

    Two things this pins, and the second matters more than the first:
      1. the bot only runs behind an explicit opt-in env flag;
      2. LivePoller is NOT removed. It is not an in-play-betting component —
         _probe_finishing_matches and settle_finished_matches are how every bet
         in the product gets settled. Deleting the poller to "remove in-play"
         would silently stop settlement.
    """
    import re as _re
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    lp = (root / "workers" / "live_poller.py").read_text()

    assert 'os.getenv("INPLAY_STRATEGIES_ENABLED", "false")' in lp, (
        "in-play strategies must be opt-in — retired 2026-09-03 for having no "
        "measurable edge"
    )
    # Anchor on the CODE, not the comment above it, which also names the flag.
    i = lp.index('os.getenv("INPLAY_STRATEGIES_ENABLED"')
    assert "run_inplay_strategies()" in lp[i:i + 400], (
        "the run_inplay_strategies() call must sit INSIDE the env gate"
    )
    # The settlement path must survive the retirement.
    for keep in ("_probe_finishing_matches", "settle_finished_matches"):
        assert keep in lp, (
            f"{keep} is missing from live_poller — settlement depends on it, "
            "and removing the poller to retire in-play would stop every bet in "
            "the product from settling"
        )

    mig = root / "supabase" / "migrations" / "294_retire_inplay_bots.sql"
    assert mig.exists(), "migration 294 (retire in-play bots) is missing"
    msql = mig.read_text()
    assert "UPDATE bots" in msql and "retired" in msql
    # Strip -- comment lines first: the rationale block legitimately contains
    # the word "delete" (as in "never delete historical bets"), and an earlier
    # draft of this assertion tripped on its own explanation.
    sql_only = "\n".join(l for l in msql.splitlines() if not l.strip().startswith("--"))
    assert not _re.search(r"\bDELETE\s+FROM\b", sql_only, _re.I), (
        "historical in-play bets must NOT be deleted — they are evidence of "
        "due diligence (OUT-OF-BETA-CUTOFF: never delete historical bets)"
    )
    return "in-play opt-in only; LivePoller settlement intact; history kept"


@test("SQL-PERCENT-GUARD — no bare per-cent sign inside a parameterised SQL literal")
def _sql_percent_guard():
    """ANALYSIS_GOTCHAS #6, enforced instead of just documented.

    psycopg2 reads a bare per-cent character in a query string as the start of
    a placeholder, so one in a SQL COMMENT raises "IndexError: tuple index out
    of range" at execute time — with a traceback that points at the caller, not
    at the comment. On 2026-09-03 this took down the 06:00 betting pipeline:
    a rationale comment added to the odds_raw query in `_load_today_from_db`
    quoted measurements like "45 per cent of 1X2 selections" and "mean +3.1
    per cent". The first fix attempt reintroduced it inside the sentence
    warning about it.

    Documented for months and still shipped twice in one day, which is the
    argument for a test rather than a doc line. Escaping as a doubled sign
    works but renders oddly in logs; the rule here is simply not to use the
    character in SQL comments.
    """
    import re as _re
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    offenders = []
    for py in sorted((root / "workers").rglob("*.py")):
        src = py.read_text()
        for m in _re.finditer(r'"""((?:[^"]|"(?!""))*)"""', src):
            body = m.group(1)
            # Only literals that are actually SQL AND touch a table — this
            # must not fire on ordinary docstrings that happen to cite a
            # percentage.
            if not _re.search(r"\b(SELECT|INSERT INTO|UPDATE|DELETE FROM)\b", body):
                continue
            if not _re.search(r"\bFROM\s+\w|\bINTO\s+\w|\bUPDATE\s+\w", body):
                continue
            for ln in body.splitlines():
                if not ln.strip().startswith("--"):
                    continue
                if "%" in ln.replace("%s", "").replace("%%", ""):
                    line_no = src[:m.start()].count("\n") + 1
                    offenders.append(
                        f"{py.relative_to(root)}:~{line_no}: {ln.strip()[:70]}")
    assert not offenders, (
        "bare per-cent sign in a SQL comment — psycopg2 will read it as a "
        "placeholder and raise IndexError at execute time (ANALYSIS_GOTCHAS "
        "#6):\n  " + "\n  ".join(offenders[:6])
    )
    return "no bare per-cent signs in SQL comments across workers/"


@test("SHADOW-SILENT-FAILURE — a failed shadow cohort must not report completed")
def _shadow_silent():
    """SHADOW-SILENT-FAILURE-2026-09-03. `_shadow_run` caught every exception
    and returned normally, so `_run_job` recorded status='completed' and the
    shadow cohorts looked healthy while writing nothing.

    Demonstrated the hard way: a per-cent sign in a SQL comment broke
    `_load_today_from_db` from 2026-09-02 14:57 UTC to 07:20 the next morning.
    `betting_pipeline` re-raises, so it logged four loud failures and was fixed
    within the hour of being noticed. Every shadow cohort over the same ~16
    hours reported completed — shadow_bets fell from 3,269 rows the previous
    day to 7, and nothing said so.

    `_run_job` already isolates jobs from each other, so re-raising costs no
    isolation. Same fix and same reasoning as job_epicbet_odds_snapshot after
    EPICBET-403, where 277 runs reported success while writing zero rows.
    """
    import re as _re
    from pathlib import Path as _Path
    src = (_Path(__file__).resolve().parent.parent / "workers" / "scheduler.py").read_text()
    i = src.index("def _shadow_run(")
    m = _re.compile(r"\ndef ").search(src, i + 10)
    body = src[i:m.start() if m else len(src)]
    assert "except Exception" not in body, (
        "_shadow_run must NOT swallow exceptions — that is how 16 hours of "
        "dead shadow cohorts reported status='completed' on 2026-09-02/03. "
        "_run_job provides the isolation."
    )
    assert "run_morning(" in body, "_shadow_run must still call run_morning"
    # And it must remain wrapped, or re-raising would take the scheduler down.
    assert "_shadow_run" in src.replace(body, ""), (
        "_shadow_run must still be invoked via the scheduler's job wrapper"
    )
    return "_shadow_run raises; failures reach pipeline_runs"


@test("SHADOW-VIEW-COLUMN-DRIFT — shadow_bets_unique exposes every base-table column")
def _shadow_view_drift():
    """SHADOW-VIEW-COLUMN-DRIFT-2026-09-03. A Postgres view freezes its column
    list at creation, so every ALTER TABLE that adds a column to shadow_bets
    leaves the canonical dedup view a column short — silently, because it only
    fails when somebody selects the missing column.

    It happened twice before being noticed: `pair_gap_hours` (migration 289)
    and `odds_at_pick_live` (291). The second bit immediately — an analysis of
    the STALE-BEST-ODDS volume impact had to fall back to an inline DISTINCT ON
    against the base table, which is precisely what ANALYSIS_GOTCHAS #5 exists
    to prevent.

    A DB test rather than a source check: the drift is between the live schema
    and the live view, and no amount of reading migrations proves they agree.
    """
    from workers.api_clients.db import execute_query
    base = {r["column_name"] for r in execute_query(
        "SELECT column_name FROM information_schema.columns "
        "WHERE table_name = 'shadow_bets'")}
    view = {r["column_name"] for r in execute_query(
        "SELECT column_name FROM information_schema.columns "
        "WHERE table_name = 'shadow_bets_unique'")}
    assert view, "shadow_bets_unique is missing entirely"
    missing = base - view
    assert not missing, (
        f"shadow_bets_unique is missing {sorted(missing)}. A view freezes its "
        "column list at creation — recreate it in the same migration that adds "
        "a column to shadow_bets, or every consumer following ANALYSIS_GOTCHAS "
        "#5 silently loses access to the new field."
    )
    return f"view exposes all {len(base)} shadow_bets columns"


@test("SIGNALS-STORE-ON-CHANGE — match_signals writes only on value change; dead signals dropped")
def _signals_store_on_change():
    """SIGNALS-STORE-ON-CHANGE + SIGNALS-NEVER-READ (2026-09-03).

    `match_signals` was 49.3M rows / 13 GB — 35 per cent of a 39.6 GB database
    — holding only 1.56M distinct (match, signal) pairs. Every pipeline run
    re-inserted the entire signal set, so a single match accumulated 8,339 rows
    with `elo_home`, `rest_days_home` and `league_position_home` each written
    130 times at exactly one value.

    Measured over 7 days: of 8,980,369 rows written, 508,962 differed from the
    previous capture. Storing on change removes 94.3 per cent of writes and
    takes the table to roughly 0.7 GB.

    Separately, ten signals were written daily and read nowhere — not in the
    production model's 67 features, not `match_feature_vectors` columns, and no
    consumer in the engine, scripts or odds-intel-web. 3,892,256 rows of them.

    Pinned because both are invisible when they regress: re-inserting unchanged
    rows is not an error, it just quietly costs 12 GB again.
    """
    import re as _re
    from pathlib import Path as _Path
    src = (_Path(__file__).resolve().parent.parent
           / "workers" / "api_clients" / "supabase_client.py").read_text()

    i = src.index("def batch_write_morning_signals(")
    m = _re.compile(r"\ndef ").search(src, i + 10)
    body = src[i:m.start() if m else len(src)]

    assert "prev[(mid, name)] == val" in body, (
        "the writer must compare each signal against its previous stored value "
        "and skip unchanged ones — without it match_signals grows ~31x"
    )
    assert "INSERT INTO match_signals" in body, (
        "expected the bulk insert to still exist"
    )
    assert "changed,\n                    page_size=1000," in body, (
        "the INSERT must write the FILTERED list, not the full signal set — "
        "computing `changed` and then inserting `signals` would silently do "
        "nothing at all"
    )
    assert "if name in _NEVER_READ_SIGNALS:" in body, (
        "the never-read deny-list must be applied inside add()"
    )

    from workers.api_clients.supabase_client import _NEVER_READ_SIGNALS
    assert len(_NEVER_READ_SIGNALS) >= 10
    for n in ("form_vs_elo_expectation_home", "games_remaining_away",
              "goals_for_venue_home", "injury_recurrence_away"):
        assert n in _NEVER_READ_SIGNALS, f"{n} should be on the deny-list"
    # Guard the guard: nothing on the deny-list may be a live model feature.
    feats = _Path(__file__).resolve().parent.parent / "data" / "models"
    if feats.exists():
        import pickle
        for fc in feats.rglob("feature_cols.pkl"):
            try:
                cols = set(pickle.load(open(fc, "rb")))
            except Exception:
                continue
            clash = _NEVER_READ_SIGNALS & cols
            assert not clash, (
                f"{sorted(clash)} is on the never-read deny-list but IS a "
                f"feature of {fc.parent.name} — dropping it would starve that "
                "model. Remove it from the deny-list."
            )
    return "store-on-change wired; 10 never-read signals dropped; no model feature on the deny-list"


@test("PLATT-LIMIT-30-TRUNCATION — every calibrated market is loadable")
def _platt_limit():
    """PLATT-LIMIT-30-TRUNCATION-2026-09-03. `load_platt_params()` read
    `ORDER BY fitted_at DESC LIMIT 30`. The daily settlement fit writes 16 rows
    per run twice a day, so that window covered under one day of fits while
    `model_calibration` holds 29 distinct markets across 1,470 rows.

    13 markets were therefore permanently invisible — btts_yes, btts_no,
    double_chance_1x/x2, asian_handicap* and others. `apply_platt` returns its
    input unchanged for an unknown market, so it was a **silent no-op**: BTTS
    bets went to market on raw ensemble probabilities while the fitting job,
    the DB and the code all looked healthy. btts_yes had a good fit sitting
    unread (a=3.885, b=-2.563, n=261). At p=0.60 the correction is -15.8pp,
    against a measured bot_btts_all over-confidence of +16.9pp.

    Guarded behaviourally, not by grepping for the absence of `LIMIT`: what
    matters is that every market in the table can actually be loaded, however
    the query is written.
    """
    import re as _re
    from pathlib import Path as _Path
    from workers.api_clients.db import execute_query

    # Deliberately NOT via load_platt_params(): it caches in a module global
    # that other tests in this file stub, and it swallows query errors and
    # returns {} — so calling it here made the test pass alone and fail in a
    # group run, for reasons that had nothing to do with the bug. Assert on
    # the SQL it issues, then run that SQL directly.
    src = (_Path(__file__).resolve().parent.parent
           / "workers" / "model" / "improvements.py").read_text()
    i = src.index("def load_platt_params(")
    m = _re.compile(r"\ndef ").search(src, i + 10)
    body = src[i:m.start() if m else len(src)]
    assert "DISTINCT ON (market)" in body, (
        "load_platt_params must take the newest row PER MARKET. It used to read "
        "ORDER BY fitted_at DESC LIMIT 30, and since the daily fit writes 16 "
        "rows twice a day that window held under one day of fits — leaving 13 "
        "of 29 markets permanently invisible."
    )
    # Strip Python comments first: the rationale block above the query names
    # the old "LIMIT 30" verbatim, and an earlier draft of this assertion
    # tripped on its own explanation — the same shape as the per-cent-sign
    # incident earlier today.
    code_only = "\n".join(
        l for l in body.splitlines() if not l.strip().startswith("#"))
    assert not _re.search(r"\bLIMIT\s+\d+", code_only), (
        "no row cap in this query: any cap lets a newly fitted market silently "
        "push another out of scope, which is the original defect"
    )

    in_db = {r["market"] for r in execute_query(
        "SELECT DISTINCT market FROM model_calibration")}
    loaded = {r["market"] for r in execute_query(
        """SELECT DISTINCT ON (market) market FROM model_calibration
            ORDER BY market, fitted_at DESC""")}
    missing = in_db - loaded
    assert not missing, (
        f"{len(missing)} calibrated markets unreachable: {sorted(missing)[:8]}. "
        "apply_platt is a silent no-op for a market it cannot load — the bets "
        "still fire, on uncalibrated probabilities."
    )
    for mk in ("btts_yes", "btts_no"):
        if mk in in_db:
            assert mk in loaded, f"{mk} must be loadable"
    return f"all {len(in_db)} calibrated markets loadable"


@test("ENSEMBLE-RECALIBRATION — calibration is fitted where it is applied, and only when it helps")
def _ensemble_recal():
    """ENSEMBLE-RECALIBRATION-2026-09-03.

    Two defects this pins, both of which shipped harmful calibration:

    1. WRONG SOURCE. `fit_platt.py` fits BTTS/OU from settled `simulated_bets`
       — predictions that PASSED an edge filter, i.e. the tail where the model
       most disagrees with the market. `btts_yes` got a=3.885/b=-2.563 from
       n=261 that way, and applying it made calibration THREE TIMES WORSE:
       ECE 0.0472 raw -> 0.1437. The new fitter sources `predictions`, which
       is every fixture the model priced with no filter (9,066 settled BTTS
       rows), the same source the 1x2 branch already uses successfully.

    2. WRONG SPACE. `apply_platt` computes sigmoid(a * prob + b) — linear in
       the probability. The first version of the fitter fitted on the LOGIT,
       so its coefficients meant something production does not compute. It
       showed as btts_no improving out-of-sample while getting worse through
       the real path. Coefficients must be fitted in the space they are used
       in, or the validation measures a function nobody runs.

    Result through the production apply_platt path: btts 0.047 -> 0.009,
    OU 3.5 0.075 -> 0.011, 1x2 unchanged at 0.002-0.004. OU 1.5 is left
    UNCALIBRATED on purpose — its refit loses to raw out-of-sample, and
    shipping a curve because it was fitted is defect 1 all over again.
    """
    import re as _re
    from pathlib import Path as _Path
    src = (_Path(__file__).resolve().parent.parent / "scripts"
           / "fit_calibration_from_predictions.py").read_text()

    assert "FROM predictions" in src and "source = 'ensemble'" in src, (
        "the fitter must source `predictions`, not settled bets — a settled "
        "bet is a filtered sample and fitting on it produced a curve that "
        "tripled BTTS calibration error"
    )
    # Check SQL usage, not the word: the docstring explains at length why
    # simulated_bets is the wrong source, and an earlier draft of this
    # assertion tripped on that explanation — the third time today a guard
    # fired on its own rationale (see the per-cent-sign and LIMIT incidents).
    assert not _re.search(r"FROM\s+simulated_bets", src), (
        "fitting from simulated_bets reintroduces the selection bias that "
        "produced the harmful BTTS curve"
    )
    # Must fit in probability space, matching apply_platt's 1-feature branch.
    i = src.index("def _fit_platt(")
    m = _re.compile(r"\ndef ").search(src, i + 10)
    body = src[i:m.start() if m else len(src)]
    assert "math.log(z / (1 - z))" not in body, (
        "the fitter must NOT work on the logit — apply_platt computes "
        "sigmoid(a * prob + b) on the raw probability, so a logit fit ships "
        "coefficients for a function production never evaluates"
    )
    assert _re.search(r"exp\(-\(a \* p \+ b\)\)", body), (
        "expected the sigmoid(a * prob + b) form that apply_platt applies"
    )
    # And it must refuse to ship a fit that loses to raw.
    assert "MIN_ECE_GAIN" in src and "e_new < e_raw - MIN_ECE_GAIN" in src, (
        "a fit must beat the RAW probability out-of-sample before it is "
        "written; OU 1.5 fails that test and must stay uncalibrated"
    )
    assert "TRAIN_FRAC" in src and "v[:cut], v[cut:]" in src, (
        "evaluation must use a held-out split, time-ordered and never shuffled"
    )
    return "fitter sources predictions, fits in probability space, ships only what beats raw"


@test("BTTS-RETIRED — BTTS is off at every layer and cannot be placed")
def _btts_retired():
    """BTTS-RETIRED-2026-09-03. Shadow BTTS n=427, ROI -12.76% at live prices,
    t=-2.87 (p<0.01). Recalibration did not rescue it: ENSEMBLE-RECALIBRATION
    took BTTS ECE from 0.047 to 0.009 -- the best-calibrated market we have --
    and re-scoring every settled pick under the new coefficients cut volume to
    33% while making survivors WORSE (-20.73%). And it can never be
    CLV-validated: 0 of 3,076,350 BTTS snapshots carry Pinnacle.

    Pinned at every layer because a market turned off in one place has a habit
    of coming back on in another.
    """
    import re as _re
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent

    # 1. The placer must treat it as retired, not merely as a high floor.
    from workers.automation.coolbet_placer import _min_edge_for, _MIN_EDGE_BY_MARKET
    assert _MIN_EDGE_BY_MARKET.get("btts") is None, (
        "btts must be None (retired) in _MIN_EDGE_BY_MARKET, not a numeric "
        "floor — a floor is a threshold someone can lower back"
    )
    assert _min_edge_for("btts") == float("inf"), (
        "_min_edge_for('btts') must be infinite so no BTTS edge can clear it"
    )

    # 2. The sweep pass must not generate BTTS candidates.
    pipe = (root / "workers" / "jobs" / "daily_pipeline_v2.py").read_text()
    i = pipe.index("_SWEEP_CONFIGS") if "_SWEEP_CONFIGS" in pipe else 0
    assert '"name": "bot_sweep_btts_yes_v1"' not in pipe, (
        "bot_sweep_btts_yes_v1 is back in the sweep configs — that bot is "
        "-14.5% inside a market measured at t=-2.87"
    )

    # 3. The BOT_CONFIGS BTTS bots must be gated off.
    for bot in ("bot_btts_all", "bot_btts_v2"):
        j = pipe.index(f'    "{bot}": {{')
        k = pipe.index("\n    },\n", j)
        assert '"is_active": False' in pipe[j:k], (
            f"{bot} must be is_active=False in BOT_CONFIGS (BTTS-RETIRED)"
        )

    mig = root / "supabase" / "migrations" / "296_retire_btts_bots.sql"
    assert mig.exists(), "migration 296 (retire BTTS bots) is missing"
    msql = mig.read_text()
    assert "ILIKE '%btts%'" in msql, (
        "the migration must sweep any bot named *btts*, not just the three "
        "known names"
    )
    assert not _re.search(r"\bDELETE\s+FROM\b", "\n".join(
        l for l in msql.splitlines() if not l.strip().startswith("--")), _re.I), (
        "historical BTTS bets must NOT be deleted — they are the evidence for "
        "this decision"
    )
    return "BTTS retired in placer, sweep pass, BOT_CONFIGS and DB; history kept"


@test("PINNACLE-BEST-NO-EDGE — warned, scoped to tier 1, deliberately not a veto")
def _pin_best():
    """PINNACLE-BEST-NO-EDGE-2026-09-03. When `recommended_bookmaker` is
    Pinnacle the SHARPEST book held the best price, so no soft book was
    offering value — the edge is measured against a fair price and there is
    nothing to take. On settled 1X2 picks at odds live at pick time:

        tier 1  Pinnacle best n=112  ROI −23.5%  t=−1.72
                soft best     n=338  ROI +26.6%
        tier 2  Pinnacle best n= 47  ROI +11.1%   <- OPPOSITE SIGN

    Two things pinned, and the second is the point. The warning must exist,
    and it must stay SCOPED TO TIER 1 and display-only: a blanket
    "Pinnacle best => skip" would remove profitable tier-2 picks, which is
    exactly what BOT-GATE-OU-BTTS was filed to prevent, and t=−1.72 on n=112
    does not justify a veto.
    """
    import re as _re
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    web = root.parent / "odds-intel-web"
    if not web.exists():
        raise SkipTest("odds-intel-web not present (CI single-repo checkout)")

    page = (web / "src/app/(app)/admin/shadow-bots/page.tsx").read_text()
    i = page.index("PINNACLE-BEST-NO-EDGE")
    blk = page[i:i + 2200]
    assert 'u.recommended_bookmaker === "Pinnacle"' in blk, (
        "the warning must key on Pinnacle holding the best price"
    )
    assert "tier === 1" in blk, (
        "the warning must be SCOPED TO TIER 1 — tier 2 runs the other way "
        "(+11.1%) and flagging it would repeat the BOT-GATE-OU-BTTS mistake"
    )
    assert 'u.market === "1x2"' in blk, (
        "scoped to 1X2: the whole effect is in that market"
    )
    # It must remain a warning. A veto would suppress the bets that are still
    # generating the evidence this rule needs.
    assert 'level: "red"' in blk and "cFlag" in blk, (
        "must be a display flag, not a suppression — the cohort is t=-1.72 and "
        "still accruing"
    )

    tracker = root / "scripts" / "track_pinnacle_best.py"
    assert tracker.exists(), "the tracking script must exist to re-measure the rule"
    tsrc = tracker.read_text()
    assert "odds_at_pick_live" in tsrc, (
        "the tracker must price at odds that were live — odds_at_pick is a "
        "high-water mark (STALE-BEST-ODDS) and would flatter every cohort"
    )
    return "tier-1 1X2 Pinnacle-best warned, display-only, tracker present"


@test("ISOTONIC-BUNDLE-MISMATCH — the isotonic fallback must not drop the odds")
def _isotonic_odds():
    """ISOTONIC-BUNDLE-MISMATCH-2026-09-03. `STAGE2_CALIBRATOR=isotonic` is set
    on the VPS, but the active bundle (v20260712) ships no isotonic_*.pkl — the
    only ones on disk belong to v20260621 and older. So every stage-2 call fell
    back to Platt, silently.

    Worse, the fallback called `apply_platt(prob, market)` with no `odds`,
    which disables Platt's 2-feature O/U logistic (a*prob + c*log(odds) + b) by
    construction. The env var advertised isotonic and the code delivered
    Platt-minus-odds — a configuration that looked deliberate from every angle
    except the filesystem.

    Behavioural test: with a 2-feature O/U calibration loaded and no isotonic
    model present, passing different odds must produce different results. If
    `odds` is dropped again they collapse to the same number.
    """
    import workers.model.improvements as imp
    saved_p, saved_i = imp._platt_params, imp._isotonic_models
    try:
        imp._platt_params = {"over_under_25_over": (0.9, -0.3, 0.4)}  # c set => 2-feature
        imp._isotonic_models = {}                                     # force the fallback
        with_odds = imp.apply_isotonic(0.50, "over_under_25_over", odds=1.85)
        no_odds = imp.apply_isotonic(0.50, "over_under_25_over", odds=None)
        assert abs(with_odds - no_odds) > 1e-9, (
            "apply_isotonic's Platt fallback dropped the odds — the 2-feature "
            "O/U logistic is then dead and every O/U calibration silently "
            "degrades to 1-feature"
        )
        # And different prices must move the result in the 2-feature path.
        hi = imp.apply_isotonic(0.50, "over_under_25_over", odds=3.20)
        assert abs(hi - with_odds) > 1e-9, "odds must actually reach the logistic"
    finally:
        imp._platt_params, imp._isotonic_models = saved_p, saved_i

    src = (__import__("pathlib").Path(__file__).resolve().parent.parent
           / "workers" / "model" / "improvements.py").read_text()
    assert "_isotonic_mode_warned" in src, (
        "asking for isotonic with no bundles present must warn once, not "
        "degrade in silence — that silence is why this ran for weeks"
    )
    return "isotonic fallback forwards odds; missing-bundle mode warns"


@test("SCHEDULER-PORT-8080-HARDEN — a stuck health port must not take the scheduler down")
def _port_harden():
    """SCHEDULER-PORT-8080-HARDEN (filed 2026-07-13, fixed 2026-09-03).

    An orphaned `python workers/scheduler.py` from the Jul 09 cutover held port
    8080 for four days, then hung on Jul 12 without restarting — 33 hours with
    no pipeline_runs before the ops dashboard surfaced it. A duplicate systemd
    unit under the pre-rename name was crash-looping on the same port every 15
    seconds.

    The principle: the health endpoint is the least important thing in this
    process. Losing it costs observability; crashing the scheduler at startup
    because a stray process holds a port costs everything the scheduler does.
    """
    import re as _re
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    src = (root / "workers" / "scheduler.py").read_text()
    i = src.index("def _start_health_server(")
    m = _re.compile(r"\ndef ").search(src, i + 10)
    body = src[i:m.start() if m else len(src)]

    assert "allow_reuse_address = True" in body, (
        "SO_REUSEADDR must be set — without it a socket left in TIME_WAIT by "
        "the previous process blocks the new one"
    )
    assert "except OSError" in body, (
        "a bind failure must be caught: the scheduler exists to run jobs, and "
        "it must not die at startup because /health cannot bind"
    )
    assert "return None" in body, (
        "the bind-failure path must return rather than raise"
    )

    unit = root / "local" / "systemd" / "oddsintel-scheduler.service"
    if unit.exists():
        u = unit.read_text()
        assert "ExecStartPre" in u and "8080/tcp" in u, (
            "the unit must nudge a stray listener off :8080 before starting"
        )
        assert u.count("ExecStartPre=-") or "|| true" in u, (
            "the ExecStartPre must not fail the unit on a clean box where "
            "nothing holds the port — that turns hardening into a new way of "
            "failing to start"
        )
    return "health bind is non-fatal, SO_REUSEADDR set, unit clears the port first"


@test("TEAMS-LEAGUE-ID-BROKEN — nothing may join teams.league_id to get a league or tier")
def _teams_league_id():
    """TEAMS-LEAGUE-ID-BROKEN-2026-09-03. `teams.league_id` never equals the
    fixture's `matches.league_id` — zero of 27,605 over 90 days. Not
    corruption: `ensure_team()` assigns a per-COUNTRY placeholder via
    `ensure_league(f"{country} / Unknown", tier=0)`, so all 11,633 teams point
    at one of 160 rows named 'Unknown' and none at a named league.

    Joining on it returns tier 0 and league name "Unknown" for everything —
    which reads as "no effect" rather than as an error, so it fails silently.
    It already cost real work: the cross-tier hypothesis in
    SWEEP-HOME-BOTS-CALIBRATION could not be tested as its ticket described.

    Guards the DB comment (so the next person meets the warning where they meet
    the column) and that no analysis script joins teams to leagues on it.
    """
    import re as _re
    from pathlib import Path as _Path
    from workers.api_clients.db import execute_query
    root = _Path(__file__).resolve().parent.parent

    rows = execute_query(
        """SELECT col_description('teams'::regclass, ordinal_position) AS c
             FROM information_schema.columns
            WHERE table_name = 'teams' AND column_name = 'league_id'""")
    comment = (rows[0]["c"] or "") if rows else ""
    assert "NOT the team" in comment, (
        "teams.league_id must carry a column comment warning that it is a "
        "placeholder — the column name alone invites the wrong join and the "
        "failure is silent (tier 0 everywhere)"
    )

    # No analysis script may join teams -> leagues on this column.
    bad = []
    for py in list((root / "scripts").glob("*.py")) + list((root / "workers").rglob("*.py")):
        src = py.read_text()
        if _re.search(r"leagues\s+\w*\s*ON\s+\w+\.id\s*=\s*t\.league_id", src, _re.I) \
           or _re.search(r"JOIN\s+leagues[^\n]*t\.league_id", src, _re.I):
            bad.append(str(py.relative_to(root)))
    assert not bad, (
        f"these join leagues on teams.league_id and will read placeholder "
        f"rows (tier 0, name 'Unknown'): {bad}. Use matches.league_id instead."
    )
    return "teams.league_id documented as a placeholder; no code joins leagues on it"


@test("OU-PLATT-UNFITTABLE — O/U calibration exists and is reachable at the production key")
def _ou_platt():
    """OU-PLATT-UNFITTABLE-2026-09-03. `model_calibration` had never held a
    single over_under row. `fit_platt.py` sources O/U from settled
    `simulated_bets` and requires MIN_SAMPLES_OU=300; the live version has 21,
    and the all-time max for any version is 175 — unreachable by design.

    Two further traps were hit while fixing it, both of which produce a
    calibration that loads cleanly and does nothing:

      * VERSION RESOLUTION. Picking each market's model version by "most
        recent row" is a race — several versions write concurrently — and it
        split a market PAIR, resolving over25 to a version with 413 settled
        rows while under25 got 5,351. Resolve by settled VOLUME instead.
      * KEY VOCABULARY. `predictions` says "over25"; the pipeline asks
        apply_platt for f"{os_market}_{os_selection}" = "over_under_25_over".
        A fit written under the predictions name matches nothing at call time
        and apply_platt silently returns its input.

    So this test checks REACHABILITY at the production key, not merely that a
    row exists.
    """
    from pathlib import Path as _Path
    import workers.model.improvements as imp

    src = (_Path(__file__).resolve().parent.parent / "scripts"
           / "fit_calibration_from_predictions.py").read_text()
    # Check the mapping is APPLIED, not merely defined — an earlier draft of
    # this assertion looked for the dict name and passed with the lookup
    # deleted, which is the exact bug it was written to catch.
    assert "PRODUCTION_KEY.get(mkt, mkt)" in src, (
        "the fitter must APPLY PRODUCTION_KEY when writing, translating "
        "predictions-market names to the keys apply_platt is called with. "
        "Defining the dict without using it writes an unreachable fit."
    )
    assert "ORDER BY p.market, COUNT(*) DESC" in src, (
        "model version must be resolved by settled VOLUME per market — "
        "'most recent row' is a race and splits market pairs across versions"
    )

    saved = imp._platt_params
    try:
        imp._platt_params = None                       # force a real load
        params = imp.load_platt_params()
        for key in ("over_under_25_over", "over_under_25_under"):
            assert key in params, (
                f"{key} missing from model_calibration — O/U 2.5 is the "
                "highest-volume goals market and apply_platt is a silent "
                "no-op without it"
            )
            out = imp.apply_platt(0.60, key)
            assert abs(out - 0.60) > 1e-9, (
                f"apply_platt is a NO-OP for {key} — the row exists but is not "
                "reachable at the key production actually uses"
            )
    finally:
        imp._platt_params = saved
    return "O/U 2.5 and 3.5 calibrated and reachable at the production keys"


@test("SILENT-FAILURE-AUDIT-JOBS — no _run_job entrypoint reports success after failing")
def _silent_jobs():
    """SILENT-FAILURE-AUDIT-JOBS-2026-09-03. The same defect bit three times in
    two days: EPICBET-403 (277 runs reporting `completed` with zero rows), the
    FRONTEND_REPO_TOKEN skip (two months of stale competitor figures behind an
    `exit 0`), and `_shadow_run` (16 hours of dead shadow cohorts reporting
    `completed` while betting_pipeline, which re-raises, was fixed within the
    hour of being noticed).

    Scoped deliberately. There are ~430 `except Exception` blocks under
    `workers/` and most are legitimate defensive code in inner loops — this is
    NOT a rule against catching exceptions. It is a rule about one place: a
    function passed to `_run_job` must not return normally after failing,
    because `_run_job` writes `status='completed'` to pipeline_runs and pings
    Kuma "up". A capped, empty or half-failed run then looks exactly like a
    clean one.

    Two shapes are both acceptable:
      * single-purpose jobs re-raise;
      * multi-step pipelines keep per-step isolation (one bad step must not
        skip the rest) and raise at the END if any step failed.
    """
    import re as _re
    from pathlib import Path as _Path
    src = (_Path(__file__).resolve().parent.parent
           / "workers" / "scheduler.py").read_text()

    targets = set(_re.findall(r'_run_job\(\s*"[^"]+"\s*,\s*([A-Za-z_][\w.]*)', src))
    assert len(targets) >= 20, f"expected many _run_job entrypoints, found {len(targets)}"

    offenders = []
    for name in sorted(targets):
        i = src.find(f"def {name}(")
        if i < 0:
            continue                      # defined in another module
        m = _re.compile(r"\ndef ").search(src, i + 10)
        body = src[i:m.start() if m else len(src)]
        # Check EACH except block, not just whether the word "raise" appears
        # somewhere in the function. An earlier draft did the latter and passed
        # with the raise deleted, because an unrelated branch still had one —
        # exactly the kind of weak assertion that let these bugs live.
        for m2 in _re.finditer(r"^(\s*)except Exception", body, _re.M):
            indent = len(m2.group(1))
            tail = body[m2.end():]
            handled = False
            for line in tail.splitlines()[1:]:
                if not line.strip():
                    continue
                cur = len(line) - len(line.lstrip())
                if cur <= indent:            # left the except block
                    break
                st = line.strip()
                if st.startswith("raise") or st.startswith("failed_steps.append"):
                    handled = True
                    break
                # Or the handler declares itself optional IN WORDS. The rule
                # is not "never catch" — plenty of side effects (a digest
                # email, a best-effort refit) genuinely should not fail the
                # job. The rule is that a swallowed failure must be a stated
                # decision rather than an accident, and the codebase already
                # uses these words where that is the intent.
                if any(w in line.lower() for w in
                       ("non-blocking", "non-critical", "skipped", "best-effort",
                        "optional")):
                    handled = True
                    break
            if not handled:
                offenders.append(name)
                break
    # Multi-step pipelines: per-step isolation is fine, but the function must
    # raise at the END when any step failed. Checked separately because those
    # per-step handlers are legitimately annotated as non-critical, so the
    # block-level check above passes even with the final raise deleted.
    for name in sorted(targets):
        i = src.find(f"def {name}(")
        if i < 0:
            continue
        m = _re.compile(r"\ndef ").search(src, i + 10)
        body = src[i:m.start() if m else len(src)]
        if "failed_steps.append" not in body:
            continue
        assert _re.search(r"if failed_steps:\s*\n\s*raise\b", body), (
            f"{name} collects failed_steps but never raises on them — a run "
            f"where half the steps failed is then recorded as "
            f"status='completed'. Keep the per-step isolation and raise at the "
            f"end when failed_steps is non-empty."
        )

    assert not offenders, (
        f"these _run_job entrypoints swallow their exception and return "
        f"normally, so pipeline_runs records status='completed' for a failed "
        f"run: {offenders}. Either re-raise, or (for multi-step pipelines) "
        f"keep per-step isolation and raise at the end when failed_steps is "
        f"non-empty."
    )
    return f"all {len(targets)} _run_job entrypoints surface their failures"


@test("OU-LIVE-PRICE-BLIND — the live-price backfill normalises market vocabulary")
def _ou_live_price_blind():
    """OU-LIVE-PRICE-BLIND-2026-09-03. `backfill_odds_at_pick_live.py` joins
    bets to `odds_snapshots` to recover the price that was actually on offer.
    It joined the two `market`/`selection` pairs raw:

        AND o.market    = b.market
        AND o.selection = b.selection

    The two tables do not share a vocabulary. Bets record
    `market='o/u', selection='under 2.5'`; snapshots record
    `market='over_under_25', selection='under'`. So for O/U the join matched
    nothing, filled nothing, and reported success — 1,713 of 1,860 settled 1x2
    bets priced against 0 of 1,111 settled O/U bets.

    Nothing errored. The consequence was that every figure filtered on
    `odds_at_pick_live IS NOT NULL` was silently ~96% 1x2, and O/U ROI could
    only be computed on `odds_at_pick`, the high-water mark that overstates
    1x2 ROI by +5.80pp. Model work on O/U would have been graded against a
    metric with a large known upward bias.

    ANALYSIS_GOTCHAS #3 is exactly this failure and the join predates it.
    """
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    src = (root / "scripts" / "backfill_odds_at_pick_live.py").read_text()

    # Assert against the SQL, not the module: the docstring above describes the
    # bug in detail, so a whole-file substring search matches the prose and
    # passes with the join reverted.
    i = src.index("_SQL = ")
    sql = src[i:src.index('"""', src.index('"""', i) + 3)]

    assert "LOWER(o.market)" in sql and "LOWER(o.selection)" in sql, (
        "the snapshot side of the join must be case-normalised — shadow_bets "
        "spells the same markets '1X2' and 'O/U', which match nothing raw"
    )
    assert "'over_under_' ||" in sql, (
        "the bet side must remap 'o/u' + 'under 2.5' onto the snapshot's "
        "'over_under_25' spelling, or O/U silently prices zero rows"
    )
    assert "REGEXP_REPLACE(t.selection" in sql, (
        "the line must be stripped off the selection ('under 2.5' -> 'under'); "
        "snapshots carry the line in the market name, not the selection"
    )
    # The precise bug: an unnormalised equality on either column.
    for bad in ("o.market    = b.market", "o.market = b.market",
                "o.selection = b.selection"):
        assert bad not in sql, (
            f"raw `{bad}` is back — this is the join that priced 0 of 1,111 "
            "settled O/U bets while reporting success"
        )

    # Source inspection cannot see a backfill that runs but fills nothing, so
    # check the outcome too where the DB is reachable.
    try:
        from workers.api_clients.db import execute_query
        rows = execute_query(
            """SELECT COUNT(*) FILTER (WHERE odds_at_pick_live IS NOT NULL) AS priced,
                      COUNT(*) AS settled
                 FROM simulated_bets
                WHERE result IN ('won','lost')
                  AND (LOWER(market) IN ('o/u','ou')
                       OR LOWER(market) LIKE 'over_under%%')"""
        )
    except Exception as e:                      # noqa: BLE001
        raise SkipTest(f"DB not reachable: {e}")

    if not rows or not rows[0]["settled"]:
        raise SkipTest("no settled O/U bets to check")
    priced, settled = rows[0]["priced"], rows[0]["settled"]
    assert priced > 0, (
        f"0 of {settled} settled O/U bets have a live price — the backfill is "
        "matching nothing again, which is how this went unnoticed the first time"
    )


@test("SHADOW-RETIRED-INVISIBLE — the canonical shadow view exposes bot retirement")
def _shadow_retired_invisible():
    """SHADOW-RETIRED-BOTS-INVISIBLE-2026-09-03. 89.3% of `shadow_bets`
    (128,243 of 143,602 rows) comes from RETIRED bots, and 20 of them are still
    writing — `bot_dc_specialist` produced 17,032 rows in the last 14 days and
    was retired on 2026-06-01.

    That is deliberate: SHADOW-RETIRED-OK (2026-05-20) keeps retired bots
    producing shadow rows so the retirement-note recovery criterion — ">=30
    bets at >=3% ROI in shadow_bets" — stays measurable. Stopping the writes
    would delete the only evidence that could un-retire a strategy, so this
    test must NOT assert that retired bots stop writing.

    The defect is that retirement was invisible at the point of use.
    `shadow_bets_unique` is the documented read path (ANALYSIS_GOTCHAS #5) and
    a row in it carried no hint its bot had been dead since May — you had to
    know to join `bots`. So the documented view's default behaviour was to
    blend ~89% dead weight into any aggregate. On 2026-09-03 that turned a
    retired market's -4.60% into a filed claim that the model itself was a
    significant loser (MODEL-VS-MARKET-STRATEGY, withdrawn same day).

    Migration 298 adds bot_retired_at / bot_is_active / bot_name to the view.
    """
    try:
        from workers.api_clients.db import execute_query
        cols = {r["column_name"] for r in execute_query(
            """SELECT column_name FROM information_schema.columns
                WHERE table_name = 'shadow_bets_unique'""")}
    except Exception as e:                       # noqa: BLE001
        raise SkipTest(f"DB not reachable: {e}")

    if not cols:
        raise SkipTest("shadow_bets_unique not present")

    for c in ("bot_retired_at", "bot_is_active"):
        assert c in cols, (
            f"shadow_bets_unique is missing `{c}` — without it the canonical "
            "shadow view silently blends ~89% retired-bot rows into every "
            "aggregate, which is how a retired market became a claim about "
            "the model (migration 298)"
        )

    # The view must still expose retired rows, not filter them out: the writes
    # exist so alpha-recovery stays measurable, and a filtering view would
    # quietly delete that capability while looking like a fix.
    row = execute_query(
        """SELECT COUNT(*) AS tot,
                  COUNT(*) FILTER (WHERE bot_retired_at IS NOT NULL) AS retired
             FROM shadow_bets_unique"""
    )[0]
    if not row["tot"]:
        raise SkipTest("no shadow rows")
    assert row["retired"] > 0, (
        "shadow_bets_unique no longer exposes any retired-bot rows — the view "
        "must surface retirement, not filter it, or the alpha-recovery "
        "criterion (SHADOW-RETIRED-OK) becomes unmeasurable"
    )
    return (f"view exposes retirement; {row['retired']} of {row['tot']} rows "
            f"are retired-bot output")


@test("TEAM-SCORING-RATES — rolling goal rates use only strictly-prior matches")
def _team_scoring_rates():
    """TEAM-SCORING-RATES-OWN-RESULTS-2026-09-03. `goals_for_avg_*` came from
    `match_signals` and sat at 46.2% coverage. The queued fix
    (UNDERSTAT-SCRAPER-BIG5-XG) covers 1.62% of the leagues we actually bet —
    we bet Argentina Primera C and Iceland 1. Deild, not the Big 5. Computing
    the rate from our own 163,901 settled matches reaches 84.1%.

    LEAKAGE IS THE ENTIRE RISK. A rate that includes the fixture it describes,
    or any fixture kicking off after it, backtests beautifully and loses money
    live — and it is invisible in every aggregate metric, because the metric is
    computed on the same leaked data. So this test does not check coverage; it
    recomputes the feature independently from strictly-prior matches and
    demands exact agreement.
    """
    from workers.model.team_scoring_rates import (
        MIN_MATCHES, WINDOW_DAYS, build_sql,
    )

    sql = build_sql()
    assert "p.date < t.kickoff" in sql, (
        "the prior-match window must be STRICTLY before kickoff — `<=` admits "
        "the fixture itself and every other match at the same timestamp"
    )
    assert "p.id <> t.mid" in sql, (
        "the self-exclusion guard is gone; if the timestamp comparison is ever "
        "loosened this is the only thing stopping a fixture describing itself"
    )
    assert "COALESCE(f.goals_for_avg_home" in sql, (
        "existing signal-sourced values must win, or the column's provenance "
        "depends on job ordering"
    )
    assert MIN_MATCHES >= 3 and WINDOW_DAYS >= 90

    try:
        from workers.api_clients.db import get_conn
        from workers.model.team_scoring_rates import fill_window
        conn_cm = get_conn()
    except Exception as e:                       # noqa: BLE001
        raise SkipTest(f"DB not reachable: {e}")

    # Compare ONLY rows this logic produced. Pre-existing signal-sourced values
    # follow different semantics and would otherwise force a `continue` that
    # silently swallows real mismatches — the exact weak-assertion shape that
    # let a broken test pass earlier the same day.
    #
    # So: inside a transaction, blank a recent window, refill it with the
    # module, compare every filled row against an independent recomputation,
    # then roll back. Nothing is written.
    checked = 0
    mismatches: list[str] = []
    with conn_cm as conn, conn.cursor() as cur:
        cur.execute("""SELECT to_char(CURRENT_DATE - 21, 'YYYY-MM-DD'),
                              to_char(CURRENT_DATE + 1,  'YYYY-MM-DD')""")
        since, until = cur.fetchone()
        try:
            cur.execute("""
                UPDATE match_feature_vectors
                   SET goals_for_avg_home = NULL, goals_against_avg_home = NULL,
                       goals_for_avg_away = NULL, goals_against_avg_away = NULL
                 WHERE match_date >= %s AND match_date < %s""", (since, until))
            fill_window(cur, since, until)
            cur.execute("""
                SELECT f.match_id, m.date, m.home_team_id, m.away_team_id,
                       f.goals_for_avg_home, f.goals_against_avg_home,
                       f.goals_for_avg_away, f.goals_against_avg_away
                  FROM match_feature_vectors f
                  JOIN matches m ON m.id = f.match_id
                 WHERE f.match_date >= %s AND f.match_date < %s
                   AND f.goals_for_avg_home IS NOT NULL
                 ORDER BY f.match_id LIMIT 25""", (since, until))
            rows = cur.fetchall()
            if not rows:
                raise SkipTest("no fixtures in the last 21 days to verify")

            for mid, ko, home, away, gf_h, ga_h, gf_a, ga_a in rows:
                for tid, gf_db, ga_db in ((home, gf_h, ga_h), (away, gf_a, ga_a)):
                    if tid is None or gf_db is None:
                        continue
                    # Independent recomputation — deliberately not reusing the
                    # module's SQL, since a test built on the implementation
                    # cannot detect the implementation being wrong.
                    cur.execute("""
                        SELECT AVG(gf)::numeric, AVG(ga)::numeric, COUNT(*) FROM (
                          SELECT score_home AS gf, score_away AS ga FROM matches
                           WHERE home_team_id = %s AND score_home IS NOT NULL
                             AND date < %s
                             AND date >= %s::timestamptz - (%s || ' days')::interval
                             AND id <> %s
                          UNION ALL
                          SELECT score_away, score_home FROM matches
                           WHERE away_team_id = %s AND score_home IS NOT NULL
                             AND date < %s
                             AND date >= %s::timestamptz - (%s || ' days')::interval
                             AND id <> %s) z""",
                        (tid, ko, ko, str(WINDOW_DAYS), mid,
                         tid, ko, ko, str(WINDOW_DAYS), mid))
                    gf_py, ga_py, n = cur.fetchone()
                    checked += 1
                    if gf_py is None or n < MIN_MATCHES:
                        mismatches.append(
                            f"{mid}/{tid}: written from {n} prior matches, below "
                            f"the MIN_MATCHES={MIN_MATCHES} floor")
                        continue
                    if (abs(float(gf_db) - float(gf_py)) > 1e-6
                            or abs(float(ga_db) - float(ga_py)) > 1e-6):
                        mismatches.append(
                            f"{mid}/{tid}: stored ({gf_db},{ga_db}) != "
                            f"strictly-prior ({gf_py},{ga_py}) over n={n}")
        finally:
            conn.rollback()

    assert checked > 0, "no rows were produced by the fill — is it running at all?"
    assert not mismatches, (
        "the rolling rate does not match a recomputation over strictly-prior "
        "matches, which is what leakage looks like: "
        + "; ".join(mismatches[:3])
    )
    return f"{checked} team-slots reproduced exactly from strictly-prior matches"


@test("ODDS-NO-MAX-AGE — a dead feed's last quote is not priced as a live offer")
def _odds_no_max_age():
    """ODDS-NO-MAX-AGE-2026-09-03. STALE-BEST-ODDS fixed `MAX(odds)` over all
    history to `DISTINCT ON ... timestamp DESC` — the latest quote per book.
    But "latest" is not "live". When a feed dies its final quote stays the
    latest forever and keeps being priced as an available offer.

    Coolbet's bulk scraper died at 08:00 UTC on 2026-09-03; by 18:40 the
    pipeline had raised 101 picks recommending Coolbet on quotes up to 11h old.
    The UI placer survived it (it re-reads the price at placement and compares
    `odds_drift_pct` — both bets placed that day show 0.000%), but the operator
    bets shadow signals by hand and has no such check.

    An ABSOLUTE age cap cannot express this, which is the whole subtlety: the
    odds job runs 07-22 UTC while the morning cohort picks at 06:00, so morning
    picks legitimately use quotes at p95 = 10.0h and p99 = 16.4h old. Any cap
    tight enough to catch Coolbet at 11.5h would delete the morning cohort.

    Staleness is RELATIVE — overnight all books age together, so their lag stays
    near zero, while a dead feed falls behind its peers on the same fixture.
    """
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    src = (root / "workers" / "jobs" / "daily_pipeline_v2.py").read_text()

    # Assert against the query, not the module: the docstrings above and in the
    # pipeline describe the bug in detail, so a whole-file substring search
    # matches the prose and passes with the guard deleted.
    i = src.index("-- ODDS-NO-MAX-AGE-2026-09-03.")
    sql = src[i:src.index('"""', i)]

    assert "lag_h <= " in sql and "age_h <= " in sql, (
        "the staleness filter is gone — a dead feed's final quote is priced as "
        "a live offer again"
    )
    assert "PARTITION BY l.match_id" in sql, (
        "lag must be measured against the freshest quote for the same fixture; "
        "an absolute age cap deletes the morning cohort (p99 = 16.4h)"
    )

    from workers.jobs.daily_pipeline_v2 import (
        ODDS_MAX_AGE_HOURS, ODDS_MAX_LAG_HOURS,
    )
    # Generous enough for the 07-22 UTC odds window plus the 06:00 pick time.
    assert 2.0 <= ODDS_MAX_LAG_HOURS <= 12.0, (
        f"ODDS_MAX_LAG_HOURS={ODDS_MAX_LAG_HOURS} is outside the range the "
        "measurement supports (market p99 lag is ~3h; Coolbet's dead feed sat "
        "at 8.5h behind its peers)")
    assert ODDS_MAX_AGE_HOURS >= 24.0

    # Source inspection cannot see a filter that is present but ineffective, so
    # assert the invariant against live data too.
    try:
        from workers.api_clients.db import execute_query
        ids = [r["id"] for r in execute_query(
            """SELECT m.id FROM matches m
                WHERE m.date > now() AND m.date < now() + interval '48 hours'
                LIMIT 300""")]
    except Exception as e:                       # noqa: BLE001
        raise SkipTest(f"DB not reachable: {e}")
    if not ids:
        raise SkipTest("no scheduled fixtures in the next 48h")

    rows = execute_query(sql, (ids, ODDS_MAX_LAG_HOURS, ODDS_MAX_AGE_HOURS))
    if not rows:
        raise SkipTest("no odds rows for the sampled fixtures")

    # Every surviving row must genuinely satisfy the invariant.
    breaches = execute_query(
        """WITH latest AS (
             SELECT DISTINCT ON (o.match_id, o.bookmaker)
                    o.match_id, o.bookmaker, o.timestamp
               FROM odds_snapshots o
              WHERE o.match_id = ANY(%s::uuid[]) AND o.is_closing = false
              ORDER BY o.match_id, o.bookmaker, o.timestamp DESC)
           SELECT COUNT(*) AS n FROM (
             SELECT EXTRACT(epoch FROM (
                      MAX(timestamp) OVER (PARTITION BY match_id) - timestamp
                    )) / 3600.0 AS lag_h
               FROM latest) z
            WHERE lag_h > %s""",
        (ids, ODDS_MAX_LAG_HOURS))
    stale_available = breaches[0]["n"] if breaches else 0

    return (f"{len(rows)} quotes passed the guard; {stale_available} "
            f"(book, fixture) pairs were excluded as lagging > "
            f"{ODDS_MAX_LAG_HOURS}h behind their peers")


@test("WEEKLY-EVAL-OU-INVERTED — over25 is scored against P(over), not P(under)")
def _weekly_eval_ou_inverted():
    """WEEKLY-EVAL-OU-INVERTED-2026-09-03. `weekly_eval_and_compare.py` zipped
    ["over25", "under25"] against `predict_proba`'s column order. The OU head is
    binary with `classes_ = [0, 1]` where y is the *over 2.5* indicator, so
    predict_proba returns [P(under), P(over)] — column 0 is UNDER. Pairing by
    position scored P(under) as the over-2.5 probability.

    It is invisible in the output. over25 and under25 are complementary, so
    their log-losses are identical either way and the table looks
    self-consistent. The tell is the predicted rate: on the 2026-08-20..09-03
    holdout the actual over rate was 0.5907, while the swapped reading implied
    0.4377 (off by 0.153) against 0.5623 for the correct one (off by 0.028).

    Impact: every weekly OU verdict since this script replaced compare_models.py
    was computed on inverted probabilities. It inflated OU log-loss enough to
    flag a working head as NO SKILL, and v20260830 was rejected for OU
    promotion on 2026-08-31 as "+11.0%% worse than v20260719" when the corrected
    figure on the same holdout is -5.3%% BETTER.
    """
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    src = (root / "scripts" / "weekly_eval_and_compare.py").read_text()

    assert 'enumerate(["over25", "under25"])' not in src, (
        "over25/under25 are being paired with predict_proba by position again — "
        "column 0 is P(under), so this scores the OU head inverted"
    )
    assert '("over25", float(probs_ou[1]))' in src, (
        "over25 must take probs_ou[1]; classes_ = [0, 1] with y = over-2.5 "
        "indicator, so column 1 is P(over)"
    )
    assert '_truth_ou25' in src

    # The property that actually matters, checked numerically rather than by
    # substring: the truth vector's first slot must be the OVER outcome, so
    # that pairing over25 -> truth_2[0] is right.
    import importlib.util as _ilu
    spec = _ilu.spec_from_file_location(
        "_wec_smoke", root / "scripts" / "weekly_eval_and_compare.py")
    wec = _ilu.module_from_spec(spec)
    try:
        spec.loader.exec_module(wec)
    except Exception as e:                       # noqa: BLE001
        raise SkipTest(f"cannot import weekly_eval_and_compare: {e}")

    assert wec._truth_ou25(3, 1) == [1, 0], (
        "a 4-goal game must read as over-2.5 in slot 0")
    assert wec._truth_ou25(1, 1) == [0, 1], (
        "a 2-goal game must read as under-2.5 in slot 1")
    return "over25 scored against P(over); truth vector is [over, under]"


@test("FEATURE-DENSIFY-ROUND-2 — backward-looking fills use strictly-prior data")
def _feature_densify_round2():
    """FEATURE-DENSIFY-ROUND-2-2026-09-03. Three features the O/U head wants sat
    sparse while their inputs were already in our database — the same shape as
    TEAM-SCORING-RATES. Backfill moved rest_days 32.0%% -> 92.4%%,
    season_progress 12.8%% -> 98.7%%, league_draw_rate_ytd 18.2%% -> 75.4%%.

    Two of the three look backward and can leak; the third cannot:

      * rest_days_*          — the team's previous PLAYED match, strictly before
                               kickoff.
      * league_draw_rate_ytd — results in the league-season strictly before
                               kickoff, with a MIN_LEAGUE_MATCHES floor.
      * season_progress      — a fixture's position in its league-season
                               SCHEDULE. Published in advance, never touches a
                               score, so using the season span is not hindsight.

    As with the scoring rates, this does not check coverage: a leaked feature has
    excellent coverage. It recomputes the backward-looking two from strictly-prior
    data and demands exact agreement.
    """
    from workers.model.feature_densify import (
        FILLS, MAX_REST_DAYS, MIN_LEAGUE_MATCHES,
        LEAGUE_DRAW_RATE_SQL, REST_DAYS_SQL, SEASON_PROGRESS_SQL, fill_window,
    )

    assert "p.date < t.kickoff" in REST_DAYS_SQL and "p.id <> t.mid" in REST_DAYS_SQL, (
        "rest_days must look strictly before kickoff and exclude the fixture itself")
    assert "p.date < t.kickoff" in LEAGUE_DRAW_RATE_SQL, (
        "league_draw_rate_ytd must only count results before kickoff — including "
        "the fixture's own result is a direct leak of the thing being predicted")
    assert "COUNT(*) >= %(min_matches)s" in LEAGUE_DRAW_RATE_SQL and MIN_LEAGUE_MATCHES >= 10
    assert "score" not in SEASON_PROGRESS_SQL, (
        "season_progress must be computed from schedule dates only")
    assert MAX_REST_DAYS >= 14

    try:
        from workers.api_clients.db import get_conn
        conn_cm = get_conn()
    except Exception as e:                       # noqa: BLE001
        raise SkipTest(f"DB not reachable: {e}")

    checked = 0
    mismatches: list[str] = []
    with conn_cm as conn, conn.cursor() as cur:
        cur.execute("""SELECT to_char(CURRENT_DATE - 21, 'YYYY-MM-DD'),
                              to_char(CURRENT_DATE + 1,  'YYYY-MM-DD')""")
        since, until = cur.fetchone()
        try:
            # Blank then refill, so only rows this logic produced are compared —
            # signal-sourced values follow different semantics and would force a
            # `continue` that swallows real mismatches.
            cur.execute("""UPDATE match_feature_vectors
                              SET rest_days_home = NULL, rest_days_away = NULL,
                                  league_draw_rate_ytd = NULL
                            WHERE match_date >= %s AND match_date < %s""",
                        (since, until))
            for name, sql in FILLS:
                fill_window(cur, name, sql, since, until)

            cur.execute("""SELECT f.match_id, m.date, m.home_team_id, m.away_team_id,
                                  f.rest_days_home, f.rest_days_away
                             FROM match_feature_vectors f
                             JOIN matches m ON m.id = f.match_id
                            WHERE f.match_date >= %s AND f.match_date < %s
                              AND f.rest_days_home IS NOT NULL
                            ORDER BY f.match_id LIMIT 20""", (since, until))
            for mid, ko, home, away, rh, ra in cur.fetchall():
                for tid, val in ((home, rh), (away, ra)):
                    if tid is None or val is None:
                        continue
                    cur.execute("""SELECT MAX(p.date) FROM matches p
                                    WHERE (p.home_team_id = %s OR p.away_team_id = %s)
                                      AND p.score_home IS NOT NULL
                                      AND p.date < %s
                                      AND p.date >= %s::timestamptz
                                                    - (%s || ' days')::interval
                                      AND p.id <> %s""",
                                (tid, tid, ko, ko, str(MAX_REST_DAYS), mid))
                    last = cur.fetchone()[0]
                    if last is None:
                        mismatches.append(f"{mid}/{tid}: rest written with no prior match")
                        continue
                    checked += 1
                    expected = round((ko - last).total_seconds() / 86400.0)
                    if expected != val:
                        mismatches.append(
                            f"{mid}/{tid}: rest {val} != strictly-prior {expected}")

            cur.execute("""SELECT f.match_id, m.date, m.league_id, m.season,
                                  f.league_draw_rate_ytd
                             FROM match_feature_vectors f
                             JOIN matches m ON m.id = f.match_id
                            WHERE f.match_date >= %s AND f.match_date < %s
                              AND f.league_draw_rate_ytd IS NOT NULL
                            ORDER BY f.match_id LIMIT 20""", (since, until))
            for mid, ko, lg, se, dr in cur.fetchall():
                cur.execute("""SELECT AVG(CASE WHEN score_home = score_away
                                               THEN 1.0 ELSE 0.0 END), COUNT(*)
                                 FROM matches
                                WHERE league_id = %s AND season = %s
                                  AND score_home IS NOT NULL
                                  AND date < %s AND id <> %s""",
                            (lg, se, ko, mid))
                expected, n = cur.fetchone()
                if n < MIN_LEAGUE_MATCHES:
                    mismatches.append(f"{mid}: draw rate written from only {n} matches")
                    continue
                checked += 1
                if abs(float(dr) - float(expected)) > 1e-9:
                    mismatches.append(
                        f"{mid}: draw rate {dr} != strictly-prior {expected}")
        finally:
            conn.rollback()

    assert checked > 0, "the fills produced nothing — are they running at all?"
    assert not mismatches, (
        "a backward-looking fill does not match a recomputation over "
        "strictly-prior data, which is what leakage looks like: "
        + "; ".join(mismatches[:3]))
    return f"{checked} values reproduced exactly from strictly-prior data"


@test("WEEKLY-EVAL-HOLDOUT — versions are never scored on their own training data")
def _weekly_eval_holdout():
    """WEEKLY-EVAL-HOLDOUT-NOT-HELD-OUT-2026-09-03. The weekly comparison scored
    candidate and baseline on "the last 14 days of settled MFV rows" and called
    it held out. It was not held out from the candidate: `train.py` trains
    through the run date unless `--cutoff` is passed, and the cron did not pass
    it. Measured — v20260903 trained through 2026-09-03 and was scored on
    2026-08-20..09-03, the entire window; v20260830 had 10 of the 14 days. Only
    the older baseline was honestly scored, so every verdict compared a model
    that had memorised the test set against one that had not.

    The guard reads `model_versions.training_window_end` and starts each
    comparison the day after. It lives in the script, not the caller: requiring
    the cron to pass `--cutoff` works until someone forgets, and that failure is
    silent.

    Two properties beyond "a guard exists", both learned by getting it wrong:

      * PER-BASELINE windows. A single global window is safe but throws away
        good data — the first version cut 6,941 rows to 949 because the 1X2
        baseline was contaminated, even though the O/U pair was honest across
        the whole span. An underpowered verdict is untrustworthy too.
      * MIN_HOLDOUT_ROWS. A candidate trained through yesterday leaves a
        technically honest window of one day; the first run scored EIGHT
        matches and printed a full table with +32.5%% swings. Refusing a rigged
        verdict and emitting a meaningless one is the same failure.
    """
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    src = (root / "scripts" / "weekly_eval_and_compare.py").read_text()

    assert "training_window_end" in src, (
        "the guard must read each version's real training window; without it "
        "the comparison silently favours whichever model saw the test set")
    assert "_honest_start" in src and "timedelta(days=1)" in src, (
        "the honest window must start the day AFTER the newest training window")
    assert "MIN_HOLDOUT_ROWS" in src, (
        "without a minimum-rows floor the guard trades a rigged verdict for a "
        "verdict on a handful of matches")
    assert "by_baseline" in src and "windows[ver]" in src, (
        "windows must be computed per baseline; a single global window discards "
        "test data that is honest for the other markets")

    import importlib.util as _ilu
    spec = _ilu.spec_from_file_location(
        "_wec_holdout", root / "scripts" / "weekly_eval_and_compare.py")
    wec = _ilu.module_from_spec(spec)
    try:
        spec.loader.exec_module(wec)
    except Exception as e:                       # noqa: BLE001
        raise SkipTest(f"cannot import weekly_eval_and_compare: {e}")
    assert wec.MIN_HOLDOUT_ROWS >= 100, (
        f"MIN_HOLDOUT_ROWS={wec.MIN_HOLDOUT_ROWS} is too low to distinguish a "
        "real difference from noise")

    # Every version that has ever been promoted must carry a training window,
    # or the guard cannot prove anything about it and has to refuse.
    try:
        from workers.api_clients.db import execute_query
        missing = execute_query(
            """SELECT version FROM model_versions
                WHERE promoted_at IS NOT NULL AND training_window_end IS NULL""")
    except Exception as e:                       # noqa: BLE001
        raise SkipTest(f"DB not reachable: {e}")
    assert not missing, (
        "promoted versions with no training_window_end: "
        + ", ".join(r["version"] for r in missing)
        + " — the holdout guard cannot verify these and will refuse to score them")
    return f"holdout guard present; MIN_HOLDOUT_ROWS={wec.MIN_HOLDOUT_ROWS}"


@test("CLV-GATE — CLV is priced at the quote that was actually on offer")
def _clv_gate_priced_live():
    """CLV-GATE-UNVALIDATED-2026-09-04. The promotion gate can promote a bot on
    de-vigged Pinnacle CLV alone. The ticket suspected that route was unsafe
    because CLV did not predict returns — correlation +0.0147, top quintile
    losing money. **That was measured on a 717-pick subset and is wrong.**

    On all 10,542 settled shadow picks carrying a de-vigged Pinnacle close, CLV
    predicts returns strongly even as stored (corr +0.0825, t=+8.50). The real
    defect was the price feeding it: `clv` and `clv_pinnacle` are computed from
    `odds_at_pick`, the snapshot high-water mark STALE-BEST-ODDS showed
    overstates by a mean +0.2522 decimal points. Repricing at
    `odds_at_pick_live` sharpens it to corr +0.0991 (t=+10.23) with quintiles
    running monotonically from -17.10%% to +11.15%%.

    So the CLV route is KEPT, not dropped, and this pins that the gate reads the
    repriced columns. New columns rather than a rewrite (migration 291's
    precedent) because `clv` is published on the performance pages.
    """
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent

    settle = (root / "workers" / "jobs" / "settlement.py").read_text()
    assert "clv_live" in settle and "clv_pinnacle_live" in settle, (
        "settlement must write the repriced CLV columns, or the gate's basis "
        "silently stops updating for new picks")
    assert 'bet.get("odds_at_pick_live")' in settle, (
        "the repriced CLV must come from odds_at_pick_live")
    assert 'clv = round((float(odds) / float(closing_odds)) - 1, 4)' in settle, (
        "the original `clv` must keep its historical definition — it is "
        "published, and silently restating a published figure is the thing we "
        "fault competitors for")

    review = (root / "scripts" / "weekly_bot_review.py").read_text()
    assert "COALESCE(clv_pinnacle_live, clv_live, clv_pinnacle, clv)" in review, (
        "the gate must prefer the repriced CLV, falling back to the originals "
        "for picks that predate the backfill")

    try:
        from workers.api_clients.db import execute_query
        cols = {r["column_name"] for r in execute_query(
            """SELECT column_name FROM information_schema.columns
                WHERE table_name = 'shadow_bets_unique'""")}
    except Exception as e:                       # noqa: BLE001
        raise SkipTest(f"DB not reachable: {e}")
    if not cols:
        raise SkipTest("shadow_bets_unique not present")
    for c in ("clv_live", "clv_pinnacle_live"):
        assert c in cols, (
            f"shadow_bets_unique is missing `{c}` — the gate reads the VIEW, and "
            "a view freezes its column list at creation (migrations 295/298/300)")

    row = execute_query(
        """SELECT COUNT(*) AS n,
                  COUNT(COALESCE(clv_pinnacle_live, clv_live,
                                 clv_pinnacle, clv)) AS basis
             FROM shadow_bets_unique
            WHERE result IN ('won','lost','void')
              AND created_at >= NOW() - INTERVAL '90 days'""")[0]
    if not row["n"]:
        raise SkipTest("no settled shadow picks in the gate window")
    assert row["basis"] > 0, (
        "the gate's CLV expression resolves on no rows — it would fall through "
        "to the ROI route for every bot")
    return (f"gate CLV basis resolves on {row['basis']} of {row['n']} picks")


@test("UNIBET-KAMBI-ODDS — milli-unit odds, type-keyed parsing, separate bookmaker")
def _unibet_kambi():
    """UNIBET-KAMBI-ODDS-2026-09-04. Unibet is a Kambi operator and the offering
    API is public and unauthenticated, so the ingest is plain JSON — no Imperva
    session, no FlareSolverr. Measured on the EE market: 699 football events,
    569 pre-match, 186 leagues.

    Three things this pins, each of which silently corrupts the feed if lost:

    1. **Odds and lines are milli-units.** `odds: 5750` is 5.75. Storing raw
       would put 5750.0 into odds_snapshots and every edge calculation
       downstream would read it as a 5750-to-1 shot.
    2. **Parsing keys on `outcome["type"]`, not labels.** With `lang=et_EE` the
       labels are Estonian ("Üle"/"Alla"). A label-matching parser silently
       stops recognising markets the moment anyone changes the lang param.
    3. **It writes `Unibet-Kambi`, not `Unibet`.** We already receive Unibet via
       API-Football; that feed has never been checked against the real site, and
       BET365-EXECUTION-AUDIT found exactly that failure (AF-fed Bet365 inflated,
       CLV +10%% vs ROI -10%%). Merging the two would destroy the only evidence
       that can settle it.
    """
    from workers.automation.unibet_kambi import (
        _BOOKMAKER, _milli, parse_betoffers, shape_candidates,
    )

    assert _milli(5750) == 5.75, "odds must be divided by 1000"
    assert _milli(4500) == 4.5, "lines must be divided by 1000"
    assert _BOOKMAKER == "Unibet-Kambi", (
        "must not write under 'Unibet' — that is the API-Football feed, and "
        "keeping them separate is what allows the AF-vs-direct comparison")

    rows = parse_betoffers([
        {"outcomes": [{"type": "OT_ONE", "odds": 5750},
                      {"type": "OT_CROSS", "odds": 1170},
                      {"type": "OT_TWO", "odds": 12000}]},
        {"outcomes": [{"type": "OT_OVER", "odds": 3950, "line": 2500},
                      {"type": "OT_UNDER", "odds": 1180, "line": 2500}]},
        # Asian quarter line — must be skipped, not rounded into a line we do
        # not hold. `over_under_225` is not in the shared vocabulary.
        {"outcomes": [{"type": "OT_OVER", "odds": 1900, "line": 2250},
                      {"type": "OT_UNDER", "odds": 1900, "line": 2250}]},
    ])
    by = {(m, sel): o for m, sel, o, _ in rows}
    assert by.get(("1x2", "home")) == 5.75, f"1x2 home mis-parsed: {rows}"
    assert by.get(("over_under_25", "over")) == 3.95, f"O/U mis-parsed: {rows}"
    assert not any(m.startswith("over_under_22") for m, _, _, _ in rows), (
        "quarter lines must be skipped — over_under_225 is not a market this "
        "repo stores, and rounding it to 2.5 would fabricate a price")

    # Pre-match filter: a live event's totals are in-play adjusted. A first pass
    # at this research sampled six already-kicked-off fixtures and wrongly
    # concluded Unibet barely offers O/U 2.5 on lower leagues.
    from datetime import datetime, timedelta, timezone
    now = datetime.now(timezone.utc)
    ev = lambda mins, group="Ligue 2": {"event": {
        "id": 1, "name": "A - B", "group": group,
        "start": (now + timedelta(minutes=mins)).isoformat().replace("+00:00", "Z")}}
    got = shape_candidates([ev(-30), ev(120), ev(120, "Cyber Live Arena (2 x 5 min)")])
    assert len(got) == 1, (
        f"expected only the future non-virtual event, got {len(got)} — "
        "live events and virtual football must both be excluded")
    return "milli-units, type-keyed parsing, pre-match + virtual filters all pinned"


@test("COOLBET-GET-NO-TIMEOUT — no request can hang the odds job forever")
def _coolbet_get_timeout():
    """COOLBET-GET-NO-TIMEOUT-2026-09-04. The Coolbet odds job hung for 15h15m.

    `requests.Session` inherits no default timeout. The POST path in
    `coolbet_session.py` had carried a `setdefault("timeout", 30)` for exactly
    that reason; **the GET path had none**, and four other call sites had
    neither. A GET on a half-open socket blocked forever, and because the
    process stayed alive launchd considered the job still running and never
    restarted it.

    Measured: PID 64881, state S, elapsed 15h15m, log silent 10:15 -> 23:48, no
    bulk sweep since 07:00, Coolbet coverage of upcoming fixtures down to 2.1%
    against Unibet-Kambi's 33.2%. Throughout, the feed watchdog ran every 20
    minutes, correctly reported STALE, and re-harvested cookies at a problem
    that was never about cookies.

    Two guards, because the first only fixes the hang we found:
      1. `_TimeoutSession` defaults every request, so a new call site cannot
         reintroduce this by omission.
      2. `kill_stalled_job` ends a process that is running while its log is
         silent, so launchd can start a clean one. Detecting a stall without
         being able to end it is spectating, not monitoring.
    """
    from pathlib import Path as _Path
    root = _Path(__file__).resolve().parent.parent
    sess_src = (root / "workers" / "automation" / "coolbet_session.py").read_text()

    assert "class _TimeoutSession(requests.Session)" in sess_src, (
        "the session must default its own timeout — patching individual call "
        "sites is what let the GET path go unguarded while POST was fixed")
    assert "kwargs.setdefault(\"timeout\", self.default_timeout)" in sess_src, (
        "_TimeoutSession must inject the default in request()")
    # Check ASSIGNMENTS, not prose: two docstrings legitimately mention
    # `requests.Session()` while describing why it was replaced, and an earlier
    # draft of this assertion matched those and failed on correct code.
    import re as _re
    bare = _re.findall(r"=\s*requests\.Session\(\)", sess_src)
    assert not bare, (
        "a bare requests.Session() is being assigned again — it inherits no "
        "timeout and can hang the job indefinitely")

    from workers.automation.coolbet_session import _TimeoutSession
    assert 5 <= _TimeoutSession.default_timeout <= 120, (
        f"default_timeout={_TimeoutSession.default_timeout} is outside a sane "
        "band; it must be well under the 30-minute job cadence so a wedged "
        "request cannot outlive its own run")

    wd = (root / "workers" / "jobs" / "coolbet_feed_watchdog.py").read_text()
    assert "def kill_stalled_job" in wd and "SIGTERM" in wd, (
        "the watchdog must be able to end a stalled job, not just report it")
    assert "_log_silent_minutes" in wd, (
        "the stall check must require a SILENT log as well as a long runtime — "
        "the full sweep legitimately walks ~2,000 fixtures with pauses, and "
        "killing a slow-but-working run turns it into a guaranteed failure")

    from workers.jobs.coolbet_feed_watchdog import kill_stalled_job
    out = kill_stalled_job(dry_run=True)
    assert out.get("killed") == [], "dry_run must never actually kill"
    return "session defaults a timeout; watchdog can end a stalled run"


@test("AF-BUDGET-STATUS-DEADLOCK — budget.status() must not self-deadlock on its own lock")
def test_af_budget_status_no_deadlock():
    """Behavioural: call status() on a real BudgetTracker and require it to return.

    2026-09-05: status() held self._lock and then called self.usage_pct(), which
    takes the same lock. With a plain threading.Lock that is a permanent
    self-deadlock — and the lock is never released, so every later can_call() /
    remaining() blocks forever. One HTTP hit on the scheduler's /health endpoint
    wedged fetch_odds, odds_refresh, settle_ready and fetch_fixtures for hours
    and drained the 12-worker APScheduler pool, starving the non-AF feeds
    (Unibet-Kambi, Epicbet) that merely needed a worker.

    Mutation-verified 2026-09-05: restoring the original bug (plain Lock AND the
    nested self.usage_pct() call) fails this test on the 5s join timeout. Either
    half of the fix alone is sufficient, so reverting just one still passes —
    both are kept deliberately: the RLock is the blanket guard against any future
    nested accessor, the inline computation removes the re-entrancy that existed.
    """
    import threading as _th
    from workers.api_clients.api_football import BudgetTracker

    tracker = BudgetTracker()
    result = {}

    def _call():
        try:
            result["status"] = tracker.status()
        except Exception as exc:  # pragma: no cover - surfaced via the assert below
            result["error"] = exc

    worker = _th.Thread(target=_call, daemon=True)
    worker.start()
    worker.join(timeout=5.0)

    assert not worker.is_alive(), (
        "budget.status() did not return within 5s — it self-deadlocked on _lock. "
        "status() must not call another _lock-taking accessor while holding _lock."
    )
    assert "error" not in result, f"budget.status() raised: {result.get('error')}"
    assert "usage_pct" in result["status"], "status() returned without usage_pct"

    # The lock must be free afterwards: a deadlocked status() leaves it held,
    # which is what actually starved the scheduler.
    followup = {}

    def _followup():
        followup["remaining"] = tracker.remaining()

    t2 = _th.Thread(target=_followup, daemon=True)
    t2.start()
    t2.join(timeout=5.0)
    assert not t2.is_alive(), (
        "budget.remaining() blocked after status() — the budget lock was left held. "
        "This is the exact failure mode that wedged every AF job."
    )



@test("SHADOW-PAGE-ROI-INFLATED — the bot DETAIL page must price ROI at the executable odds")
def test_shadow_detail_page_uses_exec_odds():
    """The index page was fixed 2026-09-04; the per-bot detail page was not, so
    clicking into a bot showed a different, inflated ROI than the row you clicked.

    `odds_at_pick` is a high-water mark (STALE-BEST-ODDS: MAX() across a fixture's
    whole snapshot history), not a price anyone could have taken. This page is what
    the operator reads before placing real money by hand.

    Measured at fix time, non-retired bots with n>=40 settled:
      bot_v10_all          17.04% -> 12.07%  (-4.97pp)
      bot_opt_home_lower   -0.86% ->  -4.72% (-3.86pp)
      bot_pin_1x2_home_v1   9.41% ->   9.41% (unchanged)

    Mutation-verified: reverting the wonPnl line to Number(b.odds_at_pick) fails this.
    """
    import os
    base = os.path.join(os.path.dirname(__file__), "..", "..", "odds-intel-web",
                        "src", "app", "(app)", "admin", "shadow-bots")
    detail = os.path.join(base, "[bot]", "page.tsx")
    if not os.path.exists(detail):
        raise AssertionError(f"shadow-bots detail page not found at {detail}")
    src = open(detail, encoding="utf-8").read()

    # 1. The helper must exist and prefer the live price.
    assert "function execOdds(" in src, "detail page must define execOdds()"
    helper = src[src.index("function execOdds("):]
    helper = helper[:helper.index("\n}")]
    assert "odds_at_pick_live" in helper, "execOdds must consider odds_at_pick_live"
    assert "return Number(b.odds_at_pick ?? 0)" in helper, (
        "execOdds must still fall back to odds_at_pick rather than dropping the row"
    )

    # 2. The P&L that feeds ROI must go through it, not read odds_at_pick raw.
    pnl_lines = [l for l in src.splitlines() if "wonPnl" in l and "reduce" in l]
    assert pnl_lines, "could not find the wonPnl reduce that feeds ROI"
    pnl_line = pnl_lines[0]
    assert "execOdds(b)" in pnl_line, (
        f"wonPnl must price winners at execOdds(b); got: {pnl_line.strip()}"
    )
    assert "odds_at_pick" not in pnl_line, (
        f"wonPnl must not read odds_at_pick directly; got: {pnl_line.strip()}"
    )

    # 3. The column has to be selected or execOdds silently always falls back.
    assert "odds_at_pick_live" in src[:src.index("function execOdds(")] or \
           "odds_at_pick_live, model_probability" in src, \
           "odds_at_pick_live must be in the PostgREST select"

    # 4. The basis must be labelled - an unlabelled return figure is what made
    #    the old number misleading in the first place.
    assert "exec" in src.lower(), "the page must say which price basis it shows"

    # 5. Guard that this test is meaningful: the two bases must actually differ
    #    on live data, otherwise it would pass even against a broken page.
    from workers.api_clients.db import execute_query
    row = execute_query(
        """SELECT count(*) n,
                  sum(CASE WHEN odds_at_pick_live IS NOT NULL
                            AND abs(odds_at_pick_live - odds_at_pick) > 0.01
                           THEN 1 ELSE 0 END) differing
             FROM shadow_bets_unique
            WHERE result IN ('won','lost')"""
    )[0]
    assert row["n"] > 0, "no settled shadow rows to validate against"
    assert row["differing"] > 0, (
        "no row has a live price differing from odds_at_pick - the bases are "
        "identical, so this test cannot detect the bug it exists to pin"
    )



@test("COOLBET-DAILY-CAP-RAISE — daily caps must clear real pick volume and stay mutually consistent")
def test_coolbet_daily_caps():
    """The daily caps were the binding constraint on trading, not a safety net.

    Measured 2026-09-05 for bot_coolbet_value_v1: the old cap of 20 turned away
    qualified picks on 9 of the 11 active days in the preceding fortnight —
    46 picks available that day, 65 on 08-30, 69 on 08-29. Both caps bound at the
    same point at a EUR 10 flat stake (20 x 10 = 200), so raising the count alone
    would have moved nothing.

    This test pins three things: the caps clear observed volume, they stay
    consistent with each other at the flat stake, and they remain real ceilings
    rather than being removed outright.
    """
    import importlib.util, os
    path = os.path.join(os.path.dirname(__file__), "place_coolbet_ui.py")
    spec = importlib.util.spec_from_file_location("_place_cb", path)
    mod = importlib.util.module_from_spec(spec)
    try:
        spec.loader.exec_module(mod)
    except SystemExit:
        pass

    bets = mod.MAX_BETS_PER_DAY
    stake_cap = mod.MAX_STAKE_PER_DAY

    # 1. Still a real ceiling — never unbounded.
    assert isinstance(bets, int) and bets > 0, "MAX_BETS_PER_DAY must be a positive int"
    assert stake_cap > 0, "MAX_STAKE_PER_DAY must stay a real ceiling"
    assert bets <= 500 and stake_cap <= 5000, (
        "daily caps look removed rather than raised — they are the blast-radius "
        "guard against a UI loop spanning many matches"
    )

    # 2. Must clear the observed daily maximum (69 on 2026-08-29) or it is still
    #    the binding constraint on normal trading rather than a safety net.
    assert bets >= 70, (
        f"MAX_BETS_PER_DAY={bets} does not clear the observed daily maximum of 69 "
        f"qualified picks — the cap would still be truncating normal trading"
    )

    # 3. The two caps must not contradict: at the EUR 10 flat stake the money cap
    #    must not bite before the count cap, or raising the count achieves nothing.
    flat = 10.0
    assert stake_cap >= bets * flat, (
        f"MAX_STAKE_PER_DAY={stake_cap} binds before MAX_BETS_PER_DAY={bets} at a "
        f"EUR {flat:.0f} stake ({bets} x {flat:.0f} = {bets*flat:.0f}) — the money "
        f"cap becomes the real wall and the count raise is inert"
    )

    # 4. Per-match guards must survive — they are what actually addresses the
    #    2026-08-31 incident (19 bets / EUR 190 / -EUR 92.80 on repeated matches).
    assert getattr(mod, "MAX_BETS_PER_MATCH", 0) > 0, "per-match count guard missing"
    assert getattr(mod, "MAX_STAKE_PER_MATCH", 0) > 0, "per-match stake guard missing"
    assert mod.MAX_BETS_PER_MATCH < bets, "per-match guard must be tighter than the daily cap"

    # 5. Only the one vetted bot may ever execute.
    assert mod.EXECUTE_ALLOWED_BOTS == {"bot_coolbet_value_v1"}, (
        "EXECUTE_ALLOWED_BOTS changed — real money may only be placed by the "
        "explicitly vetted bot"
    )



@test("LANDING-PERF-ROI-BASIS — public ROI must be priced at executable odds, with an interval")
def test_landing_perf_roi_basis():
    """The public headline and /api/v1/track-record priced ROI off odds_at_pick.

    odds_at_pick is a MAX() high-water mark across a fixture's whole snapshot
    history (STALE-BEST-ODDS), not a price anyone could take. Measured on the
    API's own cohort (calibrated+beta+active, non-inplay, pre-match markets,
    since 2026-05-04, n=738): published +17.39% vs executable +13.10%, a
    -4.29pp restatement.

    Also pins the interval: unit-return sd is ~1.4, so n=738 still leaves
    se +/-5.06pp. A bare ROI reads as precision the record does not have.
    """
    import os, re
    web = os.path.join(os.path.dirname(__file__), "..", "..", "odds-intel-web", "src")
    api = os.path.join(web, "app", "api", "v1", "track-record", "route.ts")
    lib = os.path.join(web, "lib", "engine-data.ts")
    landing = os.path.join(web, "app", "page.tsx")
    for f in (api, lib, landing):
        assert os.path.exists(f), f"missing {f}"
    api_src = open(api, encoding="utf-8").read()
    lib_src = open(lib, encoding="utf-8").read()
    land_src = open(landing, encoding="utf-8").read()

    # 1. Shared helper exists and prefers the live price.
    assert "export function execOdds(" in lib_src, "engine-data must export execOdds"
    assert "export function execPnl(" in lib_src, "engine-data must export execPnl"

    # 2. Combos must NOT be repriced off a single leg's price.
    ep = lib_src[lib_src.index("export function execPnl("):]
    ep = ep[:ep.index("\nexport ")] if "\nexport " in ep else ep[:2000]
    assert "combo_legs" in ep, "execPnl must leave combo bets on their stored pnl"

    # 3. The public HEADLINE loop specifically must price at executable odds.
    #    Checking the whole file is not enough: the per-bet ledger also calls
    #    execOdds, so a file-wide substring check passes even when the headline
    #    aggregate is reverted. Scope the assertion to the aggregate block.
    start = api_src.index("let total = 0;")
    end = api_src.index("function median(")
    agg_block = api_src[start:end]
    assert "pnl +=" in agg_block, "could not locate the headline P&L accumulation"
    pnl_stmt = [l for l in agg_block.splitlines() if "pnl +=" in l][0]
    odds_var = pnl_stmt.split("FLAT_STAKE * (")[1].split(" -")[0].strip()
    decl = [l for l in agg_block.splitlines()
            if f"const {odds_var} =" in l or f"let {odds_var} =" in l]
    assert decl, f"could not find the declaration of `{odds_var}` in the headline loop"
    assert "execOdds(" in decl[0], (
        f"the headline ROI is computed from `{odds_var}`, which is not execOdds-derived: "
        f"{decl[0].strip()}"
    )
    assert "odds_at_pick_live" in agg_block, (
        "the headline aggregate must consider odds_at_pick_live"
    )
    assert "odds_at_pick_live" in api_src, "the API must select odds_at_pick_live"

    # 4. The headline must ship with an interval and a stated basis.
    for key in ("roi_ci_low_pct", "roi_ci_high_pct", "roi_se_pct", "price_basis"):
        assert key in api_src, f"track-record meta must publish {key}"
    assert "roi_ci_low_pct" in land_src and "95% CI" in land_src, (
        "the landing hero must render the confidence interval next to the ROI"
    )

    # 5. No surviving raw-odds ROI arithmetic in the API.
    bad = re.findall(r"FLAT_STAKE \* \(Number\(r\.odds_at_pick[^_]", api_src)
    assert not bad, f"raw odds_at_pick still used for ROI arithmetic: {bad}"

    # 6. Meaningfulness guard: the two bases must actually differ on the real
    #    public cohort, else this test could pass against a broken app.
    from workers.api_clients.db import execute_query
    r = execute_query(
        """SELECT count(*) n,
             sum(CASE WHEN sb.result='won' THEN 10*(sb.odds_at_pick-1) ELSE -10 END) old_pnl,
             sum(CASE WHEN sb.result='won'
                 THEN 10*(COALESCE(NULLIF(sb.odds_at_pick_live,0),sb.odds_at_pick)-1)
                 ELSE -10 END) new_pnl
           FROM simulated_bets sb JOIN bots bt ON bt.id=sb.bot_id
          WHERE bt.maturity_label IN ('calibrated','beta','active')
            AND bt.name NOT LIKE 'inplay_%'
            AND sb.market IN ('1x2','over_under_25','o/u','btts')
            AND sb.result IN ('won','lost')
            AND sb.created_at >= '2026-05-04'"""
    )[0]
    assert r["n"] > 0, "no public-cohort rows to validate against"
    assert float(r["old_pnl"]) != float(r["new_pnl"]), (
        "the two price bases give identical P&L on the public cohort — this test "
        "cannot detect the bug it exists to pin"
    )



if __name__ == "__main__":
    main()
